// Tantra 5 — verses 1419-1572 — scraped from tamilnation.org
export const VERSES_T5: Verse[] = [
  {
    id: 1420, tantraId: 5, verseNumber: 1419,
    tamil: `ஊரும் உலகமும் ஓக்கப் படைக்கின்ற
பேரறி வாளன் பெருமை குறித்திடின்
மேருவும் மூவுல காளி யிலங்கெழுந்
தாரணி நால்வகைச் சைவமு மாமே`,
    transliteration: `ūrum ulakamum ōkkap paṭaikkiṉṟa
pēraṟi vāḷaṉ perumai kuṟittiṭiṉ
mēruvum mūvula kāḷi yilaṅkeḻun
tāraṇi nālvakaic caivamu māmē`,
    english: `1419: Four Paths of Saivam
The Lord created earth in wisdom infinite
And He made it abode of man
How shall I sing His Majesty!
He is mighty as Mount Meru,
From whence He sways the three worlds;
And He is the Four Paths of Saivam too here below.`,
    elaborationEnglish: `The Lord created the world, the place of man.

He holds power over the Three Worlds. He is the four paths,

of Saivam too(Chariya, Kriya, Yoga and Jnana). It is impossible to praise Him. adequately. He was great as Mount Meru.

Esoterically explained. Mount Meru is the universal hub, the support of all worlds. It.is the ‘central mountain’ of Hindu and Buddhist cosmography, around which our cosmos is arranged in seven concentric circles of oceans separated by intervening concentric circles of golden mountains. We may possibly regard it, like the ‘central of Western astronomy, as the gravitational centre of the known universe.

The special column, the central support of the human body structure is; analagously, in the Tantras and in the works on yoga as the Mount Meru of men in the microcosm.

Mount Meru is the king of mountains.

The Sushumna nadi is the chief orthedian nerve situated in the hollow of the spinal column (Sanskrit—Brahmadanda) the Mt. Meru of the human body—man being regarded as the microcosm of the macrocosm.

Vide “‘The Tibetian Book of the Dead,’’ translated by W.G. Eyans-Wentz, pp.63-65, 146, 147, 158-9, 215. (Editor’s note: notes 6, 7 & 8 are strictly a Meikandar interpretation of the following mantra.)

Note: The translator has chosen here to group the first

four subheadings under the title, “Suddha Saivam,’ whereas in the Tirumantiram the verses are categorized under these headings: Suddha Saivam, Asuddha Saivam, Marga Saivam and Kadum Suddha Saivam. Also the order of some of those verses had been rearranged. They now follow the original numeration of the Tirumantiram.`,
    elaborationTamil: `அனைத்து உயிர்களையும் அவை இருக்கின்ற உலகத்தையும் ஒன்றாக கலந்து நின்று இயக்குகின்ற பேரறிவு ஞானமாக இருக்கின்ற இறைவனின் பெருமைகளை குறித்து சொல்லப் போனால் அனைத்து சக்திகளின் மொத்த உருவமாகிய மேரு மலையயும் மேலோகம் பூலோகம் பாதாள லோகம் ஆகிய முன்று உலகங்களையும் ஆளுகின்ற இறைவனை தெளிவாகப் புரிந்து கொள்ளும் படி அவனிடமிருந்தே வெளிவந்து அவனை அறிவதற்கு முயலுகின்ற அடியவர்களுக்கு ஆதார இடமாக இருக்கின்ற நான்கு வகையான நெறிமுறைகளே சைவம் என்று அழைக்கப்படும் பெருமைக்கு உரியதாகும். குறிப்பு: இறைவனை உணர்ந்து அடைவதற்கு அவனால் அருளப்பட்ட நான்கு விதமான நெறிமுறைகளே சைவம் ஆகும். அந்த சைவ நெறிமுறைகளை அறிந்து கொண்டவர்கள் சைவர்கள் ஆவார்கள்.`,
  },
  {
    id: 1421, tantraId: 5, verseNumber: 1420,
    tamil: `சத்தும் அசத்துஞ் சதசத்துந் தான்கண்டு
சித்தும் அசித்துஞ் சேர்வுறா மேநீத்த
சுத்தம் அசுத்தமுந் தோய்வுறா மேநின்று
நித்தம் பரஞ்சுத்த சைவர்க்கு நேயமே`,
    transliteration: `cattum acattuñ catacattun tāṉkaṇṭu
cittum acittuñ cērvuṟā mēnītta
cuttam acuttamun tōyvuṟā mēniṉṟu
nittam parañcutta caivarkku nēyamē`,
    english: `1420: School of Suddha Saivam
Those who tread the path of Suddha Saivam
Stand aloft,
Their hearts intent on Eternal Para;
Transcending Worlds of Pure and Impure Maya,
Where Pure Intelligence consorts not with Base Ignorance,
And the lines that divide Real, Unreal and Real-Unreal
Are discerned sharp.`,
    elaborationEnglish: `1} Cosmic Being

2) Pure or suddha maya comprises the six highest tattva categories in the evolutionary scale.

3) Impure or asuddha maya includes the remaining thirty tattvas.

Others divide maya or matter in evolution into the six pure categories (suddha maya), six pure/impure categories (suddha/asuddha maya), and twenty-four impure categories (asuddha maya).

4) Chit or spirit

5) Achit or matter

6) Sat or God (Pati)

7) Asat or matter (pasam) 8) Sat/asat or soul (pasu)

Suddha Siddhanta is, in other words, Vedanta. The Suddha Siddhantins receive the constant vision by scaling the heights of the nada sphere and attain perfection in Nadanta. They are capable of distinquishing between the real, the unreal and the real/unreal.`,
    elaborationTamil: `நிலையானதாகிய சிவமும் நிலையில்லாததாகிய உடலும் நிலையில்லாத உடலுக்குள் நிலையாக நிற்கின்ற ஆன்மாவும் ஆகிய இவை மூன்றையும் கண்டு உணர்ந்தும், உலக அறிவும் அறியாமையும் சேர்ந்து விடாமல் அதிலிருந்து விலகி இருந்தும், சுத்த மாயை அசுத்த மாயை ஆகிய இரண்டிலும் மயங்கி விடாமல் உண்மை ஞானத்தில் நின்றும், எப்பொழுதும் பரம்பொருளாகிய இறைவனின் அதி சுத்த நிலையில் இருப்பதே சைவர்களின் பேரன்பு ஆகும். குறிப்பு: சைவ நெறிமுறைகளை முறையாகப் பின்பற்றி சடங்குகளில் சிக்கிக் கொள்ளாமல் சம்பிரதாயங்களைக் கடந்து இறைவனிடம் அன்பு செலுத்துபவர்களே சுத்த சைவர்கள் ஆவார்கள்.`,
  },
  {
    id: 1422, tantraId: 5, verseNumber: 1421,
    tamil: `கற்பன கற்றுக் கலைமன்னு மெய்யோகம்
முற்பத ஞான முறைமுறை நண்ணியே
சொற்பத மேவித் துரிசற்று மேலான
தற்பரங் கண்டுளோர் சைவசித் தாந்தரே`,
    transliteration: `kaṟpaṉa kaṟṟuk kalaimaṉṉu meyyōkam
muṟpata ñāṉa muṟaimuṟai naṇṇiyē
coṟpata mēvit turicaṟṟu mēlāṉa
taṟparaṅ kaṇṭuḷōr caivacit tāntarē`,
    english: `1421: Suddha Saivam is Saiva Siddhanta
Having learned all that learned must be,
Having practised all Yoga that have to be,
They, then, pursue the path of Jnana in gradation sure;
And so pass into the world of Formless Sound beyond;
And there, rid of all impurities,
Envision the Supreme, the Self-created;
They, forsooth, are the Saiva Siddhantins true.`,
    elaborationEnglish: `The path of Suddha Saivam leads to the supreme pure state, devoid of all base ignorance. Yoga leads Saiva siddhantins into the path of jnana, and to pass into the sphere of formless sound. Verily, that is the goal of Saiva Siddhanta, to be rid of all impuntties.

Mular’s Saiva Siddhanta is nothing other than Suddha Saivam as he expounds it in 1420.`,
    elaborationTamil: `இறைவனை அடைய வேண்டியதற்கு கற்க வேண்டிய கல்விகள் அனைத்தையும் கற்றுக் கொண்டு அதன் மூலம் பெற்ற கலை அறிவின் மிகவும் உன்னதமான உச்ச நிலையில் உண்மையான யோகத்தை அறிந்து கொண்டு அந்த அறிவிற்கு முதல் மூல தன்மையாக இருக்கின்ற ஞானத்தை அடைய வேண்டிய முறைகளை அறிந்து கொண்டு அந்த முறைகளை முறைப்படி கடைபிடித்து அதன் மூலம் அந்த ஞானத்தை பெற்றுக் கொண்டு தாம் சொல்லுகின்ற வாக்கில் சத்தியத்தின் தன்மையை கடைபிடித்து தம்மிடம் இருக்கும் அழுக்குகளான மும்மலங்களும் நீங்கப் பெற்று அனைத்திற்கும் மேலாக தானாகவே இருக்கின்ற பரம்பொருளை தரிசித்து அதை தமக்குள்ளேயே உணர்ந்து இருப்பவர்களே சைவ சிந்தாந்தர்கள் ஆவார்கள். குறிப்பு: சைவ நெறிமுறைகளின் மூலம் இறைவனை அடைந்தவர்களே சைவ சிந்தாந்தர்கள் ஆவார்கள்.`,
  },
  {
    id: 1423, tantraId: 5, verseNumber: 1422,
    tamil: `வேதாந்தஞ் சுத்தம் விளங்கிய சித்தாந்த
நாதாந்தங் கண்டோர் நடுக்கற்ற காட்சியர்
பூதாந்த போதாந்த மாதுப் புனஞ்செய்ய
நாதாந்த பூரணர் ஞானநே யத்தரே`,
    transliteration: `vētāntañ cuttam viḷaṅkiya cittānta
nātāntaṅ kaṇṭōr naṭukkaṟṟa kāṭciyar
putānta pōtānta mātup puṉañceyya
nātānta pūraṇar ñāṉanē yattarē`,
    english: `1422: Suddha Siddhanta is Vedanta
Suddha Siddhanta is Vedanta;
They who have scaled the heights of Nada sphere
Have verily had the Vision Unwavering;
Comprehending Tattvas from world of elemental matter
To the Finite End of Jnana (Bhodanta)
They become Perfection in Nadanta;
They verily are the ardent seekers of Jnana.`,
    elaborationEnglish: `Mular equates his Saiva Siddhanta with Vedantd, which is not to be confused with the . Vedanta of the schools of Sankaracarya,. Ramanujacarya, etc. Bhodanta is ‘quite apparently a reference to the ‘Bhodi’ of Buddhism. By Nadanta is meant apparently the Mimamsa and Spanda schools which emphasize the sound aspect of the Ultimate.`,
    elaborationTamil: `வேதங்களின் எல்லையாக இருக்கின்றவனும் மும்மலங்களும் நீங்கிய பரிசுத்தமான நிலையில் விளங்குகின்ற எண்ணங்களின் எல்லையாக இருக்கின்றவனும் நாதத்தின் எல்லையாக இருக்கின்றவனும் ஆகிய இறைவனை கண்டு தரிசித்தவர்கள் அசைகின்ற எண்ணங்கள் இல்லாமல் எப்போதும் தரிசித்துக் கொண்டே இருக்கின்றவர்கள். ஐந்து பூதங்களுக்கும் எல்லையாக இருக்கின்றவனும் கற்றுக் கொடுக்கின்ற அனைத்து ஞானத்திற்கும் எல்லையாக இருக்கின்றவனும் ஆகிய இறைவனாகவே ஆகுகின்ற பக்குவத்தை பெறுவதற்கான செயல்களை செய்து நாதத்தின் எல்லையாக இருக்கின்ற இறைவனை பரிபூரணமாக உணர்ந்து கொள்பவர்களே பேரறிவு ஞானமாகவும் பேரன்பாகவும் ஒன்றாக கலந்து இருப்பவர்கள் ஆவார்கள். குறிப்பு: இறைவனை அடைந்து அவனது பேரறிவு ஞானமாகவும் பேரன்பாகவும் ஒன்றாக கலந்து இருப்பவர்களே ஞான நேயத்தர்கள் ஆவார்கள்.`,
  },
  {
    id: 1424, tantraId: 5, verseNumber: 1423,
    tamil: `இணையார் திருவடி ஏத்துஞ் சீரங்கத்
தினையார் இணைக்குழை யீரணை முத்திரை
குணமா ரிணைக்கண்ட மாலையுங் குன்றா
தணைவாஞ் சரியை கிரியையி னார்க்கே`,
    transliteration: `iṇaiyār tiruvaṭi ēttuñ cīraṅkat
tiṉaiyār iṇaikkuḻai yīraṇai muttirai
kuṇamā riṇaikkaṇṭa mālaiyuṅ kuṉṟā
taṇaivāñ cariyai kiriyaiyi ṉārkkē`,
    english: `1423: Path of Chariya-Kriya
They who walk the twin paths of Chariya and Kriya
They ever praise the twin Feet of Lord;
On their limbs they wear holy emblems
The twin rings in ear lobes
The twin rudraksha garland around the neck,
And adopt the twin Mudra
All, in amiable constancy.`,
    elaborationEnglish: `”Presumably, the rishaba (bull) mudra and sula (trident) mudra. Vide Thevaram of St. Tirunavukkarasar beginning with

Ponnar Tiruvadi

Mantras 1423 & 1424

They who tread the twin paths of Chariya and Kriya remain amidable constancy in thought of Siva, and adore the Glorious Feet of the Lord. Their holy bodies adorned with the appropriate insignia, they sit still and impassive, chanting mantras. Thus their souls ascend to Siva.`,
    elaborationTamil: `இறைவனுக்கு இணையாக பேரழகு கொண்ட மரியாதைக்கும் மேன்மைக்கும் உரிய திருவடிகளை போற்றி வணங்கும் சாதகர்கள் சீரும் சிறப்புமாக ஒழுக்கத்துடன் பராமரிக்கும் தமது உடலில் இறைவனுக்கு இணையாக அழகாக இருக்கின்ற இரண்டு குண்டலங்களை தமது காதுகளில் அணிந்து கொண்டும் இறைவனோடு எப்போதும் சேர்த்தே வைத்து இருக்கின்ற இறைவனது இரண்டு சின்னங்களாகிய நந்தியும் சூலமும் வைத்தும் முறையான கயிற்றில் அழகாக கோர்க்கப்பட்டு இறைவனுக்கு இணையாக இருக்கின்ற ருத்திராட்ச மாலையை கழுத்தில் அணிந்து கொண்டும் இவை அனைத்தும் இறைவனுக்கு இணையாக இருக்கின்றது என்ற உறுதியான எண்ணத்தில் சிறிதளவும் குறைவு இல்லாமல் எப்போதும் தம்மோடு சேர்த்தே வைத்துக் கொண்டு உடலால் பூஜித்தும் உடலாலும் மனதாலும் வழிபட்டும் இருக்கின்ற சாதகர்களே அசுத்த சைவமாகிய சரியை கிரியை ஆகிய இரண்டு வழிமுறைகளைப் பின்பற்றுகிறவர்கள் ஆவார்கள்.`,
  },
  {
    id: 1425, tantraId: 5, verseNumber: 1424,
    tamil: `காதுப்பொ னார்ந்த கடுக்கன் இரண்டுசேர்த்
தோதுந் திருமேனி யுட்கட் டிரண்டுடன்
சோதனை செய்து துவாதெச மார்க்கராய்
ஓதி யிருப்பார் ஒருசைவ ராகுமே`,
    transliteration: `kātuppo ṉārnta kaṭukkaṉ iraṇṭucērt
tōtun tirumēṉi yuṭkaṭ ṭiraṇṭuṭaṉ
cōtaṉai ceytu tuvāteca mārkkarāy
ōti yiruppār orucaiva rākumē`,
    english: `1424: Path of Dvadasa Marga Saivam (Yoga)
In the lobes of their ear,
They wear the double ring of gold,
Around their necks
They wear the double string of rudraksha;
Their holy body thus adorned
They sit quiescent, chanting mantras
And feel their way inward
Through the twelve steps in the ladder
Of the Soul's ascension to Siva
Of such are the peerless school of Saivas.`,
    elaborationEnglish: `The reference is to the 12 states of consciousness experience in the samadhi state, The twelfth state is the Final State of Void from whose bourne there is no retuming. For elaboration of the eleven consciousness experiences (avastas) preceding the twelfth, vide Tantra Eight For elaboration on the twelfth stage of consciousness experience, vide Mantra 1489, infra.

The jnani holds mastery over the sacred lore on earth and the sixty-four attainments. He receives the vision of all worlds, inclusive of the ‘land of Mauna’. He sees the goal of all Vedas, and the Lord Himself.`,
    elaborationTamil: `தனது காதுகளில் ஒளி வீசிப் பிரகாசிக்கும் தங்கத்தால் அழகாக வார்க்கப்பட்ட கடுக்கன்கள் இரண்டையும் காதோடு சேர்த்து அணிந்து கொண்டு இறைவனது திருநாமத்தை ஓதுகின்ற தமது மரியாதைக்கும் மேன்மைக்கும் உரிய உடலுக்கு உள்ளே இறைவனது திருநாமத்தை ஓதுவதினால் உருவாகுகின்ற சக்திகளை தம்மை சுற்றியே செயல் படுத்தும் பூனூல் மற்றும் அதை மேம்படுத்தி செயல் பட வைக்கும் ருத்திராட்சம் ஆகிய இரண்டு மாலைகளையும் அணிந்து கொண்டு இவற்றின் செயல்பாடுகளை சோதனை செய்து கொண்டே பாடல் #457 இல் உள்ளபடி கழுத்துக்கு கீழே எட்டு அங்குலமும் கழுத்துக்கு மேலே நான்கு அங்குலம் சுற்றிக் கொண்டு இருக்கின்ற மூச்சுக்காற்றுடன் சேர்ந்து அசபையாக மந்திரங்களை உச்சரித்துக் கொண்டே அது சரியாக இயங்குகின்றதா என்பதை ஆராயந்து செயல் படுத்துபவர்களே அசுத்த சைவம் வழிமுறையை கடைபிடிக்கும் சைவர்கள் ஆவார்கள்.`,
  },
  {
    id: 1426, tantraId: 5, verseNumber: 1425,
    tamil: `கண்டங்கள் ஒன்பதுங் கண்டவர் கண்டனர்
கண்டங்கள் ஒன்பதுங் கண்டாய் அரும்பொருள்
கண்டங்கள் ஒன்பதுங் கண்டவர் கண்டமாங்
கண்டங்கள் கண்டோர் கடுஞ்சுத்த சைவரே`,
    transliteration: `kaṇṭaṅkaḷ oṉpatuṅ kaṇṭavar kaṇṭaṉar
kaṇṭaṅkaḷ oṉpatuṅ kaṇṭāy arumporuḷ
kaṇṭaṅkaḷ oṉpatuṅ kaṇṭavar kaṇṭamāṅ
kaṇṭaṅkaḷ kaṇṭōr kaṭuñcutta caivarē`,
    english: `1425: Pure Suddha Saivam (Jnana)
They who transcended the nine spiritual Centers
Verily saw God,
Whom the nine continents seek;
They saw the Continent beyond all continents
They, indeed, are the Pure Suddha Saivas.`,
    elaborationEnglish: `Suddha Saivas transcending the nine spiritual centres see tht continent beyond the continents, and verily behold God.

These are as avastas or states of the soul' experience as it travels from the navel to the forehead throug the heart and neck chakra centres. They represent the states of wakefulness, dream, deep sleep, beyond-deep-sleep and so op, For a fuller discussion, vide ''Saiva Siddhanta," bs V. Paranjoti, pp.167-69`,
    elaborationTamil: `பாடல் #867 இல் உள்ளபடி தமக்குள்ளும் தம்மைத் தாண்டியும் இருக்கின்ற 1. மூலாதாரம் 2. சுவாதிஷ்டானம் 3. மணிப்பூரகம் 4. அநாகதம் 5. விசுத்தி 6. ஆக்ஞா 7. சகஸ்ரதளம் 8. துவாதசாந்த வெளி 9. பரவெளி எனும் சந்திர மண்டலம் ஆகிய ஒன்பது சக்தி மயங்களையும் பாடல் #1424 இல் உள்ள பயிற்சியின் படி சாதகம் செய்து கண்டு உணர்ந்து கொண்டவர்களே உண்மையான சக்தி மயங்களை தரிசித்தவர்கள் ஆவார்கள். இவற்றை கண்டு உணர்ந்து கொண்ட சாதகர்கள் அந்த சக்தி மயங்களே கிடைப்பதற்கு மிகவும் அரிய பரம்பொருளான இறையாக இருப்பதை அறிந்து கொள்வார்கள். அதன் பிறகு சாதகத்தை தொடர்ந்து செய்து அந்த சக்தி மயங்களாக இருக்கின்ற இறை சக்தியே தாமாகவும் ஆகி இருப்பதை அவர்கள் உணர்ந்து கொள்வார்கள். இப்படி ஒன்பது சக்தி மயங்களாக இருக்கின்ற இறையை தரிசித்த சாதகர்களே கடுமையான சுத்த நெறியை இந்த உலகிலேயே பின்பற்றும் அசுத்த சைவர்கள் ஆவார்கள்.`,
  },
  {
    id: 1427, tantraId: 5, verseNumber: 1426,
    tamil: `ஞானி புவியெழு நன்னூ லனைத்துடன்
மோன திசையும் முழுஎண்ணெண் சித்தியும்
ஏனை நிலமும் எழுதா மறையீறுங்
கோனொடு தன்னையுங் காணுங் குணத்தனே`,
    transliteration: `ñāṉi puviyeḻu naṉṉū laṉaittuṭaṉ
mōṉa ticaiyum muḻueṇṇeṇ cittiyum
ēṉai nilamum eḻutā maṟaiyīṟuṅ
kōṉoṭu taṉṉaiyuṅ kāṇuṅ kuṇattaṉē`,
    english: `1426: Characteristics of Jnani
The Jnani masters all sacred lore on earth,
And the attainments sixty and four
And espies the Land of Mauna
And all other land besides;
He sees the goal of all Vedas
And sees Lord and himself in union one.`,
    elaborationTamil: `பாடல் #1425 இல் உள்ளபடி சக்தி மயங்களாகிய இறையை இந்த உலகிலேயே உணர்ந்து கொண்ட ஞானியாகிய சாதகர் உலகத்திலுள்ள உயிர்கள் எழுச்சி பெற நன்மையை தருகின்ற நூல்கள் அனைத்தையும் அறிந்து கொள்பவராகவும் பேச்சும் அசைவும் இல்லாத மோன நிலையில் இருந்தாலும் அனைத்து திசைகளிலும் நிகழும் அனைத்தையும் அறிந்தவராகவும் தமது எண்ணம் முழுவதிலும் இறைவனையே வைத்து எட்டு விதமான சித்திகளையும் பெற்றவராகவும் இந்த உலகம் தாண்டி இருக்கின்ற அனைத்து உலகங்களிலுள்ள உயிர்களும் அடைய வேண்டிய இறைவனை வெளிப்படையாக எழுதாமல் உட்பொருளாக மறைத்து வைத்து இருக்கும் வேதங்களையும் அதன் எல்லையாக இருக்கின்ற இறைவனையும் உணர்ந்தவராகவும் அனைத்தையும் ஆளுகின்ற அரசனாக இருக்கின்ற இறைவனோடு தன்னையும் சரிசமமாக பாவிக்கும் குணத்தை கொண்டவராகவும் இருப்பார்.`,
  },
  {
    id: 1428, tantraId: 5, verseNumber: 1427,
    tamil: `பொன்னாற் சிவசாத னம்பூதி சாதனம்
நன்மார்க்க சாதனம் மாஞான சாதனந்
துன்மார்க்க சாதனந் தோன்றாத சாதனஞ்
சன்மார்க்க சாதன மாஞ்சுத்த சைவர்க்கே`,
    transliteration: `poṉṉāṟ civacāta ṉampūti cātaṉam
naṉmārkka cātaṉam māñāṉa cātaṉan
tuṉmārkka cātaṉan tōṉṟāta cātaṉañ
caṉmārkka cātaṉa māñcutta caivarkkē`,
    english: `1427: Jnana Path is for Suddha Saivam
The golden emblems of Siva,
And the holy smear of ashes
Apt are they the insignia
Of those in Saiva Path stand;
But the path of Jnani
Is the path that no evil ever crosses
That his emblem, the holy path of Sanmarga (Jnana)
So beloved of Suddha Saiva.`,
    elaborationEnglish: `Mantras 1427 & 1428

Followers of Saivam wear the golden insignia of Siva and the smear of holy ashes. The path of jnana is Sanmarga, which no evil can obstruct. It is beloved of Suddha Saivam. A perfect jnani is the king of the entire realm of wisdom. He is the sun who pierces the massive lore of Vedanta/Siddhanta. He remains immortal, devoted ever to the Suddha Saiva way.`,
    elaborationTamil: `இறைவனது அம்சமாக இருக்கின்ற மணிகளை (உருத்திராட்சம், துளசிமணி, ஸ்படிகம் போன்றவற்றை) தங்கத்தால் கோர்த்து செய்து அணிந்து கொண்டும் இறையருளுக்கு கருவியாக இருக்கின்ற நறுமணப் பொருள்களை (விபூதி, குங்குமம், சந்தனம், செந்தூரம், நாமம் போன்றவற்றை) பூசிக் கொண்டும் இவற்றை கருவியாக கொண்டு பூஜை எனும் சாதகத்தை செய்கின்ற வழிமுறையானது நன்மையைக் கொடுக்கும் வழிமுறையாகும். இதற்கு கருவியாக இருக்கின்ற மணிகளும் பூசிக்கொள்ளும் நறுமணப் பொருட்களும் பலவிதமான நலங்களை அறிந்து கொள்ளுகின்ற ஞானத்தை கொடுக்கின்ற கருவியாகவும் இருக்கின்றன. தீமையைக் கொடுக்கும் வழிமுறைக்கான கருவி எதுவும் நன்மையின் நெறி வழியே செல்லுகின்ற சாதகருக்கு தடையாக உருவாகாமல் இருக்கவும் இந்த கருவிகள் உதவுகின்றன. இவை அனைத்தும் சத்தியத்தின் வழிமுறையை பின்பற்றி இறைவனை அடைவதற்கு சாதகம் செய்கின்ற சுத்த சைவர்களுக்கு உதவுகின்ற கருவிகளாக இருக்கின்றன.`,
  },
  {
    id: 1429, tantraId: 5, verseNumber: 1428,
    tamil: `கேடறு ஞானி கிளர்ஞான பூபதி
பாடறு வேதாந்த சித்தாந்த பாகத்தின்
ஊடுறு ஞானோ தயனுண்மை முத்தியோன்
பாடுறு சுத்தசை வப்பத்த நித்தனே`,
    transliteration: `kēṭaṟu ñāṉi kiḷarñāṉa pūpati
pāṭaṟu vētānta cittānta pākattiṉ
ūṭuṟu ñāṉō tayaṉuṇmai muttiyōṉ
pāṭuṟu cattacai vappatta nittaṉē`,
    english: `1428: Greatness of Jnani in Suddha Saivam
The blemishless Jnani is king of Wisdom's realm,
He is the Sun, whose beams pierce the massive lore of Vedanta-Siddhanta
His is salvation True
He, the immortal one
And devoted true to Suddha Saiva way.`,
    elaborationTamil: `பாடல் #1427 இல் உள்ளபடி கருவிகளின் மூலம் சாதகம் செய்து தீயவற்றை அறுக்கின்ற ஞானியாகிய சாதகர் கிளர்ந்து எழுகின்ற ஞானத்திற்கு அதிபதியாகவும், பாசமாகிய துன்பங்களை அறுக்கின்ற வேதங்களுக்கு எல்லையாகவும் சித்தங்களுக்கு எல்லையாகவும் இருக்கின்ற இறைவனின் திருவடிகளை தம்மை நாடி வரும் அடியவர்களின் மனதிற்குள் புகுத்தி ஞானத்தை உருவாக்குகின்ற நுட்பமான முக்தி நிலையில் இருப்பவராகவும், பாசமாகிய துன்பத்தை அனுபவித்தாலும் அதனால் சிறிதும் பாதிக்கப் படாமல் சுத்தமான சைவ நெறிமுறையைக் கடைபிடித்து எப்போதும் பக்தியிலேயே நிலைத்து நிற்பவராகவும் இருப்பார்.`,
  },
  {
    id: 1430, tantraId: 5, verseNumber: 1429,
    tamil: `ஆகமம் ஒன்பான் அதிலான நாலேழு
மோகமில் நாலேழு முப்பேத முற்றுடன்
வேகமில் வேதாந்த சித்தாந்த மெய்மேயொன்
றாக முடிந்த வருஞ்சுத்த சைவமே`,
    transliteration: `ākamam oṉpāṉ atilāṉa nālēḻu
mōkamil nālēḻu muppēta muṟṟuṭaṉ
vēkamil vētānta cittānta meymēyoṉ
ṟāka muṭinta varuñcutta caivamē`,
    english: `1429: Conclusions of Suddha Saivam
Nine are the Agamas of yore
In time expanded into twenty and eight,
They then took divisions three
Into one truth of Vedanta-Siddhanta to accord
That is Suddha Saiva, rare and precious.`,
    elaborationEnglish: `The nine Agamas of yore, which expanded into twenty-eight, took three divisions (Mantra, Tantra and Upadesa) to accord into one, the truth of Vedanta/Siddhanta, unique and precious of Suddha Saiva.

By stating that the Agamas provide the base for both Vedanta and Siddhanta (which are equated by him), Mular makes it clear that the Vedanta he has in mind is not the same as that of the Acaryas. The one thing common to Vedanta, Siddhanta and Bodhanta is they all consider Knowledge as the ultimate path to Liberation.`,
    elaborationTamil: `இறைவனை அடைவதற்கு வழிவகுக்கும் ஆகமங்கள் பாடல் #62 இல் உள்ளபடி ஒன்பது வகையாகவும் அவற்றின் முழுமையான சொத்தாக பாடல் #57 இல் உள்ளபடி 28 ஆகமங்களாகவும் இருக்கின்றன. எந்தவிதமான ஆசைகளும் இல்லாமல் இந்த 28 ஆகமங்களையும் கற்று உணர்ந்து அவற்றின் பயனால் இறைவனை அடைவதற்கு தடையாக இருக்கின்ற மூன்று விதமான பற்றுக்களை விட்டு விலகுவது எப்படி என்பதை ஆராய்ந்து அறிந்து கொண்டு அதனுடன் சேர்ந்து எந்தவிதமான எண்ணங்களும் இல்லாமல் வேதங்களுக்கு எல்லையாகவும் ஞானத்திற்கு எல்லையாகவும் இருக்கின்ற உண்மைப் பொருளாகிய இறைவனுடன் ஒன்றாக கலந்து தான் எனும் நிலை முடிந்து இறைவனும் தானும் வேறு வேறு இல்லை எனும் நிலையை அடைவதே கிடைப்பதற்கு மிகவும் அரிதான பெரும் பேறாகிய சுத்த சைவம் ஆகும்.`,
  },
  {
    id: 1431, tantraId: 5, verseNumber: 1430,
    tamil: `சுத்தம் அசுத்தந் துரியங்கள் ஓரேழுஞ்
சத்தும் அசத்துந் தணந்த பராபரை
உய்த்த பராபரை யுள்ளாம் பராபரை
அத்தன் அருட்சத்தி யாய்எங்கு மாமே`,
    transliteration: `cuttam acuttan turiyaṅkaḷ ōrēḻuñ
cattum acattun taṇanta parāparai
uytta parāparai yuḷḷām parāparai
attaṉ aruṭcatti yāyeṅku māmē`,
    english: `1430: Doctrine of Grace in Suddha Saivam
She transcends the worlds of Matter, Pure and Impure,
And the seven states of Turiya awareness
And the categories of Real and Unreal,
She is Paraparai;
She grants the soul deliverance;
She is ever within;
She is the Lord’s Divine Grace,
The Arul Sakti that is all pervasive.`,
    elaborationEnglish: `She, the Lord’s Divine Grace, and the all-pervasive Arul Sakti, holds superiority over the worlds of matter — pure and impure — the seven states of turiya consciousness, and the categories of real and unrea! She is the Paraparai, who is inherent in Para.`,
    elaborationTamil: `சுத்த மாயையில் இருக்கும் நனவு, கனவு ஆகிய இரண்டு நிலைகளும் அசுத்த மாயையில் இருக்கும் நனவு, கனவு, உறக்கம் ஆகிய மூன்று நிலைகளும் துரியம் துரியாதீதம் ஆகிய இரண்டு நிலைகளும் கூட்டி மொத்தம் ஏழு விதமான நிலைகளையும் அனுபவிக்கும் நிலையாக இருக்கின்ற ஆன்மாவையும் நிலையற்றதாக இருக்கின்ற உடலையும் கடந்து இறைவனும் இறைவியும் சேர்ந்து இருக்கின்ற பரம்பொருளே அனைத்திற்கும் உள்ளே இருந்து இயக்கி அவற்றை மேல் நிலைக்கு கொண்டு செல்கின்ற பரம்பொருளாகும். அதுவே அப்பனாகவும் அருள் மயமாகிய சக்தியாகவும் ஆகி அனைத்துமாகவும் ஆகி இருக்கின்றது. ஏழுவிதமான நிலைகள்: சுத்த மாயை – நனவு – இறைவன் இருக்கின்றான் என்கிற நினைவுடன் இறைவனோடு இருக்கின்ற நிலை. சுத்த மாயை – கனவு – இறைவனுடன் தாமும் சேர்ந்து இருக்கின்றோம் என்ற எண்ணத்தில் இருக்கின்ற நிலை. அசுத்த மாயை – நனவு – உலகத்தில் பார்க்கின்ற அனைத்தையும் உண்மை என்று நினைத்து இருக்கின்ற நிலை. அசுத்த மாயை – கனவு – உலகத்தில் பார்க்காத விஷயங்களையும் உண்மை என்று நினைத்து இருக்கின்ற நிலை. அசுத்த மாயை – உறக்கம் – உலகத்தில் சுய நினைவின்றி மாயையில் மயங்கி இருக்கின்ற நிலை. துரியம் – பேருறக்கம் – இறைவனை மட்டுமே எண்ணிக்கொண்டு உயிர்ப்புடன் செயல் அற்று இருக்கின்ற சமாதி நிலை. துரியாதீதம் – உயிர்ப்படங்கல் – எந்த எண்ணங்களும் செயல்களும் இன்றி உயிரும் அடங்கி இருக்கின்ற சமாதி நிலை.`,
  },
  {
    id: 1432, tantraId: 5, verseNumber: 1431,
    tamil: `சத்தும் அசுத்துந் தணந்தவர் தானாகிச்
சித்தும் அசித்துந் தெரியாச் சிவோகமாய்
முத்தியுள் ஆனந்த சத்தியுள் மூழ்கினார்
சித்தியு மங்கே சிறந்துள தானே`,
    transliteration: `cattum acuttun taṇantavar tāṉākic
cittum acittun teriyāc civōkamāy
muttiyuḷ āṉanta cattiyuḷ mūḻkiṉār
cittiyu maṅkē ciṟantuḷa tāṉē`,
    english: `1431: Sakti's Grace for Jnani in Suddha Saivam
They transcended Categories Real and Unreal
That cognize neither Chit nor Achit
They attuned themselves to Sivoham meditation,
And in Mukti, in the bliss of Sakti
They were immersed deep,
And there
All Siddhis abounded in surpassing prowess.`,
    elaborationEnglish: `The siddhas are immersed in ‘Sivoham’ meditation and attain mukti, the bliss of Sakti. There, they abound in unsurpassed prowess.`,
    elaborationTamil: `நிலையான ஆன்மாவும் நிலையில்லாத உடலையும் கடந்து பாடல் #1430 இல் உள்ளபடி துரியாதீத நிலையில் இருக்கின்ற சாதகர் தானே இறைவனாகி உலக அறிவாலும் அறியாமையாலும் தெரிந்து கொள்ள முடியாத சிவ யோகத்தின் வடிவமாய் முக்தி நிலைக்கு உள்ளே இருக்கின்ற பேரின்பத்தின் சக்திக்கு உள்ளே மூழ்கி இருந்து பேரறிவு ஞானத்தைப் பெற்று அந்த முக்தி நிலைக்குள் மேன்மையுடன் சிறந்து விளங்குகின்றார்.`,
  },
  {
    id: 1433, tantraId: 5, verseNumber: 1432,
    tamil: `தன்னைப் பரனைச் சதாசிவன் என்கின்ற
மன்னைப் பதிபசு பாசத்தை மாசற்ற
முன்னைப் பழமல முன்கட்டை வீட்டினை
உன்னத் தகுஞ்சுத்த சைவர் உபாயமே`,
    transliteration: `taṉṉaip paraṉaic catācivaṉ eṉkiṉṟa
maṉṉaip patipacu pācattai mācaṟṟa
muṉṉaip paḻamala muṉkaṭṭai vīṭṭiṉai
uṉṉat takuñcutta caivar upāyamē`,
    english: `1432: Suddha Saiva Strategy
The Self, Para and the Sadasiva that is Lord,
The categories threePati, Pasu and pasa,
The Immaculate Ancient One,
And the Tattvas that bind Jiva
And the goal of Liberation
On All these in accord contemplate
They, of the path of Suddha Saiva.`,
    elaborationTamil: `சாதகர் தன்னையும் பரம்பொருளாகிய இறைவனையும் சதாசிவமூர்த்தி என்று உணரப்படுகின்ற அசையும் சக்தியும் அசையா சக்தியும் சேர்ந்து செயல்படுகின்ற பதியாகிய இறையையும் பசுவாகிய ஆன்மாவையும் பாசமாகிய பற்றுக்களையும், குற்றம் இல்லாத இறைவனிடமிருந்து ஆசையினால் பிரிந்து வந்த பிறகு குற்றமடைந்து பழமையான காலத்திலிருந்தே தொடர்ந்து வருகின்ற மூன்று விதமான மலங்களையும், நல் வினை தீ வினை ஆகிய இரண்டு விதமான வினைகளாலும் கட்டப் பட்டு இருக்கும் ஆன்மா வசிக்கும் வீடாகிய இந்த உடலையும் தனக்கு உள்ளேயே ஆராய்ந்து பரிபூரணமாக உணர்ந்து கொள்வதற்கு ஏதுவாக இருப்பது சுத்தமான சைவத்தை கடைபிடிக்கும் சைவர்களின் வழியாகிய மார்க்க சைவமே ஆகும்.`,
  },
  {
    id: 1434, tantraId: 5, verseNumber: 1433,
    tamil: `பூரணம் தன்னிலே வைத்தற்ற வப்போதே
மாரண மந்த மதித்தானந் தத்தோடு
நேரென ஈராறு நீதி நெடும் போகங்
காரண மாஞ்சுத்த சைவர்க்குக் காட்சியே`,
    transliteration: `pūraṇam taṉṉilē vaittaṟṟa vappōtē
māraṇa manta matittāṉan tattōṭu
nēreṉa īrāṟu nīti neṭum pōkaṅ
kāraṇa māñcutta caivarkkuk kāṭciyē`,
    english: `1433: Vision of Suddha Saivam Path
They fixed their thoughts on Perfection
And lost consciousness of Self's existence
They have reached the End of Vedas;
They followed the Twelve-Way route
To divine rapture
That their vision is,
Those of Suddha Saiva Way.`,
    elaborationEnglish: `Mantras 1433 & 1434

Concentrating the thought on perfection and becoming unconscious of self's existence leads siddhas to reach the end of the Vedas, and by following the twelve way route they receive the vision of the Suddha Saiva way. Jnana stills the flow of thought which even yogis find it difficult to practise, and through destruction of the self, he finds identity in Siva.`,
    elaborationTamil: `பாடல் #1432 இல் உள்ள அனைத்து தத்துவங்களையும் முறைப்படி தமக்குள் பரிபூரணமாக ஆராய்ந்து உணர்ந்து ஆதியிலிருந்தே சேர்த்து வைத்து இருக்கும் மும்மலங்களங்களையும் நீக்குகின்ற இறைவன் அருளிய போதனைகளால் வேதத்திற்கு எல்லையாக இருக்கின்ற இறைவனை தொழுது வணங்கி இறையருளால் தனக்குள் பெற்ற பேரின்பத்தில் சீராக இருக்கும் படி மொத்தம் 12 அங்குலமும் (கழுத்துக்கு கீழே எட்டு அங்குலம் கழுத்துக்கு மேலே நான்கு அங்குலம்) மூச்சுக்காற்றை மந்திரங்களோடு சேர்த்து சுவாசிக்கும் முறைப்படி சுவாசித்து நீண்ட காலம் சாதனை செய்கின்ற சாதகங்களுக்கு காரணமாக இருப்பது மார்க்க சைவ முறைப்படி நடக்கும் சுத்தமான சைவர்கள் தமக்குள் பரிபூரணமாக ஆராய்ந்து பெற்ற இறை காட்சியே ஆகும்.`,
  },
  {
    id: 1435, tantraId: 5, verseNumber: 1434,
    tamil: `மாறாத ஞான மதிப்பற மாயோகந்
தேறாத சிந்தையைத் தேற்றிச் சிவமாக்கிப்
பேறான பாவனை பேணி நெறிநிற்றல்
கூறாகு ஞானி சரிதை குறிக்கிலே`,
    transliteration: `māṟāta ñāṉa matippaṟa māyōkan
tēṟāta cintaiyait tēṟṟic civamākkip
pēṟāṉa pāvaṉai pēṇi neṟiniṟṟal
kūṟāku ñāṉi caritai kuṟikkilē`,
    english: `1434: Way of Jnani
He stills the incessant flow of thought
That even Yoga’s severity stills not,
With Jnana he effaces the Self
And in Bhava identifies with Siva;
That in brief is worthy Jnani’s story.`,
    elaborationTamil: `எந்தக் காலத்திலும் மாறாத உண்மையான ஞானத்தை தமக்குள்ளே ஆராய்ந்து அறிந்து அந்த அறிவால் பரம் பொருளை அடையும் மாபெரும் யோகத்தை செய்வதும் அதன் பயனால் தெளிவாக இறையை உணர்ந்து கொள்ளாத சிந்தனையை தெளிவு படுத்தி சிவம் எனும் பேரன்பாக ஆக்குவதும் அதன் பயனால் கிடைப்பதற்கு மிகவும் அரிய பேறாக இருக்கும் அருள் பாவனைகளை பெற்று அவற்றை கடைபிடித்து அருள் வழியே மாறாமல் நிற்பதும் ஆகிய இந்த மூன்றும் மார்க்க சைவத்தின் ஞான வழியைக் கடைபிடிக்கும் சைவர்கள் குறிப்பாக வைத்து சாதகம் செய்கின்ற சரியை எனும் முறைக்கு அங்கங்கள் ஆகும்.`,
  },
  {
    id: 1436, tantraId: 5, verseNumber: 1435,
    tamil: `வேதாந்தங் கண்டோர் பிரமமித் தியாதரர்
நாதாந்தங் கண்டோர் நடுக்கற்ற யோகிகள்
வேதாந்த மல்லாத சித்தாந்தங் கண்டுளோர்
சாதா ரணமன்ன சைவர் உபாயமே`,
    transliteration: `vētāntaṅ kaṇṭōr piramamit tiyātarar
nātāntaṅ kaṇṭōr naṭukkaṟṟa yōkikaḷ
vētānta mallāta cittāntaṅ kaṇṭuḷōr
cātā raṇamaṉṉa caivar upāyamē`,
    english: `1435: Vedanta is Siddhantin's Finite Goal
The Vedantins envision Brahman
Adepts are they in Brahmaic art;
They hold all phenomenon as illusion entire,
Those who envision Nadanta
Are yogis unwavering;
But Siddhanta that accords not with Vedanta,
Is the common Saiva's lot.`,
    elaborationTamil: `வேதத்திற்கு எல்லையாக இருக்கின்ற பரம்பொருளை கண்டு அறிந்து கொண்டவர்கள் மிகவும் உன்னதமான நிலையில் மெய் ஞானம் உலக ஞானம் ஆகிய அனைத்தையும் கற்று அறிந்தவர்கள் ஆவார்கள். நாதத்திற்கு எல்லையாக இருக்கின்ற பரம்பொருளை கண்டு அறிந்து கொண்டவர்கள் சித்தத்தில் நடுக்கம் சிறிதும் இல்லாமல் எப்போதும் இறைவனையே சிந்தித்து கொண்டு இருக்கும் யோகிகள் ஆவார்கள். இப்படி இல்லாமல் வேதத்திற்கு எல்லையாக இருக்கின்ற பரம்பொருளை அறிந்து கொள்ளாத வெறும் உலக அறிவுக்கு எல்லையைக் கண்டு இருக்கின்ற சைவர்கள் சாதாரணம் என்று சொல்லப்படும் பொதுவான சைவர்களின் வழியையே கடை பிடிக்கின்றவர்கள் ஆவார்கள். குறிப்பு: வேதத்திற்கும் நாதத்திற்கும் எல்லையாக இருக்கின்ற பரம்பொருளை அறிந்து கொள்ளாமல் வெறும் உலக கல்வியை மட்டும் அறிந்து கொண்டு சைவத்தை கடைபிடிப்பவர்கள் சாதாரண சைவர்கள் ஆவார்கள். வேதத்திற்கும் நாதத்திற்கும் எல்லையாக இருக்கின்ற பரம்பொருளை அறிந்து கொண்டு மார்க்க சைவத்தை முறைப்படி கடைபிடிப்பவர்கள் உண்மையான மார்க்க சைவர்கள் ஆவார்கள்.`,
  },
  {
    id: 1437, tantraId: 5, verseNumber: 1436,
    tamil: `விண்ணினைச் சென்றணு காவியன் மேகங்கள்
கண்ணினைச் சென்றணு காப்பல காட்சிகள்
எண்ணினைச் சென்றணு காம லெணப்படும்
அண்ணலைச் சென்றணு காபசு பாசமே`,
    transliteration: `viṇṇiṉaic ceṉṟaṇu kāviyaṉ mēkaṅkaḷ
kaṇṇiṉaic ceṉṟaṇu kāppala kāṭcikaḷ
eṇṇiṉaic ceṉṟaṇu kāma leṇappaṭum
aṇṇalaic ceṉṟaṇu kāpacu pācamē`,
    english: `1436: God is Beyond Reach of Pasu and Pasa Knowledge
High be the clouds that soar
They never shall touch the heaven's roof;
Varied be the sights that loom
They never shall touch the eye's orbs;
Even so,
Neither Pasu nor Pasa shall reach Him,
Whom contemplation scarce comprehends.`,
    elaborationTamil: `பரந்து விரிந்து இருக்கின்ற வானத்தில் எவ்வளவுதான் உயரே மேகங்கள் சென்றாலும் அவை விண்ணுலகத்தை சென்று அடைவதில்லை. பல விதமான காட்சிகளைக் கண்டாலும் கண்களில் அந்தக் காட்சிகள் வந்து ஒட்டிக் கொள்வதில்லை. அது போலவே உலகத்தில் அறிந்தவற்றையே எண்ணிக் கொண்டு இருக்கின்ற எண்ணங்களால் உண்மை ஞானமாக இருக்கின்ற இறைவனை சென்று அடைய முடியாதபடி பாசமானது ஆன்மாவை தடுத்துக் கொண்டு இருக்கின்றது. ஆகவே இறைவனை அடைய வேண்டுமென்றால் மார்க்க சைவத்தின் வழியைக் கடை பிடித்து அதன் பயனால் பாசத்தளை நீங்கி உண்மை ஞானமாக இருக்கின்ற இறைவனை அடையலாம்.`,
  },
  {
    id: 1438, tantraId: 5, verseNumber: 1437,
    tamil: `ஒன்றும் இரண்டும் இலதுமாய் ஒன்றாக
நின்று சமய நிராகார நீங்கியே
நின்று பராபரை நேயத்தைப் பாதத்தாற்
சென்று சிவமாதல் சித்தாந்த சித்தியே`,
    transliteration: `oṉṟum iraṇṭum ilatumāy oṉṟāka
niṉṟu camaya nirākāra nīṅkiyē
niṉṟu parāparai nēyattaip pātattāṟ
ceṉṟu civamātal cittānta cittiyē`,
    english: `1437: Siddhanta is to Unite With Siva
You and He are not two separate
You and He are but one united;
Thus do you stand,
Freed of all sectarian shackles;
Adore the Feet of Paraparai
And with Siva become One;
That the way Siddhanta fulfills.`,
    elaborationTamil: `நான் என்ற ஒன்றை நினைப்பதும் இல்லாமல் நானும் இறைவனும் என்று இரண்டாக நினைப்பதும் இல்லாமல் நானும் இறைவனும் வேறு வேறு என்று நினைப்பதும் இல்லாமல் அனைத்தும் இறைவன் ஒருவன் மட்டுமே எனும் எண்ணத்தில் நின்று உலக நியதிகளில் பல விதமாக இறைவன் என்று உருவாக்கி வைத்து இருக்கும் உருவங்களை எல்லாம் நீக்கி விட்டு உருவமே இல்லாத அன்பில் நின்று பரம்பொருளாகிய இறைவனின் பேரன்பின் வடிவத்தை இறைவனது திருவடியின் அருளினால் சென்று அடைந்து அன்பே சிவமாக ஆகி விடுவதும் சித்தத்தின் எல்லையாக இருக்கின்ற பேரறிவை பெறுவதுமே மார்க்க சைவத்தின் வழிமுறைகள் ஆகும்.`,
  },
  {
    id: 1439, tantraId: 5, verseNumber: 1438,
    tamil: `வேடம் கடந்து விகிர்தன்தன் பால்மேனி
ஆடம் பரமின்றி ஆசாபா சம்செற்றுப்
பாடொன்று பாசம் பசுத்துவம் பாழ்படச்
சாடும் சிவபோ தகர்சுத்த சைவரே`,
    transliteration: `vēṭam kaṭantu vikirtaṉtaṉ pālmēṉi
āṭam paramiṉṟi ācāpā camceṟṟup
pāṭoṉṟu pācam pacuttuvam pāḻpaṭac
cāṭum civapō takarcutta caivarē`,
    english: `1438: Suddha Saivam Defined
They are not for outward form and attire,
They are not for pomp and ceremony,
Uprooting all bond and desire,
Abiding in the Immaculate Lord,
They bring to dire destruction
The Soul’s egoity and its bondage beginningless
Thus they onward leap
With Siva’s light suffused
They, of Suddha Saiva Way.`,
    elaborationTamil: `வெளிப்புற வேடங்கள் எதுவும் இன்றி உலக நியதிகளைக் கடந்து இருக்கின்ற இறைவனின் மேல் மட்டும் எண்ணங்களை வைத்து எந்தவிதமான ஆடம்பரங்களும் இல்லாமல் ஆசைகளையும் பாசங்களையும் நீக்கி விட்டு பதியாகிய இறைவனை அடைவது மட்டுமே குறிக்கோளாகக் கொண்டு பாசத் தளைகளும் இறைவனிடமிருந்து ஆன்மா தனித்து இருக்கும் பசு தத்துவமும் அழிந்து போகும் படி செய்து இறைவனை மட்டுமே சார்ந்து இருந்து இறைவன் அருளிய போதனைகளை முறைப்படி கடை பிடிப்பவரே கடும் சுத்த சைவர்கள் ஆவார்கள்.`,
  },
  {
    id: 1440, tantraId: 5, verseNumber: 1439,
    tamil: `உடலான ஐந்தையும் ஓராறும் ஐந்து
மடலான மாமாயை மற்றுள்ள நீவப்
படலான கேவல பாசந் துடைத்துத்
திடமாய்த் தனையுறல் சித்தாந்த மார்க்கமே`,
    transliteration: `uṭalāṉa aintaiyum ōrāṟum aintu
maṭalāṉa māmāyai maṟṟuḷḷa nīvap
paṭalāṉa kēvala pācan tuṭaittut
tiṭamāyt taṉaiyuṟal cittānta mārkkamē`,
    english: `1439: Teachings of Siddhanta School
The five Tattvas that constitute the body,
The thirty more that together constitute them
And the one Tattva that is yet beyond Pure Maya,
All these they transcend;
The thick layers of primal bondage they dissolve
And of certain, realize the Self
That the way of Siddhantins true.`,
    elaborationTamil: `மனித உடலாக இருக்கின்ற ஐந்து விதமான பஞ்ச பூதங்களையும் அதை ஒன்றின் மேல் ஒன்றாக மூடி இருக்கின்ற ஐந்து வகையான கோசங்களையும் கடந்து நின்று அதையும் தாண்டி விரிந்து இருக்கின்ற சுத்த மாயையும் மற்றும் இருக்கின்ற அனைத்து தத்துவங்களையும் தாண்டிச் சென்று இறைவனை அடைவதற்கு தடையாக மாயையிலேயே மயங்கி இருக்கின்ற கேவல நிலைக்குக் காரணமாக இருக்கின்ற பாசங்களையும் முழுவதுமாக நீக்கி விட்டு உறுதியாக தனக்குள் இருக்கும் இறைவனை மட்டுமே உற்று கவனித்த படியே இருப்பதே சித்தத்தின் எல்லையாக இருக்கின்ற கடும் சுத்த மார்க்கத்தின் வழியாகும். பஞ்ச பூதங்கள்: நிலம் – தசைகளும் எலும்புகளும் நீர் – இரத்தமும் உமிழ் நீரும் நெருப்பு – உணவை செரிக்கும் சூடு காற்று – மூச்சுக் காற்று ஆகாயம் – மனம் புத்தி அறிவு பஞ்ச கோசங்கள்: அன்ன மய கோசம் – உணவால் ஆகிய உறை பிராண மய கோசம் – காற்றால் ஆகிய உறை மனோ மய கோசம் – மனம் / எண்ணங்களால் ஆகிய உறை விஞ்ஞான மய கோசம் – அறிவு / புத்தி ஆகிய உறை ஆனந்த மய கோசம் – பேரின்பத்தால் ஆகிய உறை`,
  },
  {
    id: 1441, tantraId: 5, verseNumber: 1440,
    tamil: `சுத்தச் சிவனுரை தானத்தில் தோயாமல்
முத்தர் பதப்பொருள் முத்திவித் தாமூலம்
அத்தகை யான்மா அரனை அடைந்தற்றாற்
சுத்த சிவமாவ ரேசுத்த சைவரே`,
    transliteration: `cuttac civaṉurai tāṉattil tōyāmal
muttar patapporuḷ muttivit tāmūlam
attakai yāṉmā araṉai aṭaintaṟṟāṟ
cutta civamāva rēcutta caivarē`,
    english: `1440: Goal of Suddha Saivas is to be One With Siva
They tarry not in the Pure Maya Sphere of Siva Tattvas
There they but attain the status of Gods,
But that as a spring board
Their Soul reaches farther out to Siva Him-self
And merging in His union, Self-effacing,
Themselves become Immaculate Siva
They, forsooth, are Suddha Saivas.`,
    elaborationEnglish: `Lingering not in maya, Suddha Saivas reach the status of Gods. And using it as a spring board, the soul soars to Siva Himself and merges in Him, Realisation of the truth that ‘I’ and are one leads to the light of supreme jnana, illumining the soul’s path to the final goal of sayujya union in the Lord.`,
    elaborationTamil: `மாசு இல்லாத பரம்பொருளாகிய இறைவன் பாடல் #1438 இல் உள்ளபடி சொல்லி அருளிய போதனைகளை தமக்குள் உள்வாங்கிக் கொண்டு அவற்றையே ஓயாமல் சிந்தித்து ஆராய்ந்து இறைவன் அருளிய போதனைகளில் உள்ள ஒவ்வொரு வார்த்தைகளின் பொருளும் முத்தி நிலைக்கு விதையாக இருக்கின்றதை உணர்ந்து அதன் மூலம் முக்திக்கு மூலப் பொருளாக இருக்கின்ற இறைவனின் தன்மையை தானும் பெற்ற சாதகரின் ஆன்மாவானது இறைவனை சென்று அடைந்து அவன் அருளால் மாசு இல்லாத சிவம் எனும் பரம்பொருளாக தாமும் ஆகி இருப்பவர்களே கடும் சுத்த சைவர்கள் ஆவார்கள்.`,
  },
  {
    id: 1442, tantraId: 5, verseNumber: 1441,
    tamil: `நானென்றும் தானென்றும் நாடிநான் சாரவே
தானென்று நானென் றிரண்டிலாத் தற்பதந்
தானென்று நானென்ற தத்துவ நல்கலால்
தானென்று நானென்றுஞ் சாற்றகில் லேனே`,
    transliteration: `nāṉeṉṟum tāṉeṉṟum nāṭināṉ cāravē
tāṉeṉṟu nāṉeṉ ṟiraṇṭilāt taṟpatan
tāṉeṉṟu nāṉeṉṟa tattuva nalkalāl
tāṉeṉṟu nāṉeṉṟuñ cāṟṟakil lēṉē`,
    english: `1441: I and You Difference Effaced
I sought Him in terms of I and You
But He that knows not I from You
Taught me the truth, "I" indeed is "You"
And now I talk not of I and You.`,
    elaborationTamil: `நானாகிய ஆன்மா எங்கே இருக்கின்றது என்றும் தனக்குள் இருக்கும் இறைவன் எங்கே இருக்கின்றான் என்றும் தேடி அலைந்து நான் இறைவனை சார்ந்து இருக்கும் போது இறைவன் என்றும் ஆன்மா என்றும் தனித்தனியாக இருக்கின்ற இரண்டுவிதமான தத்துவங்களும் இல்லாமல் தானே அனைத்துமாய் நிற்கின்ற பரம்பொருளாகிய இறைவன் தான் என்றும் நான் என்றும் ஆகிய அனைத்தும் தாமாகவே இருக்கின்ற தத்துவத்தை எனக்கு தந்து அருளியதால் இனி தான் என்றும் நான் என்றும் ஆன்மாவையும் இறைவனையும் வேறு வேறு என்று பார்க்கின்ற தத்துவத்தை சார்ந்து நிற்காமல் அனைத்தும் இறைவன் ஒருவனே என்று இருக்கின்றேன்.`,
  },
  {
    id: 1443, tantraId: 5, verseNumber: 1442,
    tamil: `சாற்றரி தாகிய தத்துவஞ் சித்தித்தால்
ஆற்றரி தாகிய ஐந்தும் அடங்கிடும்
மேற்றிகழ் ஞானம் விளக்கொளி யாய்நிற்கும்
பாற்பர சாயுச்சிய மாகும் பதியே`,
    transliteration: `cāṟṟari tākiya tattuvañ cittittāl
āṟṟari tākiya aintum aṭaṅkiṭum
mēṟṟikaḻ ñāṉam viḷakkoḷi yāyniṟkum
pāṟpara cāyucciya mākum patiyē`,
    english: `1442: When This Truth Dawns Then is Union in Siva
When this Truth, beyond words, you perceive
The Siva Tattvas five bend below;
The light of Supreme Jnana dawns,
Illumines the Soul's path
To the Finite goal
Of Sayujya union in Lord.`,
    elaborationTamil: `சார்ந்து நிற்பதற்கு மிகவும் அரியதாக இருக்கின்ற அனைத்தும் இறைவன் ஒருவனே எனும் தத்துவம் இறையருளால் கிடைக்கப் பெற்றால் ஆசைகளை நீக்குவதற்கு மிகவும் அரியதாகிய ஐந்து புலன்களும் அடங்கி விடும். அதன் பிறகு மேலே திகழ்கின்ற உண்மை ஞானமானது இருளான வீட்டில் ஏற்றி வைத்த விளக்கு ஒளியை கொடுப்பது போல மாயை நீங்கிய உண்மையை விளங்க வைக்கும் ஒளியாக நிற்கும். அப்போது இந்த உலகத்திலேயே கடும் சுத்த சைவத்தை கடைபிடிக்கின்ற சைவர்கள் தாம் இருக்கின்ற இடத்திலேயே பரம்பொருளோடு எப்போதும் ஒன்றாக சேர்ந்தே இருக்கின்ற சாயுச்சியம் எனும் நிலை கிடைக்கப் பெறுவார்கள்.`,
  },
  {
    id: 1444, tantraId: 5, verseNumber: 1443,
    tamil: `நேர்ந்திடு மூல சரியை நெறியிதென்
றாய்ந்திடுங் காலாங்கி கஞ்ச மலையமான்
ஓர்ந்திடுங் கந்துரு கேண்மின்கள் பூதலத்
தோர்ந்திடுஞ் சுத்த சைவத் துயிரதே`,
    transliteration: `nērntiṭu mūla cariyai neṟiyiteṉ
ṟāyntiṭuṅ kālāṅki kañca malaiyamāṉ
ōrntiṭuṅ kanturu kēṇmiṉkaḷ pūtalat
tōrntiṭuñ cutta caivat tuyiratē`,
    english: `1443: Chariya is Breath of Suddha Saivam
"O! Kalangi! Kanja Malayaman! Kanduru!
My loved disciples, this you understand;
The practice of Chariya is basic to salvation,
And verily is the breath of Suddha Saiva
In this world below"-
Thus quotes-Mula,
Master of penances many.`,
    elaborationTamil: `இறைவனை சென்று அடைவதற்கு மூலமாக இருக்கின்ற சரியை எனும் வழிமுறை இதுவே என்று ஆராய்ந்து அறிந்து கொண்ட காலத்தை வென்று அதை அங்கியாக அணிந்து கொண்டு வெண்கலம் போன்ற உறுதியான மலை எனும் பொருளில் பெயர் கொண்ட கஞ்ச மலைக்கு பெருமை சேர்த்த காலாங்கி நாதரும் இதையே ஆராய்ந்து தெளிவாக உணர்ந்து கொண்ட கந்துரு நாதரும் ஆராய்ந்து உணர்ந்து கொண்ட வழிமுறையை நீங்களும் கேளுங்கள். இந்த பூமியிலேயே இறைவனை அடைவதற்கான வழி என்று ஆராய்ந்து உணர்ந்து கொண்டு அதில் தேர்ச்சி பெறும் சுத்த சைவம் எனும் வழிமுறைக்கு உயிர் ஆதாரமாக இருப்பதே சரியை எனும் வழிமுறை ஆகும்.`,
  },
  {
    id: 1445, tantraId: 5, verseNumber: 1444,
    tamil: `உயிர்க்குயி ராய்நிற்றல் ஒண்ஞான பூசை
உயிர்க்கொளி நோக்கல் மகாயோக பூசை
உயிர்ப்பெறு மாவா கனம்புறப் பூசை
செயிற்கடை நேசஞ் சிவபூசை யாமே`,
    transliteration: `uyirkkuyi rāyniṟṟal oṇñāṉa pūcai
uyirkkoḷi nōkkal makāyōka pūcai
uyirppeṟu māvā kaṉampuṟap pūcai
ceyiṟkaṭai nēcañ civapūcai yāmē`,
    english: `1444: Jnana, Yoga, Kriya and Chariya Defined
To be one, Life within Life-that the luminous path of Jnana;
To seek the Light within Life-that the mighty path of Yoga;
To invest idol with Life-that the external way of Kriya
To adore Siva in love-that the basic worship of Chariya.`,
    elaborationEnglish: `Mantras 1444 & 1445

Jnana is to be one with Siva - life within Life. Seeking that light within Life is Yoga. The external acts investing an image with vibrant spirituality if Kriya; and to adore Siva in intense love is Chariya. Constant worship and adoration of His Name and glory make the Lord to erect a temple within you.`,
    elaborationTamil: `உயிர்களுக்குள் ஆன்மாவாக இறைவன் நிற்கின்ற விதத்தை தமக்குள்ளே ஆராய்ந்து அறிந்து கொள்ளுதல் ஆத்ம விசாரமாகிய (நான் யார் என்று அறிந்து கொள்வது) ஞான பூசையாகும். உயிர்களுக்குள் ஒளியாக இருக்கும் இறைவனை தமக்குள்ளே தரிசித்தல் மாபெரும் சாதனையாகிய யோக பூசையாகும். உருவச் சிலைகள் இறை சக்தியை பெறும்படி மந்திரங்கள் சொல்லி கிரியைகள் செய்து சக்தியூட்டி அந்த சிலைகளுக்கு அபிஷேகமும் ஆராதனையும் செய்வது வெளிப்புற பூசையாகும். எந்தவிதமான பூசைகளை செய்தாலும் அந்த பூசைக்கான செயல்களை இறைவன் மேல் கொண்ட பேரன்போடு செய்வது மானசீகமாகிய சிவ பூசையாகும். இந்த நான்கு விதமான பூசைகளே சரியை ஆகும்.`,
  },
  {
    id: 1446, tantraId: 5, verseNumber: 1445,
    tamil: `நாடு நகரமும் நற்றிருக் கோயிலுந்
தேடித் திரிந்து சிவபெரு மான்என்று
பாடுமின் பாடிப் பணிமின் பணிந்தபின்
கூடிய நெஞ்சத்துக் கோயிலாய்க் கொள்வனே`,
    transliteration: `nāṭu nakaramum naṟṟiruk kōyilun
tēṭit tirintu civaperu māṉeṉṟu
pāṭumiṉ pāṭip paṇimiṉ paṇintapiṉ
kūṭiya neñcattuk kōyilāyk koḷvaṉē`,
    english: `1445: Temple Worship Essential to Chariya
Wander you through town and villa
Seek Him through shrine and temple
Sing of Him as "Siva, Siva, my Lord"
And thus do you offer worship meek,
And the Lord will make your heart His temple.`,
    elaborationTamil: `உலகமெங்கும் இருக்கின்ற அனைத்து நாடுகளிலும் அதிலுள்ள நகரங்களிலும் உயிர்களின் நன்மைக்காக அமைக்கப் பட்டுள்ள இறைவன் வீற்றிருக்கும் கோயில்களை தேடி அலைந்து திரிந்து கண்டு பிடித்து அங்கு வீற்றிருக்கின்ற இறை சக்தியை சிவம் எனும் பரம்பொருளாகவே எண்ணி இறைவனைப் போற்றிப் புகழ்ந்து பாடி கொண்டே இறைவனைப் பணிந்து தொழுது வணங்குங்கள். அவ்வாறு வணங்கிய பிறகு அந்தக் கோயிலில் வீற்றிருக்கும் இறை சக்தியும் வணங்கித் தொழுத பக்தர்களோடு ஒன்றாக சேர்ந்து அந்த பக்தர்களின் நெஞ்சத்தையே தமக்கு விருப்பமான கோயிலாக ஆட்கொண்டு அங்கே வீற்றிருக்கும். கருத்து: ஆலயங்களுக்கு சென்று பக்தியால் போற்றி வணங்கித் தொழுது இறைவனை அடையும் சரியை எனும் முறை இதுவே ஆகும்.`,
  },
  {
    id: 1447, tantraId: 5, verseNumber: 1446,
    tamil: `பத்தர் சரிதை படுவோர் கிரியையோர்
அத்தகு தொண்டர் அருள்வேடத் தாகுவோர்
சுத்த வியமாதி சாதகர் தூயோகர்
சித்தர் சிவஞானஞ் சென்றெய்து வோர்களே`,
    transliteration: `pattar caritai paṭuvōr kiriyaiyōr
attaku toṇṭar aruḷvēṭat tākuvōr
cutta viyamāti cātakar tūyōkar
cittar civañāṉañ ceṉṟeytu vōrkaḷē`,
    english: `1446: Ways of Those Who Follow Four Paths
They who follow path of Chariya are Bhaktas;
In Kriya the devoted souls wear holy emblems,
They who practise Iyama and the rest are Yogis;
And they who reach Siva Jnana are Jnana Siddhas true.`,
    elaborationEnglish: `Bhakta follow the path of Chariya, and devotees wear holy symbols in Kriya. Yogis tread the paths of yama and the rest, and trac siddhars attain Siva jnana.`,
    elaborationTamil: `இறைவனை அடையும் வழிமுறையான சரியையை மேற் கொண்டு கிரியைகளை செய்கின்றவர்களே பக்தர்கள் ஆவார்கள். அந்த கிரியைகளின் செயலின் தன்மையையே தாமும் அடைந்து அதன் பயனால் அருள் வடிவத்தில் இறை தன்மையாகவே அவர்கள் ஆகின்றார்கள். அதனால் மும்மலங்களும் நீங்கி சுத்தமாகிய தமது உடலுக்குள்ளே ஆதியிலிருந்தே இருக்கின்ற ஆன்மாவானது எது என்பதை உணர்ந்து கொண்டு தூய்மையான யோகிகள் ஆகின்றார்கள். அதன் பிறகு பரம்பொருளான சிவத்தின் உண்மை ஞானத்தை தமக்குள்ளே சென்று உணர்ந்து அடைந்து சித்தர்கள் ஆகின்றார்கள். கருத்து: இறைவனை அடையும் வழிமுறையான சரியையை முறைப்படி கடை பிடிப்பவர்கள் அதனாலேயே யோகியர்களாகவும் சித்தர்களாகவும் ஆக முடியும்.`,
  },
  {
    id: 1448, tantraId: 5, verseNumber: 1447,
    tamil: `சார்ந்தமெய்ஞ் ஞானத்தோர் தானவ னாயினோர்
சேர்ந்தவெண் யோகத்தர் சித்தர் சமாதியோர்
ஆய்ந்த கிரியையோர் அருச்சனை தப்பாதோர்
நேர்ந்த சரியையோர் நீள்நிலத் தோரே`,
    transliteration: `cārntameyñ ñāṉattōr tāṉava ṉāyiṉōr
cērntaveṇ yōkattar cittar camātiyōr
āynta kiriyaiyōr aruccaṉai tappātōr
nērnta cariyaiyōr nīḷnilat tōrē`,
    english: `1447: Goals of the Four Paths
Jnanis merge the I in You;
Yogis attain Siddhi and Samadhi;
Those in Kriya miss not daily worship;
And in Chariya they perform pilgrimages many.`,
    elaborationEnglish: `1.-Siddhis — miracles 2. Samadhi — state of quiescence when breath is controlled and thoughts are centred on God.`,
    elaborationTamil: `இறைவனை சார்ந்து இருந்து உண்மை ஞானத்தை அடைந்தவர்கள் தாமே இறைவனாக ஆகி தான் எனும் தன்மை இல்லாதவர்களாக இருக்கின்றார்கள். இறைவனோடு எப்போதும் சேர்ந்தே இருக்கும் எண்ணங்களால் யோகத்தில் மேல் நிலை பெற்ற யோகியர்கள் சித்தர்களாக ஆகி சமாதி நிலையில் இருக்கின்றார்கள். இறைவனை அடைவதற்கான நுட்பங்களை ஆராய்ந்து அறிந்து கொண்டு அதன் படியே கிரியையை செய்கின்றவர்கள் அதற்காக செய்கின்ற பூசைகளை முறைப்படி தவறாமல் செய்கின்றவர்களாக இருக்கின்றார்கள். இறைவனை அடைவதையே குறிக்கோளாக கொண்டு சரியையை செய்கின்றவர்கள் நீண்ட காலம் இந்த உலகத்திலேயே இருக்கின்றார்கள்.`,
  },
  {
    id: 1449, tantraId: 5, verseNumber: 1448,
    tamil: `கிரியை யோகங்கள் கிளர்ஞான பூசை
அரிய சிவனுரு அமரும் அரூபந்
தெரியும் பருவத்துத் தேர்ந்திடும் பூசை
உரியன நேயத் துயர்பூசை யாமே`,
    transliteration: `kiriyai yōkaṅkaḷ kiḷarñāṉa pūcai
ariya civaṉuru amarum arūpan
teriyum paruvattut tērntiṭum pūcai
uriyaṉa nēyat tuyarpūcai yāmē`,
    english: `1448: Worship in the Four Paths
Kriya is worship of Siva in Form,
Yoga of the Formless One,
Jnana is the advanced path in ripeness of time,
The adoration of the loving heart is Chariya,
Exalted indeed it is.`,
    elaborationTamil: `கிரியையில் வெளிப்புறமாக செய்யப்படும் பூசைகளை எண்ணத்தால் யோகத்தில் செய்து தமக்குள் இருக்கும் அறிவை கிளர்ச்சி பெற்று எழுப்பும் உயர்வான ஞான பூசையாகும். அதனால் கிடைப்பதற்கு மிகவும் அரியதான சிவ பரம்பொருளின் உண்மை உருவமாக இருக்கின்ற உருவமே இல்லாத அரூப நிலையை அறிந்து கொள்ளும் பக்குவத்தை பெறலாம். அந்த பக்குவத்தில் தேர்ச்சி பெற்ற பூசைக்கு ஏற்றதாக இருப்பது இறைவன் மீது கொண்ட பேரன்பினால் செய்யப்படும் உயர்வான மானசீக பூசையே ஆகும்.`,
  },
  {
    id: 1450, tantraId: 5, verseNumber: 1449,
    tamil: `சரியாதி நான்குந் தருஞான நான்கும்
விரிவான வேதாந்த சித்தாந்த மாறும்
பொருளா னதுநந்தி பொன்னகர் போந்து
மருளாகு மாந்தர் வணங்கவைத் தானே`,
    transliteration: `cariyāti nāṉkun taruñāṉa nāṉkum
virivāṉa vētānta cittānta māṟum
poruḷā ṉatunanti poṉṉakar pōntu
maruḷāku māntar vaṇaṅkavait tāṉē`,
    english: `1449: The Four Paths Were Revealed by Nandi
The Four paths of worship
And the four states of realization they give
And the six schools of Vedanta-Siddhanta
All these are truths
That Nandi from the Golden City descending revealed
For the doubting humanity to redeem.`,
    elaborationTamil: `இறைவனை அடைவதற்கான சரியை கிரியை யோகம் ஞானம் ஆகிய நான்கு விதமான வழிமுறைகளுக்கும் அவற்றை செய்வதற்கு தேவையான அறிவாகிய நான்கு விதமான ஞானங்களுக்கும் அந்த ஞானங்களின் விரிவாக இருக்கின்ற வேதத்தின் எல்லையாக இருக்கின்ற காபிலம் காணாதம் பாதஞ்சலம் அட்சபாதம் வியாசம் ஜைமினியம் ஆகிய ஆறு விதமான வழிமுறைகளுக்கும் சித்தத்தின் எல்லையாக இருக்கின்ற பைரவம் வாமம் காளாமுகம் மாவிரதம் பாசுபதம் சைவம் ஆகிய ஆறு விதமான வழிமுறைகளுக்கும் உண்மைப் பொருளாக இருக்கின்ற குருநாதனாகிய இறைவன் தம்மை அடையும் இந்த வழிமுறைகளை அறியாமல் மாயையில் சிக்கி சுழன்று கொண்டு இருக்கின்ற மனிதர்களை தான் வீற்றிருக்கும் தங்கம் போன்ற தில்லை சிற்றம்பலத்திற்குள் நுழைய வைத்து தம்மை வணங்கும் படி செய்து அவர்களை ஆட்கொள்கிறான். கருத்து: மாயையில் இருக்கின்ற மனிதர்களை சரியை முறையில் தான் வீற்றிருக்கும் கோயில்களுக்கு வரவைத்து தம்மை வணங்கும் படி செய்து அதன் பயனால் மாயையை நீக்கி ஞானத்தை கொடுத்து இறைவன் ஆட்கொள்கின்றான்.`,
  },
  {
    id: 1451, tantraId: 5, verseNumber: 1450,
    tamil: `சமையம் பலசுத்தித் தன்செயல் அற்றிடும்
அமையும் விசேடமும் அரன்மந் திரசுத்தி
சமைய நிருவாணங் கலாசுத்தி யாகும்
அமைமன்னு ஞானமார்க் கம்அபிடேகமே`,
    transliteration: `camaiyam palacuttit taṉceyal aṟṟiṭum
amaiyum vicēṭamum araṉman tiracutti
camaiya niruvāṇaṅ kalācutti yākum
amaimaṉṉu ñāṉamārk kamapiṭēkamē`,
    english: `1450: Ordination Rites for the Four Paths
Samaya is the ordination rite for self-surrender in Chariya
Visesha, the rite for incantation of Siva Mantra in Kriya
Nirvana helps Kalas purification in Yoga
And Abhisheka for Grace to reach in Jnana.`,
    elaborationEnglish: `The ordination rite for self-surrender in Chariya worship in Samya Diksa, the rite for reception of Siva mantra in Kriya worship is Viesta in Chariya. Nirvana Diksa in Chariya helps purify the kalas in Yoga, and the Abiseka rite in Chariya is for Grace to be reached in Jnana.`,
    elaborationTamil: `சமயம் சொல்கின்ற முறைப்படி அமைக்கப்பட்ட பலவிதமான கோயில்களுக்கு சென்று அவற்றை சுற்றி வந்தால் தன்னுடைய முயற்சியால் எல்லா செயல்களும் நடக்கின்றன என்ற எண்ணம் நீங்கி அனைத்தும் இறைவனாலே நடக்கின்றது என்ற எண்ணம் வந்து விடும். அதன் பிறகு அந்த கோயில்களில் அமைந்து இருக்கின்ற சிறப்பானதும் பாதுகாக்க கூடியதும் ஆகிய மந்திர உச்சாடனங்கள் தம்மை தூய்மை படுத்தி விடும். அதன் பயனால் சமயம் என்று சொல்லப்படுகின்ற எந்த விதிமுறைகளும் அதனைச் சார்ந்த எண்ணங்களும் நீங்கும் படி அறிவை சுத்தம் செய்து விடும். அதன் பிறகு தன்னுடை சுத்தமான அறிவில் இறைவனை நிலைபெறும் படி செய்து இறையருளால் பெற்ற ஞானத்தின் வழியில் தாம் செய்கின்ற அனைத்தையும் இறைவனுக்கு அர்ப்பணிக்கின்றார். குறிப்பு: இந்தப் பாடல் சுவடிகளில் இல்லாததால் பிற்சேர்க்கை பாடலாக இருக்கலாம்.`,
  },
  {
    id: 1452, tantraId: 5, verseNumber: 1451,
    tamil: `பத்துத் திசையும் பரமொரு தெய்வமுண்
டெத்திக் கிலரில்லை என்பதின் அமலர்க்
கொத்துத் திருவடி நீழல் சரணெனத்
தத்தும் வினைக்கடல் சாராது காணுமே`,
    transliteration: `pattut ticaiyum paramoru teyvamuṇ
ṭettik kilarillai eṉpatiṉ amalark
kottut tiruvaṭi nīḻal caraṇeṉat
tattum viṉaikkaṭal cārātu kāṇumē`,
    english: `1451: God is Everywhere-Seek Him
The One God there is
He pervades the ten directions around,
In which direction can we say is He not?
So, do take refuge under His Holy Feet
Then shall you cross the roaring Sea of Karma,
And safe reach the Shores of Beyond.`,
    elaborationEnglish: `Mantras 1451 & 1452

The tempestuous sea of karma can be crossed and the shores beyond can be reached by seeking refuge under the Holy Feet of Him, who pervades the ten directions around. All the fragrant sandal trees and the rarest flowers can hardly take you to the Holy Feet of God. There is an easier way to reach Him - that is, by realising His presence in the depths of your heart, unfettering all worldly shackles`,
    elaborationTamil: `பத்து விதமான திசைகளுக்கும் பரம்பொருளாக இருக்கின்ற ஒரு தெய்வம் இருக்கின்றது. அந்த தெய்வத்தை எந்த விதத்திலும் போற்றி வணங்குவதற்கு இயலாதவர்கள் என்று எவரும் இல்லை (அனைவராலும் இயலும்). ஆகவே தூய்மையான தாமரை மலர் போன்று இருக்கின்ற அவனது மேன்மைக்கும் மரியாதைக்கும் உரிய திருவடிகளின் அமைதியையும் குளிர்ச்சியையும் தருகின்ற நிழலே சரணாகதி என்று சரணடைந்தால் மாயையில் சிக்கிக்கொண்டு தத்தளிக்கின்ற வினைகளால் சூழ்ந்த கடல் போன்ற இந்த உலக வாழ்க்கையை சார்ந்து இல்லாமல் அந்த இறை சக்தியை தமக்குள் தரிசிக்கலாம். கருத்து: இறைவனை அடைவதற்கு அருளப்பட்ட சரியை கிரியை யோகம் ஞானம் ஆகிய நான்கு விதமான வழிமுறைகளில் சரியை செய்வதற்கு ஊனமில்லாத ஆரோக்கியமான உடல் வேண்டும். யோகம் செய்வதற்கு உறுதியான உடலும் மனமும் வேண்டும். ஞானம் மூலம் இறைவனை அடைவதற்கு குருவருளும் திருவருளும் இருக்க வேண்டும். ஆனால் கிரியையை எவரும் எந்த விதத்திலும் செய்ய முடியும்.`,
  },
  {
    id: 1453, tantraId: 5, verseNumber: 1452,
    tamil: `கானுறு கோடி கடிகமழ் சந்தனம்
வானுறு மாமல ரிட்டு வணங்கினும்
ஊனினை நீக்கி உண்பவர்க் கல்லது
தேனமர் பூங்கழல் சேரவொண் ணாதே`,
    transliteration: `kāṉuṟu kōṭi kaṭikamaḻ cantaṉam
vāṉuṟu māmala riṭṭu vaṇaṅkiṉum
ūṉiṉai nīkki uṇpavark kallatu
tēṉamar pūṅkaḻal cēravoṇ ṇātē`,
    english: `1452: True Worship is Worship Within
You may adore Him with sandal fragrance exceeding,
That grows on peaks atop in forests interior,
You may worship Him with flowers rare,
That bloom in Heaven's gardens
Unless you shed your fleshy attachments
And realize Him in the depths of your heart
You shall never never reach His Holy Feet`,
    elaborationTamil: `காட்டில் இருக்கும் மரங்களை ஊடுறுவிச் சென்று கோடி காத தூரம் பரவுகின்ற நறுமணம் கமழ்கின்ற சந்தனத்தை பூசி வழிபட்டாலும் வானத்தை ஊடுறுவும் அளவிற்கு மிகப் பெரிய அளவு மலர்களால் கட்டிய மாலையை சூட்டி வழிபட்டாலும், தான் எனும் எண்ணத்தையும் உடல் சார்ந்த பற்றுக்களையும் நீக்கி விட்டு இறைவனை உணர்ந்து வழிபடுபவர்களுக்கு மட்டுமின்றி சுவையான தேனை போன்ற பேரின்பத்தை கொண்டு இருப்பதால் வண்டுகள் போன்ற அடியவர்கள் விரும்பி வந்து சரணடைகின்ற மென்மையான பூவைப் போன்ற இறைவனின் திருவடிகளை சென்று சேரும் பெரும் பேறு வேறு யாருக்கும் கிடைக்காது.`,
  },
  {
    id: 1454, tantraId: 5, verseNumber: 1453,
    tamil: `கோனக்கன் றாயே குரைகழல் ஏத்துமின்
ஞானக்கன் றாகிய நடுவே யுழிதரும்
வானக்கன் றாகிய வானவர் கைதொழு
மானக்கன் றீசன் அருள்வள்ள மாமே`,
    transliteration: `kōṉakkaṉ ṟāyē kuraikaḻal ēttumiṉ
ñāṉakkaṉ ṟākiya naṭuvē yuḻitarum
vāṉakkaṉ ṟākiya vāṉavar kaitoḻu
māṉakkaṉ ṟīcaṉ aruḷvaḷḷa māmē`,
    english: `1453: Bhakti Begets Grace
The Lord is your Guide,
Seek His feet as does the yearning calf,
He shall seat you amidst His children of Wisdom;
The Devas, the Beings of Heaven, bow low before Him;
Great is His love, as of the cow to her calf;
And bounteous His Grace, beyond beyond count.`,
    elaborationEnglish: `He groups you among His children of wisdom when He is sought with a loving heart. Great is His love and bounteous His Grace infinite.

The simile of the cow and the calf to describe the relationship : between God and the individual is as old as the Atharva Veda.`,
    elaborationTamil: `நேர் வழியில் செல்ல முடியாமல் வினைகளால் அலைக்கழிக்கப்பட்டு விதி வழியே செல்லுகின்ற பிள்ளைகளாக இருந்தாலும் ஒலி பொருந்திய சிலம்புகளை அணிந்திருக்கும் இறைவனின் திருவடிகளை போற்றி வணங்கிக் கொண்டே இருங்கள். அப்படி வணங்கிக் கொண்டே இருந்தால் அவனது அருளால் ஞானம் பெற்ற பிள்ளைகளாக ஆகி தமக்கு நடுவில் இருக்கும் சுழுமுனை நாடியில் இருந்து அமிழ்தம் சுரக்கும் படி கொடுக்கும். அந்த அமிழ்தத்தை அருந்திக் கொண்டு இருந்தால் வானத்தில் இருக்கும் பிள்ளைகளாகிய தேவர்களும் சென்று கைகூப்பி தொழுகின்ற ஆன்மாவைக் கொண்டு இருக்கின்ற பிள்ளைகளாகிய உயிர்களுக்கு எல்லாம் அதிபதியாகிய இறைவனின் திருவருளை நிரம்புகின்ற பாத்திரமாக நீங்கள் ஆகிவிடுவீர்கள்.`,
  },
  {
    id: 1455, tantraId: 5, verseNumber: 1454,
    tamil: `இதுபணிந் தெண்டிசை மண்டிலம் எல்லாம்
அதுபணி செய்கின் றவளொரு கூறன்
இதுபணி மானுடர் செய்பணி யீசன்
பதிபணி செய்வது பத்திமை காணே`,
    transliteration: `itupaṇin teṇṭicai maṇṭilam ellām
atupaṇi ceykiṉ ṟavaḷoru kūṟaṉ
itupaṇi māṉuṭar ceypaṇi yīcaṉ
patipaṇi ceyvatu pattimai kāṇē`,
    english: `1454: Bhakti's End is Lord's Abode
She fashioned this world
And all universe that fills space in directions eight
Her-He consorts, sharing Himself with Her
To adore Him is the duty of humans here below;
And that which fashions a place in Lord's Abode
Is Bhakti true.`,
    elaborationEnglish: `Mantras 1454 & 1455

He is one with his consort, who fashioned this world in eight directions. It is the jiva's duty to adore and worship Him. Commencing with the performance of Chariya and Kriya, the devotee is blessed with the grace of yoga pure and this takes him to jnana, leading finally to union with Siva, in the way the Guru shows.`,
    elaborationTamil: `கிரியை வழிமுறையை கடைபிடிக்கின்றவர்கள் இந்த உடலுக்குள் இருப்பது இறை சக்தியே என்பதை அறிந்து கொண்டு அதை பணிந்து வணங்கி எட்டு திசைகளிலும் இருக்கின்ற மண்டலங்கள் அனைத்திலும் நிகழ்கின்ற அனைத்து விதமான செயல்களையும் செய்கின்ற ஒளியாக இருக்கின்றதும் அதுவே என்பதை எடுத்துச் சொன்னால், இந்த உலகத்தில் தாம் செய்ய வேண்டிய செயல்கள் என்று மனிதர்களால் செய்யப் படுகின்ற அனைத்து செயல்களும் இறைவனே செய்கின்றான் என்பதை அறிந்து கொண்டு அனைத்திற்கும் அதிபதியாக இருக்கின்ற இறைவனுக்கே தாம் செய்கின்ற அனைத்து செயல்களையும் செய்வதாக எண்ணிக் கொண்டு அவற்றை அன்போடு செய்வது கிரியை வழியில் செல்லுகின்ற பக்தியின் முறைமை என்று கண்டு கொள்ளுங்கள்.`,
  },
  {
    id: 1456, tantraId: 5, verseNumber: 1455,
    tamil: `பத்தன் கிரியை சரியை பயில்வுற்றுச்
சுத்த அருளால் துரிசற்ற யோகத்தில்
உய்த்த நெறியுற் றுணர்கின்ற ஞானத்தாற்
சித்தங் குருவரு ளாற்சிவ மாகுமே`,
    transliteration: `pattaṉ kiriyai cariyai payilvuṟṟuc
cutta aruḷāl turicaṟṟa yōkattil
uytta neṟiyuṟ ṟuṇarkiṉṟa ñāṉattāṟ
cittaṅ kuruvaru ḷāṟciva mākumē`,
    english: `1455: The Four Paths are the Steps in the Ladder to Siva Union
The Bhakta to begin with practises Chariya and Kriya,
Then blessed with grace takes to Yoga pure;
And that way reaches the path of Jnana
And in the end by Guru's grace becomes one with Siva.`,
    elaborationTamil: `பாடல் #1454 இல் உள்ளபடி பக்தியின் முறையை கடைபிடிக்கின்ற பக்தன் கிரியையும் சரியையும் முறைப்படி கற்று அதனை கடைபிடிப்பதையே குறிக்கோளாகக் கொண்டு செய்யும் போது இறைவனின் தூய்மையான அருளால் யோகம் கிடைக்கப் பெறும். அப்படி தமக்கு கிடைத்த மேன்மையான யோக வழியை குறிக்கோளாகக் கொண்டு ஒரு குற்றமும் இல்லாமல் செய்யும் போது அதன் பயனால் தமக்குள் உண்மை ஞானத்தை உணரலாம். அப்படி உணர்ந்த உண்மை ஞானத்தின் வழியாக சித்தம் தெளிவு பெற்று குருவாக இருக்கின்ற இறைவனின் அருளால் அவர் தமது சித்தம் சிவமாகவே ஆகி விடும்.`,
  },
  {
    id: 1457, tantraId: 5, verseNumber: 1456,
    tamil: `அன்பின் உருகுவ நாளும் பணிசெய்வன்
செம்பொன்செய் மேனி கமலத் திருவடி
முன்புநின் றாங்கே மொழிவ தெனக்கருள்
என்பினுட் சோதி இலங்குகின் றானே`,
    transliteration: `aṉpiṉ urukuva nāḷum paṇiceyvaṉ
cempoṉcey mēṉi kamalat tiruvaṭi
muṉpuniṉ ṟāṅkē moḻiva teṉakkaruḷ
eṉpiṉuṭ cōti ilaṅkukiṉ ṟāṉē`,
    english: `1456: Daily I Beseech His Grace
The Lord is resplendent as pure gold
His Feet are unto the lotus bloom
At them I pray: "Lord, Grant me Your Grace!"
And in love I melt and daily adore;
And the Lord that is Light within my bones
Himself does reveal unto me.`,
    elaborationEnglish: `By blessing His Grace and Love through daily worship, the Lord reveals Himself - He that is the light within our bones.

Samaya, Visesa, Nirvana, and Abhiseka are four ordinations in Kriya worship. also.`,
    elaborationTamil: `இறைவன் மேல் கொண்ட உண்மையான அன்பினால் உருகுபவனும் தினந்தோறும் தாம் செய்கின்ற அனைத்து விதமான செயல்களையும் இறைவனுக்காகவே செய்வதாகவே நினைத்துக் கொண்டு செய்பவனும் தூய்மையான பசும் பொன்னால் செய்யப்பட்டது போல பிரகாசிக்கின்ற திருமேனியையும் செந்தாமரை மலர் போன்ற திருவடிகளையும் கொண்டு தமக்குள் இருக்கும் சோதி வடிவான இறைவனாகவே தமக்கு முன்பு நிற்கின்றவர்கள் அனைவரையும் பார்ப்பவனும் அவர்கள் சொல்லுகின்ற அனைத்துமே தமக்கு இறைவன் கொடுத்த அருளாக எடுத்துக் கொள்கின்றவனும் ஆகிய பக்தனின் எலும்புகளால் மூடியிருக்கும் உடலுக்கு உள்ளே தங்கம் போல பிரகாசிக்கின்ற சோதியாக பக்தன் இருக்கின்ற இடத்திலேயே நிற்கின்றான் இறைவன்.`,
  },
  {
    id: 1458, tantraId: 5, verseNumber: 1457,
    tamil: `நெறிவழி யேசென்று நேர்மையுள் ஒன்றித்
தறியிருந் தாற்போல் தம்மை யிருத்திச்
சொறியினுந் தாக்கினுந் துண்ணென் றுணராக்
குறியறி வாளர்க்குக் கூடலு மாமே`,
    transliteration: `neṟivaḻi yēceṉṟu nērmaiyuḷ oṉṟit
taṟiyirun tāṟpōl tammai yiruttic
coṟiyiṉun tākkiṉun tuṇṇeṉ ṟuṇarāk
kuṟiyaṟi vāḷarkkuk kūṭalu māmē`,
    english: `1457: Yoga Way Leads to Realization
They course Kundalini through centers six,
To singleness of aim direct the mind,
Unto a wooden stake they sit immobile,
Impervious to tickle or to thrust,
To the wise yogins who thus set their purpose high,
Lord His Grace grants.`,
    elaborationEnglish: `Yogis receive the Grace of the Lord when they course the kundalini through the six centres, sitting immobile, unperturbed by tickle or thrust, concentrating on the single aim.`,
    elaborationTamil: `இறைவனை அடைவதற்கு என்று குருநாதர் அருளிய நெறிமுறைகளின் வழியாகவே மனதை செலுத்தி அந்த வழிமுறையில் சிறிது அளவும் குறை இல்லாமல் முறைப்படி செய்து அதிலேயே மனதை ஒன்றி வைத்து தரையில் ஊன்றி வைத்த கழி அசையாமல் இருப்பதைப் போலவே தாமும் எதனாலும் அசையாமல் இருந்து, மழை பொழிந்தாலும் காற்று அடித்தாலும் அதனால் சிறிதும் அசையாத கழியைப் போலவே தம்மை சுற்றி எது நடந்தாலும் அதனால் பயம் என்ற உணர்வே சிறிது அளவும் இல்லாமல் இறைவனை அடைவது மட்டுமே குறிக்கோளாகக் கொண்டு அவனை தமக்குள் அறிந்து தெளிந்தவர்களுக்கு இறைவனோடு ஒன்றாக கூடுவது இயலும்.`,
  },
  {
    id: 1459, tantraId: 5, verseNumber: 1458,
    tamil: `ஊழிதோ றூழிஉணர்ந்தவர்க் கல்லால்
ஊழிதோ றூழி உணரவுந் தானொட்டான்
ஆழி அமரும் அரியயன் என்றுளார்
ஊழி முயன்றும் ஒருச்சியு ளானே`,
    transliteration: `ūḻitō ṟūḻiuṇarntavark kallāl
ūḻitō ṟūḻi uṇaravun tāṉoṭṭāṉ
āḻi amarum ariyayaṉ eṉṟuḷār
ūḻi muyaṉṟum orucciyu ḷāṉē`,
    english: `1458: God is Timeless Eternity
Unless you have realized Him as Timeless Eternity
You know Him not, albeit through aeons and aeons of time;
The Gods-Hari of the Ocean bed and Aya, the Creator-
In vain have sought Him through countless vista of Time
He is at the Pinnacle, beyond, beyond their reach.`,
    elaborationEnglish: `Mantras 1458 & 1460

Realise Him, the pinnacle beyond our understanding as Timeless Eternity. Siva's Grace blossoms out of jiva as hidden fragrance comes out of the flower. The yogi, unmoved as a painted picture, cognises Him, who is all pervasive, and immanent too within him. Then is the destruction of darkness, that is the seed of the endless birth and rebirth.`,
    elaborationTamil: `ஊழிக்காலம் ஒவ்வொன்றிலும் ஊழியாக இருந்து அனைத்தையும் அழித்து மீண்டும் உருவாக்குகின்ற இறைவனை யோகத்தின் வழியால் சென்று தமக்குள் உணர்ந்தவர்களை தவிர வேறு யாராலும் உணர இயலாது. ஊழிக்காலம் ஒவ்வொன்றிலும் ஊழியாக இருந்து அனைத்தையும் அழித்து மீண்டும் உருவாக்குகின்ற இறைவனை தமக்குள் உணர்ந்து கொண்ட யோகியர்கள் அந்த ஊழிக்காலத்தோடு தானும் ஒட்டாமல் விலகி இறைவனை மட்டுமே சார்ந்து இருப்பார்கள். பாற் கடலில் பள்ளி கொண்டு அமர்ந்து இருக்கும் திருமால் அவரது தொப்புள் கொடியில் இருக்கும் தாமரை மலரில் வீற்றிருக்கும் பிரம்மன் என்று இருக்கின்ற தெய்வங்களும் ஊழிக்காலத்தோடு ஒட்டாமல் இருக்கின்றார்கள். ஊழிக்காலம் எவ்வளவுதான் இவர்களை அழிக்க முயற்சி செய்தாலும் அதனால் அழிக்க முடியாத ஒரு மாபெரும் உயரத்தில் இருந்து அவர்களை பாதுகாக்கின்ற அரனாக இறைவன் இருக்கின்றான். கருத்து: பாடல் #1457 இல் உள்ளபடி யோகம் செய்து தமக்குள் இறைவனை உணர்ந்து அவனை மட்டுமே சார்ந்து இருக்கின்றவர்களை ஊழிக்காலம் எவ்வளவு முயன்று பார்த்தாலும் அழிக்க முடியாத அளவு பாதுகாக்கின்றான் இறைவன்.`,
  },
  {
    id: 1460, tantraId: 5, verseNumber: 1459,
    tamil: `பூவினிற் கந்தம் பொருந்திய வாறுபோற்
சீவனுக் குள்ளே சிவமணம் பூத்தது
ஓவியம் போல உணர்ந்தறி வாளர்க்கு
நாவி யணைந்த நடுதறி யாமே`,
    transliteration: `pūviṉiṟ kantam poruntiya vāṟupōṟ
cīvaṉuk kuḷḷē civamaṇam pūttatu
ōviyam pōla uṇarntaṟi vāḷarkku
nāvi yaṇainta naṭutaṟi yāmē`,
    english: `1459: Yogi Realizes God Within
As from within the flower,
The hidden fragrance wakes to life,
So, out of Jiva blossoms
Siva's divine grace;
Sitting unmoved like painted picture
The yogi realizes Him within
Unto the planted pole is He,
Which the musk-cat embraces, its fragrance to shed.`,
    elaborationTamil: `மலராத பூவிற்குள்ளும் நறுமணம் கலந்து இருக்கின்ற முறையை போலவே ஜீவாத்மாவிற்கு உள்ளே சிவம் எனும் பரம் பொருளானது கலந்து இருக்கின்றது. பூவானது மலர்ந்த பிறகு அதனது நறுமணம் வெளிப்படுவது போலவே வரைந்து வைத்த ஓவியம் போல எதனாலும் அசையாமல் யோகத்தில் இருந்து இந்த முறையை தமக்குள்ளே உணர்ந்து அறிந்து கொண்டவர்களுக்கு, கஸ்தூரியோடு சேர்ந்து இருக்கும் நறுமணம் போல தரையில் நடப்பட்ட கழியைப் போல அசையாமல் இருக்கின்ற யோகியர்களின் பக்குவப்பட்ட ஆன்மாவிற்குள் சேர்ந்து இருக்கின்ற சிவம் வெளிப்படும்.`,
  },
  {
    id: 1461, tantraId: 5, verseNumber: 1460,
    tamil: `உய்ந்தனம் என்பீர் உறுபொருள் காண்கிலீர்
கந்த மலரிற் கலக்கின்ற நந்தியைச்
சிந்தை யுறவே தெளிந்திருள் நீங்கினால்
முந்தைப் பிறவிக்கு மூலவித் தாமே`,
    transliteration: `uyntaṉam eṉpīr uṟuporuḷ kāṇkilīr
kanta malariṟ kalakkiṉṟa nantiyaic
cintai yuṟavē teḷintiruḷ nīṅkiṉāl
muntaip piṟavikku mūlavit tāmē`,
    english: `1460: Seek God Within You
You say, "I have realized God"
Yet you have not seen Him that is but within you;
Nandi abides subtle as fragrance within flower;
Seek Him in singleness of your thought
Then shall your darkness of Impurities vanish
The darkness that is the seed of birth and rebirth interminable.`,
    elaborationTamil: `முக்திக்கான ஞானத்தை பெற்று விட்டோம் என்று கூறுகின்றீர்கள் உங்களுக்கு உள்ளேயே இருக்கின்ற பரம்பொருளை கண்டு உணராமல் இருக்கின்றீர்கள். நறுமணம் மலருக்குள் மறைந்து இருப்பது போல ஜீவாத்மாவிற்குள் மறைந்து இருக்கின்ற குருநாதனாகிய இறைவனை சிந்தை முழுவதும் அவன் மேல் வைத்து யோகம் செய்து தமக்குள் அவனை அறிந்து கொண்டு தெளிவு பெற்று அதன் பயனால் மும்மலங்களாகிய இருளை நீக்கி விட்டால் முதன் முதலில் இறைவனிடமிருந்து பிரிந்து வந்து பிறவி எடுப்பதற்கு மூல காரணமாக இருக்கின்ற ஆசைகள் நீங்கப் பெற்று இனி பிறவியே இல்லாத நிலையை அடையலாம்.`,
  },
  {
    id: 1462, tantraId: 5, verseNumber: 1461,
    tamil: `எழுத்தோடு பாடலும் எண்ணெண் கலையும்
பழித்தலைப் பாசப் பிறவியும் நீங்கா
வழித்தலைச் சோமனோ டங்கி யருக்கன்
வழித்தலைச் செய்யும் வகையுணர்ந் தேனே`,
    transliteration: `eḻuttōṭu pāṭalum eṇṇeṇ kalaiyum
paḻittalaip pācap piṟaviyum nīṅkā
vaḻittalaic cōmaṉō ṭaṅki yarukkaṉ
vaḻittalaic ceyyum vakaiyuṇarn tēṉē`,
    english: `1461: Yoga Shows the Way
Neither mantra, nor song, nor arts four and sixty
Ever sunders birth and its accursed bonds;
Then did I take to Yoga's way,
And lo! I met the Sun, Moon and Fire on the way to Cranium
And they showed the Supreme Way!`,
    elaborationEnglish: `Neither mantra nor song, nor the sixty-four arts can sever birth and its accursed bonds. Yoga leads to the supreme Way to the sublime. Yogic practice turns one a true tapasvin. He becomes one with the heavenly beings, realising the true word. Yogis vision Him in single-mindedness.`,
    elaborationTamil: `பாடல் #1457 இல் உள்ளபடி அசையாத மனதுடன் செய்யாமல் அலைகின்ற மனதுடன் செய்யப்படுகின்ற எழுதப் பட்ட எழுத்துக்களும் அவற்றோடு சேர்ந்து பாடுகின்ற பாடல்களும் இவற்றை கொண்டு இருக்கும் அறுபத்து நான்கு கலைகளும் ஆகியவற்றால் இறைவனை அடையாமல் வாழ்க்கையை வீணடிக்கின்ற பழிக்கு தலைமையாக இருக்கின்ற பாசத்தையும் அதனால் எடுக்கின்ற பிறவிகளையும் ஒருவரால் நீக்கி விட முடியாது. பாசத்தையும் பிறவியையும் நீக்குகின்ற வழிக்கு தலைமையாக இருக்கின்ற சந்திர கலையோடு அக்கினி கலையையும் சூரிய கலையையும் சேர்த்து பயன்படுத்துகின்ற வழிமுறைக்கு தலைமையாக இருக்கின்ற யோகத்தை அசையாத மனதுடன் செய்கின்ற வகைகளை எமக்குள் செய்த யோகத்தினால் யாம் உணர்ந்து கொண்டோம். குறிப்பு: பாசமும் பிறவிகளும் நீங்கி இறைவனை அடைவதற்கு எந்த முறையை பயன்படுத்தினாலும் அதில் அசையாத மனதுடன் செய்தால் மட்டுமே அடைய முடியும்.`,
  },
  {
    id: 1463, tantraId: 5, verseNumber: 1462,
    tamil: `விரும்பிநின் றேசெயில் மேய்த்தவ ராகும்
விரும்பிநின் றேசெயின் மெய்யுரை யாகும்
விரும்பிநின் றேசெயின் மெய்த்தவ மாகும்
விரும்பிநின் றேசெயில் விண்ணவ னாகுமே`,
    transliteration: `virumpiniṉ ṟēceyil mēyttava rākum
virumpiniṉ ṟēceyiṉ meyyurai yākum
virumpiniṉ ṟēceyiṉ meyttava mākum
virumpiniṉ ṟēceyil viṇṇava ṉākumē`,
    english: `1462: Fruits of Yoga
Do in devotion practise yoga
You shall a true tapasvin become;
You shall the True Word realize;
And of certain, one with Heavenly Beings be;
Yoga devoted is penance true.`,
    elaborationTamil: `பாடல் #1461 இல் உள்ளபடி எழுத்துக்களும் பாடல்களும் அவை அடங்கிய அறுபத்து நான்கு கலைகளும் ஆகிய எதை செய்தாலும் இறைவனை அடைய வேண்டும் என்ற விருப்பத்தில் அசையாத மனதுடன் நின்று செய்கின்றவர்களே உண்மையான தவத்தை புரிகின்றவர்கள் ஆவார்கள். அந்த செயலால் கிடைக்கப் பெறுவதே மாயை நீங்கிய உண்மையான உணர்வு நிலை ஆகும். அப்படி அசையாத மனதுடன் செய்வதே உண்மையான தவ முறை ஆகும். அந்த தவத்தை முறையாக செய்கின்றவர்கள் விண்ணுலகத் தேவர்களாகவே ஆகிவிடுவார்கள்.`,
  },
  {
    id: 1464, tantraId: 5, verseNumber: 1463,
    tamil: `பேணிற் பிறவா உலகருள் செய்திடுங்
காணில் தனது கலவியு ளேநிற்கும்
நாணில் நகர நெறிக்கே வழிசெயும்
ஊனிற் சுடுமங்கி யுத்தமன் றானே`,
    transliteration: `pēṇiṟ piṟavā ulakaruḷ ceytiṭuṅ
kāṇil taṉatu kalaviyu ḷēniṟkum
nāṇil nakara neṟikkē vaḻiceyum
ūṉiṟ cuṭumaṅki yuttamaṉ ṟāṉē`,
    english: `1463: Do's and Don'ts in Yoga
Do with care practise yoga
You shall with Immortals be;
Within you shall you glimpse Him;
If you but waver,
Then shall you reach the World of Darkness
Verily, Kundalini Fire that Yoga kindles in thee
Is the Gracious Lord HimSelf.`,
    elaborationTamil: `யோகத்தை அசையாத மனதுடன் இடைவிடாது முறைப்படி கடைபிடித்து வந்தால் இனி பிறவி எடுக்காத நிலையை இந்த உலகத்திலேயே இறையருள் கொடுத்து விடும். அந்த இறை சக்தியை தமக்குள் தரிசித்தால் தம்முடைய ஆன்மாவோடு ஒன்றாக கலந்து உள்ளே வீற்றிருக்கும் அந்த சக்தியை அறிந்து கொள்ளலாம். அப்படி இறையோடு கலந்து இருக்கின்ற நிலையில் இருப்பதற்கு வெட்கப் பட்டுக் கொண்டு விலகி நின்றால் மனமானது ஐம்புலன்களின் வழியே ஆசைகளின் பின்னால் செல்லுகின்ற தவறான வழியையே கொடுக்கும். இறையோடு கலந்து இருக்கின்ற நிலையிலேயே வெட்கப் படாமல் தொடர்ந்து இருந்தால் உடலுக்குள் இருக்கின்ற மலங்களை சுட்டெரிக்கின்ற மூலாக்கினியாக இருக்கின்ற உத்தமனாகிய இறைவனாகவே தாமும் ஆகிவிடுவார்கள்.`,
  },
  {
    id: 1465, tantraId: 5, verseNumber: 1464,
    tamil: `ஒத்தசெங் கோலார் உலப்பிலி மாதவர்
எத்தனை யாயிரம் வீழ்ந்தனர் எண்ணிலி
சித்தர்கள் தேவர்கள் மூவர் பெருமையாய்
அத்த னிவனென்றே அன்புறு வார்களே`,
    transliteration: `ottaceṅ kōlār ulappili mātavar
ettaṉai yāyiram vīḻntaṉar eṇṇili
cittarkaḷ tēvarkaḷ mūvar perumaiyāy
atta ṉivaṉeṉṟē aṉpuṟu vārkaḷē`,
    english: `1464: Fall and Redemption Through Yoga
The monarchs that swayed the sceptre righteous,
The devout anchorites in unnumbered thousands,
How many, how many, thy fell below;
(For having wavered in Yoga practice)
And yet, the myriad Siddhas, Devas and Supreme Beings Three,
All redeemed adore Him
Saying "You, Our Father!"`,
    elaborationEnglish: `Monarchs and anchorites have fallen due to the pursuit of yoga in fickleness. But myriad siddhars, devas and the three Gods adore Him redeemed.`,
    elaborationTamil: `ஒன்றாக இருக்கும் செம்மையான கோலைப் போல வீற்றிருந்து அழிவு இல்லாத மாபெரும் தவத்தை புரிந்தவர்களில் எத்தனையோ ஆயிரம் பேர்கள் அதை தொடராமல் விட்டு விட்டதால் வீழ்ந்து போனவர்கள் என்று எண்ணிக்கை இல்லாமல் இருக்கின்றார்கள். அப்படி விட்டு விடாமல் தொடர்ந்து மாபெரும் தவத்தை புரிகின்றவர்களை சித்தர்களும் தேவர்களும் மும்மூர்த்திகளும் பெருமையுடன் எங்களின் அப்பனான இறைவன் இவனே என்று கூறி அவரோடு அன்பு கொண்டு இருப்பார்கள்.`,
  },
  {
    id: 1466, tantraId: 5, verseNumber: 1465,
    tamil: `யோகிக்கு யோகாதி மூன்றுள கொண்டுற்றோர்
ஆகத் தகுகிரி யாதி சரியையாந்
தாகத்தை விட்ட சரியையொன் றாம்ஒன்றுள்
ஆதித்தன் பத்தியுள் அன்புவைத் தேனே`,
    transliteration: `yōkikku yōkāti mūṉṟuḷa koṇṭuṟṟōr
ākat tarukiri yāti cariyaiyān
tākattai viṭṭa cariyaiyoṉ ṟāmoṉṟuḷ
ātittaṉ pattiyuḷ aṉpuvait tēṉē`,
    english: `1465: Sub-divisions in Yoga
The yogi has sub-divisions three in his path;
The yoga-kriya that helps him be the yogi;
The yoga-chariya that of desires deprives him,
And yoga-in-yoga that centers thought on Sun within;
This latter I fixed my heart on.`,
    elaborationTamil: `யோகத்தை புரிகின்ற யோகிக்கும் யோக நெறிமுறைக்கும் மூலமாக இருக்கின்ற மூன்று விதமான வழிமுறைகள் உள்ளது. இவற்றோடு ஒன்றி யோக முறையை கடை பிடிக்கின்ற யோகியர்கள் யோகியாக ஆகுவதற்கு தகுந்த கிரியைகள் மற்றும் அவற்றின் மூல முறைகள் சரியைகள் மற்றும் அவற்றின் மூல முறைகள் யாகம் செய்வதை தவிர மற்ற அனைத்து செயல்களும் அடங்கிய சரியை முறைகள் என்று ஒவ்வொன்றாக உள்ள மூன்று விதமான முறைகளையும் தமக்கு ஏற்ற வழிமுறைகளாக எடுத்துக் கொண்டு அதன் வழியே புரிகின்ற யோகத்தில் தாம் கொண்ட பக்திக்கு உள்ளேயே இறைவன் மேல் உண்மையான அன்பை வைத்து இருப்பார்கள்.`,
  },
  {
    id: 1467, tantraId: 5, verseNumber: 1466,
    tamil: `யோகச் சமயமே யோகம் பலவுன்னல்
யோக விசேடமே அட்டாங்க யோகமாம்
யோகநிர் வாணமே யுற்ற பரோதயம்
யோக அபிடேகமே ஒண்சித்தி யுற்றலே`,
    transliteration: `yōkac camayamē yōkam palavuṉṉal
yōka vicēṭamē aṭṭāṅka yōkamām
yōkanir vāṇamē yuṟṟa parōtayam
yōka apiṭēkamē oṇcitti yuṟṟalē`,
    english: `1466: Stages of Initiation in the Yoga Path
Samaya Diksha in yoga is initiation for diverse yoga efforts;
Visesha Diksha in yoga is for achievement of eight-limbed yoga;
Nirvana Diksha in yoga aids yogi glimpse the Divine;
And when he is granted Abhisheka Ordination
Then is he ripe for Siddha State.`,
    elaborationEnglish: `The sub-divisions of Yoga are Chariya in Yoga, Kriya in Yoga, and Yoga in Yoga. The first one helps the aspirant to be the yogi, the second sunders desires while the third enables him to centre his thoughts on God. Samaya Diksha, Visesa Diksha, Nirvana Diksha, and Abhisheka Diksha are the ordinations in the graded stages of the Yoga path.`,
    elaborationTamil: `யோகத்தில் சமயம் எனப்படுகின்ற சரியை என்பது யோகத்தில் உள்ள பல விதமான நெறிமுறைகளை உள் வாங்கிக் கொண்டு அதை தவறாமல் கடைபிடித்தல் ஆகும். யோகத்தில் விசேடம் எனப்படுகின்ற கிரியை என்பது எட்டு அங்கங்களைக் கொண்டு இருக்கின்ற அட்டாங்க யோகம் ஆகும். யோகத்தில் நிர்வாணம் எனப்படுகின்ற யோகம் என்பது தமக்கு கிடைக்கப் பெற்ற அசையாத மனதோடு எண்ணங்கள் அற்ற நிலை தோன்றுவது ஆகும். யோகத்தில் அபிடேகம் எனப்படுகின்ற ஞானம் என்பது தம்மோடு ஒன்றாக கலந்து இருக்கின்ற இறை சக்தியை உணர்வது ஆகும்.`,
  },
  {
    id: 1468, tantraId: 5, verseNumber: 1467,
    tamil: `ஞானத்தின் மிக்க அறநெறி நாட்டில்லை
ஞானத்தின் மிக்க சமயமும் நன்றன்று
ஞானத்தின் மிக்கவை நன்முத்தி நல்காவா
ஞானத்தின் மிக்கார் நரரின்மிக் காரே`,
    transliteration: `ñāṉattiṉ mikka aṟaneṟi nāṭṭillai
ñāṉattiṉ mikka camayamum naṉṟaṉṟu
ñāṉattiṉ mikkavai naṉmutti nalkāvā
ñāṉattiṉ mikkār narariṉmik kārē`,
    english: `1467: Jnana Path Most Exalted
Than Jnana,
There is none better an ethical path, here below;
None better a religious faith;
Nothing else than Jnana can confer liberation true;
They that are exalted in Jnana
Are truly exalted among men.`,
    elaborationEnglish: `Mantras 1467 & 1468

Jnana is the most exalted path and nothing else can confer final liberation. Mastery over consciousness, egoity, will and the mind's cognizational activity is real mastery in Jnana.`,
    elaborationTamil: `ஞானத்தை விட மேலானதாக அறியப் படுகின்ற நெறி முறைகள் என்று எதுவும் எந்த நாட்டிலும் இல்லை. ஞானத்தை மேலானது என்று எடுத்துக் கொள்ளாத எந்த சமயமும் நன்மையானது இல்லை. ஞானத்தை விட்டு விட்டு இருக்கின்ற எந்த வழிமுறையும் நன்மையான முக்தி நிலையை கொடுக்காது. ஆதலால், ஞானத்தில் மிகவும் மேன்மை பெற்றவர்களே மனிதர்களில் மிகவும் மேன்மையானவர் ஆவார்கள்.`,
  },
  {
    id: 1469, tantraId: 5, verseNumber: 1468,
    tamil: `சத்தமுஞ் சத்த மனனும் தகுமனம்
உய்த்த வுணர்வு முணர்த்தும் அகந்தையுஞ்
சித்தமென் றிம்மூன்றுஞ் சிந்திக்குஞ் செய்கையுஞ்
சத்தங் கடந்தவர் பெற்றசன் மார்க்கமே`,
    transliteration: `cattamuñ catta maṉaṉum takumaṉam
uytta vuṇarvu muṇarttum akantaiyuñ
cittameṉ ṟimmūṉṟuñ cintikkuñ ceykaiyuñ
cattaṅ kaṭantavar peṟṟacaṉ mārkkamē`,
    english: `1468: Jnani Transcends Nada
Out of the primal Principle of Sound (Nada)
The Mind springs;
And out of the Mind-Intelligence, Egoity and Will;
They who have mastered these three,
And the Mind's cogitational activity as well,
Verily have mastered Nada
And have truly attained Jnana.`,
    elaborationTamil: `ஞானத்தை பெறுகின்ற 1. மூல சத்தமும், அந்த சத்தம் நிலை பெற்று இருப்பதற்கு தகுதியான மனமும், அந்த மனதால் கிடைக்கப் பெற்ற 2. உண்மை உணர்வும், அதை உணர்ந்து கொண்டதால் அதற்கு காரணமாக இருப்பவர் என்று தெரிந்து கொண்ட 3. குருவும், சித்தம் என்று அழைக்கப் படுகின்ற இந்த மூன்றையும் எப்போதும் சிந்தித்துக் கொண்டே இருக்கின்ற செயலும், ஆகிய இவை அனைத்தும் சத்தங்களை கடந்து அதன் எல்லையாக இருக்கின்ற இறைவனை அறிந்து கொண்ட ஞானியர்கள் பெற்ற உண்மை வழியாகும்.`,
  },
  {
    id: 1470, tantraId: 5, verseNumber: 1469,
    tamil: `தன்பால் உலகுந் தனக்கரு காவதும்
அன்பா லெனக்கரு ளாவது மாவன
என்பார்கள் ஞானமும் எய்துஞ் சிவோகமும்
பின்பாலின் நேயமும் பெற்றிடுந் தானே`,
    transliteration: `taṉpāl ulakun taṉakkaru kāvatum
aṉpā leṉakkaru ḷāvatu māvaṉa
eṉpārkaḷ ñāṉamum eytuñ civōkamum
piṉpāliṉ nēyamum peṟṟiṭun tāṉē`,
    english: `1469: Stages of Attainment Through Jnana
Thus they say:
By devotion the Jiva first sojourns Lord's world;
Then comes to dwell in Lord's proximity;
Further on receives Lord's grace,
And in the end attains Jnana
In Sivohamic I and You union
Jiva shall himself Siva become.`,
    elaborationEnglish: `The different stages of attainment through Jnana are: jiva sojourning in the Lord’s world, in Lord's proximity, receiving the Lord’s Grace (form), and ultimately attaining union in Him.`,
    elaborationTamil: `தாம் சார்ந்து இருக்கின்ற உலகமும் அதில் நிகழ்கின்ற அனைத்தும் தமக்கு இறைவன் கொடுத்த அருள் என்று எடுத்துக் கொள்வதும் தம் மேல் கொண்ட அன்பினால் தமக்கு இறைவன் கொடுக்கின்ற அருளாகவே அனைத்தும் நிகழ்வதும் அதை நிகழ்த்துபவனாகவும் இறைவனே இருக்கின்றான் என்று ஞானிகள் கூறுவார்கள். இந்த ஞானிகளே இறையருளால் ஞானமும் பெற்று சிவத்தை அறியும் யோகமும் பெற்று இனிமையான பாலைப் போல இறைவனோடு அவர்கள் கொண்ட தூய்மையான அன்பினால் பேரின்பத்தையும் பெற்று இருக்கின்றார்கள்.`,
  },
  {
    id: 1471, tantraId: 5, verseNumber: 1470,
    tamil: `இருக்குஞ் சேம இடம்பிரமமாகும்
வருக்கஞ் சராசர மாகும் உலகந்
தருக்கிய ஆசார மெல்லாந் தருமே
திருக்கிலாஞானத்தைத் தேர்ந்துணர்ந் தோர்க்கே`,
    transliteration: `irukkuñ cēma iṭampiramamākum
varukkañ carācara mākum ulakan
tarukkiya ācāra mellān tarumē
tirukkilāñāṉattait tērntuṇarn tōrkkē`,
    english: `1470: Unitive Attainment of Jnani
Brahmam shall be his impregnable abode,
Universe, his kith and kin;
Diverse paths the world presents
All, all shall be his;
For, verily he has realized
The pure Jnana, free of doubt.`,
    elaborationEnglish: `The jnani deems Brahman as his impregnable abode,. the universe his kith and kin, and all contending faiths as one. He is truly the realised one.`,
    elaborationTamil: `இறைவனின் பிள்ளைகளாகிய ஞானிகளுக்கு அவர்கள் இருக்கின்ற இடமே வீடுபேறாக ஆகி விடும். ஆதியிலிருந்து தொடர்ந்து வருகின்ற அசையும் பொருளும் அசையா பொருளுமாக இருக்கின்ற இந்த உலகமே அவர் கடைபிடித்து வருகின்ற ஒழுக்கங்கள் அனைத்திற்கும் தகுதியான படி அமைந்து விடும். இது யாருக்கு என்றால் ஒரு பிழையும் இல்லாத உன்னதமான ஞானத்தை தமக்குள்ளே ஆராய்ந்து உணர்ந்து கொண்டவர்களாகிய ஞானிகளுக்கே ஆகும்.`,
  },
  {
    id: 1472, tantraId: 5, verseNumber: 1471,
    tamil: `அறிவும் அடக்கமும் அன்பும் உடனே
பிறியா நகர்மன்னும் பேரரு ளாளன்
குறியுங் குணமுங் குரைகழல் நீங்கா
நெறியறி வார்க்கிது நீர்த்தொனி யாமே`,
    transliteration: `aṟivum aṭakkamum aṉpum uṭaṉē
piṟiyā nakarmaṉṉum pēraru ḷāḷaṉ
kuṟiyuṅ kuṇamuṅ kuraikaḻal nīṅkā
neṟiyaṟi vārkkitu nīrttoṉi yāmē`,
    english: `1471: Jnana is Lifeboat
The Lord is of Infinite Grace,
In His Celestial City are Love, Light and Peace eternal,
To them that seek to know His Form
And understand His Attributes
And attain His Holy Feet
To them, this is the Path
This, this the boat to cross Life's turbulent waters.`,
    elaborationEnglish: `The Lord is of Infinite Grace, Love! Light and Peace Teign eternally in His celestial city. The ultimate path to cross life’s turbulent waters is to have an absolute cognition of the Lord, and so reach His Holy Feet.`,
    elaborationTamil: `உண்மையான அறிவும் பணிவுடைய எண்ணமும் இறைவன் மேல் கொண்ட அன்பும் அதனுடனே அடியவர்களை விட்டு என்றும் பிரியாமல் தில்லை சிற்றம்பலத்தில் நிலை பெற்ற திருநடனம் புரிகின்ற மிகப் பெரும் அருளை வழங்குவபனாகிய இறைவனை அடைவதையே குறிக்கோளாகக் கொண்டு இருக்கின்ற நல்ல குணமும் பேரழகு வாய்ந்த அவனின் திருவடிகளை எப்போதும் நினைத்துக் கொண்டே இருக்கின்ற மனதும் ஆகிய இவை அனைத்தையும் இறைவனை அடைவதற்கான வழியாக அறிந்து கொண்டவர்களுக்கு இந்த வழிமுறையே பிறவி எனும் பெரும் கடலை கடக்க உதவும் படகாக இருக்கும்.`,
  },
  {
    id: 1473, tantraId: 5, verseNumber: 1472,
    tamil: `ஞானம் விளைந்தெழு கின்றதோர் சிந்தையுள்
ஏனம் விளைந்தெதி ரேகாண வழிதோறுங்
கூனல் மதிமண் டலத்தெதிர் நீர்கண்டு
ஊனம் அறுத்துநின் றொண்சுட ராகுமே`,
    transliteration: `ñāṉam viḷainteḻu kiṉṟatōr cintaiyuḷ
ēṉam viḷainteti rēkāṇa vaḻitōṟuṅ
kūṉal matimaṇ ṭalattetir nīrkaṇṭu
ūṉam aṟuttuniṉ ṟoṇcuṭa rākumē`,
    english: `1472: Jnani Becomes Light Divine
In whose thoughts Jnana ripens and swells,
In his path the Life-Boat appears and greets him;
And thus does he reach the surging waters
Of the Crescent Moon's sphere,
And there, rid of Impurities,
He himself the Effulgent Light becomes.`,
    elaborationEnglish: `Mantras 1472 & 1473

The 'boat of life' (Jnana) aids the jnani to cross to the surging waters of the crescent moon's sphere. There, he becomes the divine light. Jnana embraces all the four paths - Chariya, Kriya, Yoga, and Jnana, and the jnani attains all the four stages they bring in.`,
    elaborationTamil: `பாடல் #1471 இல் உள்ளபடி இறைவனை அடைவதற்கு தேவையான வழிமுறையை அறிந்து கொண்டு அதை விடாமல் கடை பிடித்ததால் உண்மையான ஞானம் உருவாகி மேல் நிலைக்கு எழுந்து இருக்கின்ற ஒரு ஞானியின் சிந்தைனைக்கு உள்ளே இன்னமும் இறைவனை அடைவதற்கு தடையாக இருக்கின்ற ஆணவம் கன்மம் முதலிய குற்றங்கள் பிறவியின் காரணத்தினால் விளைந்து அவர் எதிர்கொள்கின்ற வாழ்க்கையை காட்டு வழி போல முழுவதும் கடினமாக வைத்து இருக்கும். அப்போது அவர் பெற்ற ஞானத்தின் பயனால் அவரது கடினமான வாழ்க்கையை மாற்றி அறிவு ஞானமாக இருக்கின்ற மண்டலத்தில் அமிழ்த நீரை வைத்து இருக்கும் சுழுமுனை நாடியின் வழியாக அமிழ்தத்தை ஊறச் செய்து இறைவனை அவர் அடைவதற்கு தடையாக இருக்கின்ற அனைத்து மலங்களையும் அதன் மூலம் நீக்கி விட்டு நிலைபெற்று நின்று எப்போதும் அவரோடு சேர்ந்தே இருக்கின்ற இறைவனின் ஜோதி வடிவமாகவே அவரையும் ஆக்கி விடும்.`,
  },
  {
    id: 1474, tantraId: 5, verseNumber: 1473,
    tamil: `ஞானிக் குடன்குண ஞானத்தில் நான்குமா
மோனிக் கிவையொன்றுங் கூடாமுன் மோகித்து
மேனிற்ற லாஞ்சத்தி வித்தை விளைத்திடுந்
தானிக் குலத்தோர் சரியை கிரியையே`,
    transliteration: `ñāṉik kuṭaṉkuṇa ñāṉattil nāṉkumā
mōṉik kivaiyoṉṟuṅ kūṭāmuṉ mōkittu
mēṉiṟṟa lāñcatti vittai viḷaittiṭun
tāṉik kulattōr cariyai kiriyaiyē`,
    english: `1473: Jnani's Attainments are Unique
For Jnani
All four paths are;
Not so for the Yogi until he becomes Mauni;
For him is Kundalini Yoga in ardour performed,
Chariya and Kriya too are his.`,
    elaborationTamil: `உண்மையான ஞானத்தை பெற்ற ஞானிக்கு அவருடனே இருக்கின்ற குணங்களாக ஞானத்தில் சேர்ந்து இருக்கின்ற சரியையில் முழுமை பெற்ற ஞானமும் கிரியையில் முழுமை பெற்ற ஞானமும் யோகத்தில் முழுமை பெற்ற ஞானமும் ஞானத்தில் முழுமை பெற்ற ஞானமும் ஆகிய நான்கு விதமான நிலைகள் இருக்கின்றன. இந்த நிலைகளை அடைந்து மௌன நிலைக்கு சென்று விட்ட ஞானிக்கு இந்த நான்கு நிலைகளில் ஒன்று கூட குணமாக சேர்ந்து இருப்பதற்கு முந்தைய காலத்தில் அவர் உலகப் பற்றுக்களில் மயங்கி இருக்கும் போது அவருக்கு மேல் நின்று அருளுகின்றதாகிய இறை சக்தியானது பாடல் #1471 இல் உள்ளபடி அவர் கடைபிடித்த வழிகளின் பயனால் விதையைப் போல ஞானம் விளைந்து விடும். அதன் பயனால் மௌன நிலை என்ற உச்சத்திற்கு சென்று நான்கு விதமான ஞான நிலைகளையும் தம்முடைய குணங்களாக கொண்ட இந்த ஞானியர்கள் அனைவரும் இனி இறைவனை அடைய வேண்டும் என்று சரியையும் கிரியையும் செய்கின்ற அனைத்து உயிர்களுக்கும் அதன் பலன்களை கொடுக்கின்ற இறை நிலையாக இருப்பார்கள்.`,
  },
  {
    id: 1475, tantraId: 5, verseNumber: 1474,
    tamil: `ஞானத்தின் ஞானாதி நான்குமா ஞானிக்கு
ஞானத்தின் ஞானமே நானென தென்னாமல்
ஞானத்தில் யோகமே நாதாந்த நல்லொளி
ஞானக் கிரியையே நன்முத்தி நாடலே`,
    transliteration: `ñāṉattiṉ ñāṉāti nāṉkumā ñāṉikku
ñāṉattiṉ ñāṉamē nāṉeṉa teṉṉāmal
ñāṉattil yōkamē nātānta nalloḷi
ñāṉak kiriyaiyē naṉmutti nāṭalē`,
    english: `1474: Attainments at Four Jnana Stages
The Jnani attains all the four stages in Jnana;
Jnana-in-Jnana is to transcend the "I" and "Mine"
Yoga-in-Jnana is to envision the Light of Nadanta;
Kriya-in-Jnana is to seek the liberation by good.`,
    elaborationEnglish: `Transcending the "I" and "Mine" is Jnana in Jnana; visualizing the light of Nadanta is Yoga in Jnana; and Kriya in Jnana is the search for liberation.`,
    elaborationTamil: `பாடல் #1473 இல் உள்ளபடி ஞானத்தில் முழுமை பெற்ற ஞானத்திற்கு முதலாக இருக்கின்ற நான்கு விதமான நிலைகளாக ஞானிக்கு இருப்பதில் ஞானத்தில் முழுமை பெற்ற ஞானமானது நான் இது எனது என்கின்ற எந்தவிதமான எண்ணமும் இல்லாமல் அனைத்தும் இறைவனே என்று இருக்கின்ற நிலையாகும். யோகத்தில் முழுமை பெற்ற ஞானமானது சத்தத்திற்கு எல்லையாக இருக்கின்ற நன்மையே வடிவான ஜோதியாகும். கிரிகையில் முழுமை பெற்ற ஞானமானது நன்மை தரும் முக்தியை தேடிச் செல்லுதல் ஆகும். சரியையில் முழுமை பெற்ற ஞானமானது இறைவனை நாடிச் சென்று அடைவது ஆகும்.`,
  },
  {
    id: 1476, tantraId: 5, verseNumber: 1475,
    tamil: `நண்ணிய ஞானத்தின் ஞானாதி நண்ணுவோன்
புண்ணிய பாவங் கடந்த பிணக்கற்றோன்
கண்ணிய நேயங் கரைஞானங் கண்டுளோன்
திண்ணிய சுத்தன் சிவமுத்தன் சித்தனே`,
    transliteration: `naṇṇiya ñāṉattiṉ ñāṉāti naṇṇuvōṉ
puṇṇiya pāvaṅ kaṭanta piṇakkaṟṟōṉ
kaṇṇiya nēyaṅ karaiñāṉaṅ kaṇṭuḷōṉ
tiṇṇiya cuttaṉ civamuttaṉ cittaṉē`,
    english: `1475: Jnani Attains Unitive Wisdom in the Absolute
He who realizes Jnana in its four divisions
He verily transcends the conflict of virtue and vice;
He has reached the farthest shores of Truth;
He has glimpsed the Mighty Object;
He is the Immaculate, Siddha, Siva Mukta.`,
    elaborationTamil: `தமக்கு கிடைக்கப் பெற்ற ஞானத்தில் முழுமை பெற்ற ஞானத்திற்கு முதலாக இருக்கின்ற ஞானத்தில் சரியை ஞானத்தில் கிரியை ஞானத்தில் யோகம் ஞானத்தில் ஞானம் ஆகிய நான்கு நிலைகளையும் கிடைக்கப் பெற்றவர்கள் புண்ணியம் பாவம் என்கின்ற நிலைகளை கடந்து நின்று எந்த விதமான பற்றுகளும் இல்லாமல் இருப்பவர்கள். மேன்மையான அன்பிற்கு எல்லையாக இருக்கின்ற இறை ஞானத்தை கண்டு அதிலேயே பேரன்பாக இருப்பவர்கள். இவர்களே உறுதியாக எந்தவிதமான மாசுக்களும் இல்லாமல் தூய்மையாக இருக்கின்ற சிவ நிலையில் முக்தியாக இருக்கின்ற சித்தர்கள் ஆகும்.`,
  },
  {
    id: 1477, tantraId: 5, verseNumber: 1476,
    tamil: `ஞானச் சமயமே நாடுந் தனைக் காண்டல்
ஞான விசேடமே நாடு பரோதய
ஞானநிர் வாணமே நன்றறி வானருள்
ஞானாபி டேகமே நற்குறு பாதமே`,
    transliteration: `ñāṉac camayamē nāṭun taṉaik kāṇṭal
ñāṉa vicēṭamē nāṭu parōtaya
ñāṉanir vāṇamē naṉṟaṟi vāṉaruḷ
ñāṉāpi ṭēkamē naṟkuṟu pātamē`,
    english: `1476: Initiation Rites in Jnana
In Jnana are initiation rites four;
Samaya initiates the search for the Self;
Visesha, the search for the Divine;
Nirvana for the descent of Lord's Grace;
Abhisheka for the attainment of Divine Guru's Holy Feet.`,
    elaborationTamil: `ஞானமானது சமயம் எனப்படுகின்ற சரியையில் முழுமையாக இருப்பது வெளியில் தேடி செல்லுகின்ற இறைவனை தனக்குள் கண்டு உணர்வது ஆகும். ஞானமானது விசேடம் எனப்படுகின்ற கிரியையில் முழுமையாக இருப்பது தாம் தேடுகின்ற பரம் பொருளாகிய இறைவன் தமக்குள்ளேயே ஞானமாக உருவாகுவது ஆகும். ஞானமானது நிர்வாணம் எனப்படுகின்ற யோகத்தில் முழுமையாக இருப்பது நன்மையை கொடுக்கின்ற நெறிகளாக இருக்கின்ற இறைவனின் அருளை பரிபூரணமாக பெறுவது ஆகும். ஞானமானது அபிடேகம் எனப்படுகின்ற ஞானத்தில் முழுமையாக இருப்பது நன்மையே வடிவாக குருநாதனாக இருக்கின்ற இறைவனின் திருவடிகளே ஆகும்.`,
  },
  {
    id: 1478, tantraId: 5, verseNumber: 1477,
    tamil: `சாற்றுஞ்சன் மார்க்கமாந் தற்சிவ தத்துவத்
தோற்றங் களான சுருதிச் சுடர்கண்டு
சீற்றம் ஒழிந்து சிவயோக சித்தராய்க்
கூற்றத்தை வென்றார் குறிப்பறிந் தார்களே`,
    transliteration: `cāṟṟuñcaṉ mārkkamān taṟciva tattuvat
tōṟṟaṅ kaḷāṉa curutic cuṭarkaṇṭu
cīṟṟam oḻintu civayōka cittarāyk
kūṟṟattai veṉṟār kuṟippaṟin tārkaḷē`,
    english: `1477: San Marga
They glimpsed the Light of Holy Scriptures,
The revealed word of the Self-Existent Sivam.
They lost the sense of ego,
Became Siddhas of SivaYoga,
And over Death triumphed;
Only they that had thus evolved
Knew meaning inner of Sanmarga.`,
    elaborationTamil: `எடுத்து சொல்லப் படுகின்ற உண்மையான வழியாக இருப்பது தாமே சிவமாக இருக்கின்ற தத்துவம் ஆகும். பல விதமாக காணுகின்ற அனைத்து தோற்றங்களாக இருக்கின்ற சத்தமும் வெளிச்சமுமாக இருக்கின்ற இறை தத்துவத்தை தமக்குள்ளே கண்டு உணர்ந்து அதன் பயனால் காமம் குரோதம் லோபம் மதம் மாச்சரியம் ஆகிய அனைத்தும் அழிந்து போய் சிவ யோகத்தையே சித்தமாக கொண்டு இருப்பவர்களாகி இறப்பு என்கின்ற ஒன்றை வென்று விட்டவர்களே இந்த சன் மார்க்கம் என்று சொல்லப் படுகின்ற இறை தத்துவத்தின் பொருளை அறிந்தவர்கள் ஆவார்கள்.`,
  },
  {
    id: 1479, tantraId: 5, verseNumber: 1478,
    tamil: `சைவப் பெருமைத் தனிநா யகன்நந்தி
உய்ய வகுத்த குருநெறி ஒன்றுண்டு
தெய்வச் சிவநெறி நன்மார்க்கஞ் சேர்ந்துய்ய
வையத்துள் ளார்க்கு வகுத்தவைத் தானே`,
    transliteration: `caivap perumait taṉinā yakaṉnanti
uyya vakutta kuruneṟi oṉṟuṇṭu
teyvac civaneṟi naṉmārkkañ cērntuyya
vaiyattuḷ ḷārkku vakuttavait tāṉē`,
    english: `1478: Nandi Showed Sanmarga Path
The peerless Master Nandi
Of Saivam honoured high,
He showed us a holy path
For Souls' redemption true
It is Siva's divine path, Sanmarga's path
For all world to tread
And for ever be free.`,
    elaborationTamil: `சைவம் எனும் வழிமுறைக்கு பெருமையளிக்கும் தனிப் பெரும் தலைவனாகவும் குருநாதராகவும் நிற்கின்ற இறைவன் ஆன்மாக்கள் மேல் நிலையை அடைவதற்கு அவரவரது பக்குவத்திற்கு ஏற்றபடி கொடுத்து அருளிய குரு வழி முறை ஒன்று இருக்கின்றது. அதுவே தெய்வ அம்சமாகிய சிவத்தை அடைகின்ற வழி முறை ஆகும். அதனுடன் உண்மை வழியாகிய தாமும் பார்க்கின்ற பொருளும் அந்த இறைவனாகவே இருக்கின்ற தத்துவமும் சேர்ந்து மேல் நிலையை அடைவதற்காக உலகத்தில் உள்ள அனைத்து உயிர்களுக்கும் அதனதன் பக்குவத்திற்கு ஏற்றபடி கொடுத்து வைத்து அருளுகின்றான் குரு நாதனாக நிற்கின்ற இறைவன்.`,
  },
  {
    id: 1480, tantraId: 5, verseNumber: 1479,
    tamil: `தெரிசிக்கப் பூசிக்கச் சிந்தனை செய்யப்
பரிசிக்கக் கீர்த்திக்கப் பாதுகஞ் சூடக்
குருபத்தி செய்யுங் குவலயத் தோர்க்குத்
தருமுத்திச் சார்பூட்டுஞ் சன்மார்க்கந் தானே`,
    transliteration: `tericikkap pūcikkac cintaṉai ceyyap
paricikkak kīrttikkap pātukañ cūṭak
kurupatti ceyyuṅ kuvalayat tōrkkut
tarumuttic cārpūṭṭuñ caṉmārkkan tāṉē`,
    english: `1479: Guru Adoration is Sanmarga
To see him, to adore him, to meditate on him
To touch him, to sing of him,
To bear his holy feet on humbled head,
They that render devotion to Guru
In diverse ways thus,
They indeed walk the Sanmarga path
That to liberation leads.`,
    elaborationTamil: `குருவை இறைவனாகவே தரிசிப்பதும் அவரை பூசிப்பதும் குருவின் திருவுருவத்தை தியானத்தில் சிந்தனை செய்வதும் குருவின் அருகாமையை அனுவிப்பதும் அவரது புகழை போற்றி பாடுவதும் அவரது திருவடிகளில் இருக்கும் பாதுகைகளை தமது தலை மேல் சூடுவதும் ஆகிய இவற்றை எல்லாம் செய்து தமது குருவுக்கு பக்தியை முறைப்படி செய்கின்ற உலகத்தவர்களுக்கு அதன் பயனால் தருகின்ற முக்தி நிலைக்கு சார்பாக இருந்து அனுபவிக்க வைப்பது உண்மையான வழியாகும்.`,
  },
  {
    id: 1481, tantraId: 5, verseNumber: 1480,
    tamil: `தெளிவறி யாதார் சிவனை யறியார்
தெளிவறி யாதார் சீவனு மாகார்
தெளிவறி யாதார் சிவமாக மாட்டார்
தெளிவறி யாதவர் தீரார் பிறப்பே`,
    transliteration: `teḷivaṟi yātār civaṉai yaṟiyār
teḷivaṟi yātār cīvaṉu mākār
teḷivaṟi yātār civamāka māṭṭār
teḷivaṟi yātavar tīrār piṟappē`,
    english: `1480: Sanmarga Gives the Vision True
They that have true Vision none,
Shall never Siva know;
Nor shall even Jivas be;
Nor indeed Siva become;
Never, never their birth's bondage broken be.`,
    elaborationEnglish: `Mantras 1480 & 1481

Sanmarga gives the true vision, breaking the fetters of birth and extinguishing the fire of impurities. Listening to the silent voice in Sanmarga you become a pure mukta, annihilating the state of 'I' and 'You' difference and savouring the divine bliss.`,
    elaborationTamil: `குருவின் அருளால் ஞானத் தெளிவை அறியாதவர்கள் சிவப் பரம்பொருளை அறிந்து கொள்ள மாட்டார்கள். அவர்கள் தமது ஆத்ம ஞானத்தில் முழுமை அடைய மாட்டார்கள். அவர்கள் சிவமாக ஆக மாட்டார்கள். அவர்களுக்கு எப்போதும் தீர்ந்து விடாமல் பிறவிகள் தொடர்ந்து கொண்டே இருக்கும்.`,
  },
  {
    id: 1482, tantraId: 5, verseNumber: 1481,
    tamil: `தானவ னாகித் தானைந்தா மலஞ்செற்று
மோனம தாம்மொழிப் பான்முத்த ராவது
மீனமில் ஞானானு பூதியில் இன்பமுந்
தாவை னாயுறலானசன் மார்க்கமே`,
    transliteration: `tāṉava ṉākit tāṉaintā malañceṟṟu
mōṉama tāmmoḻip pāṉmutta rāvatu
mīṉamil ñāṉāṉu pūtiyil iṉpamun
tāvai ṉāyuṟalāṉacaṉ mārkkamē`,
    english: `1481: Sanmarga Leads to Supreme Grace-Bliss
When you scorch Impurities five
And listen to the Voice of Silence
You become a pure Mukta;
And I and You in one merge;
And by the unsullied Grace Jnana grants
You shall joy of the Bliss Divine;
Verily, then by Sanmarga Path
You become He indeed .`,
    elaborationEnglish: `The voice of silence or mauna is what called the “harmony of the spheres,’’ — beyond words and forms — the experience of the infinite within us. Vide “‘Foundations of Tibetan by Lama Angarika Govinda, Part I.`,
    elaborationTamil: `குருவருளால் தெளிவு பெற்றவர்கள் தாம் சிவமாகவே ஆகுவதும் தம்மிடம் இருக்கின்ற ஆணவம் கன்மம் மாயை மாயேயம் திரோதாயி ஆகிய ஐந்து விதமான மலங்களையும் அழிப்பதும் மௌனம் என்று சொல்லப்படுகின்ற உச்ச நிலையில் எண்ணங்கள் அனைத்தையும் அழித்து முக்தி நிலை பெற்றவராக ஆகுவதும் ஒரு குறையும் இல்லாத பேரறிவு ஞானத்தை தமது அனுபவித்தில் உணர்ந்து அதில் பேரின்பம் பெறுவதும் தாமே சிவமாக ஆகி தான் எனும் எண்ணமே இல்லாமல் இருப்பதும் ஆகிய இவை அனைத்துமே உண்மையான வழிகளாகும். ஐந்து விதமான மலங்கள் ஆணவம் – செருக்கு, மமதை கன்மம் – வினைப் பயன் மாயை – பொய்யான தோற்றம் மாயேயம் – அசுத்த மாயை திரோதாயி – உண்மையை மறைத்தல்`,
  },
  {
    id: 1483, tantraId: 5, verseNumber: 1482,
    tamil: `சன்மார்க்கத் தார்க்கு முகத்தொடு பீடமுஞ்
சன்மார்க்கத் தார்க்கும் இடத்தொடு தெய்வமுஞ்
சன்மார்க்கத் தார்க்கு வருக்கந் தரிசனம்
எம்மார்க்கத் தார்க்கும் இயம்புவன் கேண்மினோ`,
    transliteration: `caṉmārkkat tārkku mukattoṭu pīṭamuñ
caṉmārkkat tārkkum iṭattoṭu teyvamuñ
caṉmārkkat tārkku varukkan taricaṉam
emmārkkat tārkkum iyampuvaṉ kēṇmiṉō`,
    english: `1482: Greatness of Sanmargis
The visage of Sanmargi is Pedestal of Sakti
Where Sanmargi is there God is,
To see assemblage of Sanmargis is to vision Lord,
This I proclaim,
To whatsoever path you do incline.`,
    elaborationEnglish: `The face of the Sanmargi.is the pedestal of Sakti; the place of the Sanmargi is the seat of God. Whatever path may be followed, to see assemblages of Sanmargis is to see the Lord.`,
    elaborationTamil: `உண்மையான வழியை பின்பற்றி முக்தி நிலையில் சிவமாகவே இருக்கின்றவர்களின் முகமே இறைவன் அமர்ந்து இருக்கின்ற பீடமாகவும் அவர்கள் இருக்கின்ற இடமே இறைவன் வீற்றிருக்கின்ற கோயிலாகவும் அவர்களின் கூட்டத்தை காண்பதே இறைவனின் தரிசனமாகவும் இருக்கின்றது. தாமும் பார்க்கின்ற பொருளும் சிவமாகவே இருக்கின்ற உண்மையை தெரிந்து கொள்ளுகின்ற வழியை தேடுகின்ற அனைவருக்கும் இதுவே வழி என்று யான் எடுத்து சொல்கின்றேன் கேட்டுக் கொள்ளுங்கள்.`,
  },
  {
    id: 1484, tantraId: 5, verseNumber: 1483,
    tamil: `சன்மார்க்க சாதனந் தான்ஞான ஞேயமாம்
பின்மார்க்க சாதனம் பேதையர்க்காய்நிற்கும்
துன்மார்க்கம் விட்ட துரியத் துரிசற்றார்
சன்மார்க்கந் தானவ னாகுஞ்சன் மார்க்கமே`,
    transliteration: `caṉmārkka cātaṉan tāṉñāṉa ñēyamām
piṉmārkka cātaṉam pētaiyarkkāyniṟkum
tuṉmārkkam viṭṭa turiyat turicaṟṟār
caṉmārkkan tāṉava ṉākuñcaṉ mārkkamē`,
    english: `1483: Sanmarga Path Purest
Alone of all paths
Sanmarga grants God-head through knowledge;
The rest of paths are for un-illumined;
Renouncing the ways of impurities
And transcending limits of Turiya
It merges I in You;
Verily, Sanmarga is Path Purest.`,
    elaborationEnglish: `Sanmarga is the purest path that grants the experience of God-head through knowledge. The rest are unillumined and uninspiring. It is the way of renouncing impurities and transcending the limits of turiya consciousness. It is the way of I becoming He.`,
    elaborationTamil: `உண்மையான வழிக்கு உதவுகின்ற கருவியாக இருப்பது ஞானத்தின் மூலம் அன்பு வடிவமாக இருக்கின்ற இறைவனை உணர்ந்து கொள்ளுவது ஆகும். மற்ற வழிகளுக்கு கருவியாக இருக்கின்ற அனைத்தும் அறியாமையில் இருப்பவர்களுக்கு பெற முடியாததாகவே நிற்கின்றது. தீய வழிகளை நீக்கி விட்ட ஆழ்நிலை தியான நிலையில் அழுக்குகள் எதுவும் இல்லாதவர்களாக பேரின்பத்தில் இருப்பதுவே உண்மையான வழி முறையில் தாமே சிவம் ஆகுகின்ற சன் மார்க்க வழியாகும்.`,
  },
  {
    id: 1485, tantraId: 5, verseNumber: 1484,
    tamil: `சன்மார்க்க மெய்த வருமருஞ் சீடர்க்குப்
பின்மார்க்க மூன்றும் பெறவியல் பாமென்றால்
நன்மார்க்கந் தானே சிவனொடு நாடலே
சொன்மார்க்க மென்னச்சுருதிகைக்கொள்ளுமே`,
    transliteration: `caṉmārkka meyta varumaruñ cīṭarkkup
piṉmārkka mūṉṟum peṟaviyal pāmeṉṟāl
naṉmārkkan tāṉē civaṉoṭu nāṭalē
coṉmārkka meṉṉaccurutikaikkoḷḷumē`,
    english: `1484: Other Three Paths Open of Themselves
Unto that rare seeker in Sanmarga path
The rest of three paths, of themselves open;
That alone is True Path union with Siva seeks;
Seek that Path
As Guiding Word scriptures proclaim.`,
    elaborationEnglish: `To the aspirant after Sanmarga, the other three paths open of themselves. It is the sole path, the True Path which scriptures enjoin for uniting in Siva.`,
    elaborationTamil: `உண்மையான வழி முறையை அனைவரும் ஏற்றுக் கொள்ளும் படி சிறப்பிக்க வருகின்ற பெருமை பெற்ற சீடர்களுக்கு அதற்கு பிறகு இருக்கின்ற வழி முறைகளாகிய சக மார்கம் சற்புத்திர மார்கம் தாச மார்கம் ஆகிய மூன்றும் பிறவியிலேயே இயல்பாக கிடைத்து விடுகின்றது. ஏன் என்றால் நன்மையான வழி முறையானது அவர்கள் சிவப் பரம்பொருளோடு சேர்ந்து இருப்பதை விரும்பி தேடிக்கொண்டே இருப்பதால் ஆகும். ஆகவே குரு தமது சீடர்களுக்கு அறிவுறுத்தக் கூடிய வழி முறைகளாக வேதங்கள் கொடுத்த அனைத்து முறைகளும் அவர்களுக்கு கைவரப் பெறும்.`,
  },
  {
    id: 1486, tantraId: 5, verseNumber: 1485,
    tamil: `அன்னிய பாசமும் ஆகுங் கருமமும்
முன்னும் அவத்தையும் மூலப் பகுதியும்
பின்னிய ஞானமும் பேதாதி பேதமுந்
தன்னொடுங் கண்டவர் சன்மார்க்கத் தோரே`,
    transliteration: `aṉṉiya pācamum ākuṅ karumamum
muṉṉum avattaiyum mūlap pakutiyum
piṉṉiya ñāṉamum pētāti pētamun
taṉṉoṭuṅ kaṇṭavar caṉmārkkat tōrē`,
    english: `1485: Sanmargi's Vision
The bondage that keeps Jiva an alien to God,
The Karmas that flow from it,
The avastas that the Self experiences,
The Primordial Stuff that is Matter's nucleus,
The Consciousness that entwines it,
The million, million mutations that pervade the universe,
They who see them all and their own Selves
Verily are they the Sanmargis true.`,
    elaborationTamil: `தனக்கு வேறாகவும் தன்னை அடிமைப்படுத்தியும் தன்னுள் அடங்கியும் இருக்கின்ற பாசத்தையும் அதற்கு காரணமாகும் கர்மத்தையும் அந்த கர்மத்தின் பயனால் அனுபவிக்கின்ற அனைத்து வாழ்க்கை அனுவங்களையும் அந்த அனுபங்களுக்கு மூலமாக இருக்கின்ற ஆசைகளையும் அதனோடு பின்னிப் பிணைந்து இருக்கின்ற பாசக் கட்டுகளையும் அதனோடு சேர்ந்து இருக்காமல் விலகி இருக்கின்ற ஆன்மாவையும் ஆதியில் முதன் முதலில் அந்த ஆன்மா இறைவனை விட்டுப் பிரிந்து வந்த காரணத்தையும் தமக்கு உள்ளும் வெளியிலும் கண்டு அறிந்து கொண்டவர்களே உண்மையான வழியை கடை பிடிப்பவர்கள் ஆவார்கள்.`,
  },
  {
    id: 1487, tantraId: 5, verseNumber: 1486,
    tamil: `பசுபாச நீக்கிப் பதியுடன் கூட்டிக்
கசியாத நெஞ்சங் கசியக் கசிவித்
தொசியாத வுண்மைச் சொரூபோ தயத்துற்
றசைவான தில்லாமை யானசன் மார்க்கமே`,
    transliteration: `pacupāca nīkkip patiyuṭaṉ kūṭṭip
kaciyāta neñcaṅ kaciyak kacivit
tociyāta vuṇmaic corūpō tayattuṟ
ṟacaivāṉa tillāmai yāṉacaṉ mārkkamē`,
    english: `1486: Sanmarga Leads to Svarupa State
Rending the Soul's bonds asunder
Conjoining him to the Lord
Melting the heart that knew no melting
Merging into the Primal Manifestness (Svarupa)
That is Truth Eternal
Sanmarga verily gives Jiva
The rest that knows no commotion ever.`,
    elaborationTamil: `ஆன்மாவில் இருகின்ற “நான்” எனும் எண்ணத்தையும் பாசத் தளைகளையும் நீக்கி இறைவனுடன் ஒன்று சேர்த்து எதனாலும் உருகாமல் இருக்கின்ற நெஞ்சத்தையும் இறைவனின் மேல் கொண்ட தூய அன்பினால் உருகும் படி உருக வைத்து ஒரு ஆன்மாவாக இருப்பதுவே இறைவனின் பேருண்மை சுய உருவமாக இருக்கின்றது என்கின்ற எண்ணத்தை உருவாக்கி அதனை உணர வைத்து அதிலேயே இலயிக்க வைத்து அசைவில்லாமல் இருக்கும்படி ஆக்குகின்றது உண்மை வழியாகும்.`,
  },
  {
    id: 1488, tantraId: 5, verseNumber: 1487,
    tamil: `மார்க்கஞ்சன் மார்க்கிகள் கிட்ட வகுப்பது
மார்க்கஞ்சன் மார்க்கமே யன்றிமற் றொன்றில்லை
மார்க்கஞ்சன் மார்க்க மெனுநெறி வைகாதோர்
மார்க்கஞ்சன் மார்க்க மாஞ்சித்த யோகமே`,
    transliteration: `mārkkañcaṉ mārkkikaḷ kiṭṭa vakuppatu
mārkkañcaṉ mārkkamē yaṉṟimaṟ ṟoṉṟillai
mārkkañcaṉ mārkka meṉuneṟi vaikātōr
mārkkañcaṉ mārkka māñcitta yōkamē`,
    english: `1487: Sanmarga is Only Path to Finite Goal
That alone is Path Divine
The Sanmargis for Goal ordain;
Other Path there is none,
Than this path to the One;
They that straight reach it not,
Through Yoga's Path may yet climb.`,
    elaborationTamil: `தாமும் பார்க்கின்ற பொருளும் சிவமாகவே இருப்பதை உணர்கின்ற வழியாகிய உண்மை வழி முறையை கடைபிடிப்பவர்கள் முறைப்படி கட்டமைத்து வகுத்து வைத்த நெறி முறைகள் அல்லாமல் வேறு ஒரு வழி முறைகளும் இல்லை. உண்மை வழி முறை என்று சொல்லப்படும் அந்த நெறி முறைகளை வகுத்து வைத்த முறைப்படி தவறாமல் காத்து கடை பிடிப்பவர்களுக்கு எண்ணத்தை எல்லாம் சிவப் பரம்பொருளின் மேல் வைத்து செய்கின்ற மிகவும் உயர்ந்த யோகமாக அந்த உண்மை வழியே இருக்கின்றது.`,
  },
  {
    id: 1489, tantraId: 5, verseNumber: 1488,
    tamil: `சன்மார்க்கந் தானே சகமார்க்க மானது
மன்மார்க்க மாமுத்தி சித்திக்குள் வைப்பதாம்
பின்மார்க்க மானது பேராப் பிறந்திறந்
துன்மார்க்க ஞானத் துறதியு மாமே`,
    transliteration: `caṉmārkkan tāṉē cakamārkka māṉatu
maṉamārkka māmutti cittikkuḷ vaippatām
piṉmārkka māṉatu pērāp piṟantiṟan
tuṉmārkka ñāṉat tuṟatiyu māmē`,
    english: `1488: Sahamarga Leads to Sanmarga3Sahamarga (Yoga)
blossoms into Sanmarga,
Through Siddhi it leads to Supreme Mukti;
It is the Path lower to Sanmarga,
Involving myriad birth and death
But eventually landing in Jnana Finite.`,
    elaborationTamil: `உண்மை வழியில் ஞானம் பெற்ற சாதகர்களுக்கு தானாகவே இறைவன் தோழமையுடன் வழிகாட்டும் நெறி முறையாக சக மார்கம் [தோழமை வழிமுறை] இருக்கின்றது. இதுவே எப்போதும் நிலைத்து நிற்கின்ற வழியாக இருந்து முக்தி பேறு அடைவதற்கும் நினைப்பதை எல்லாம் செயல்பட வைப்பது ஆகவும் இருக்கின்றது. இதற்கு நேர் எதிரான வழியில் செல்பவர்கள் இடைவிடாமல் பிறவி எடுத்து இறந்து மீண்டும் மீண்டும் மனம் செல்லுகின்ற வழியில் செல்லும் போதும் இறைவன் தோழமையுடன் மறைந்து இருந்து ஒரு காலத்தில் உண்மை ஞானம் உறுதியாக கிடைக்கும் படி அருளுவார். கருத்து: உண்மை வழியில் ஞானம் பெற்றவர்களுக்கு இறைவன் தோழமையாக அருகிலேயே இருந்து நினைப்பது அனைத்தையும் செயல் படுத்துகின்றார். எந்த வழிமுறையையும் பின் பற்றாமல் மனம் போன போக்கில் வாழ்ந்து இறந்து மீண்டும் மீண்டும் பிறவி எடுத்தாலும் இறைவன் தோழமையாக மறைந்து இருந்து வழிகாட்டி ஒரு காலத்தில் ஞானம் பெறும் படி அருளுவார்.`,
  },
  {
    id: 1490, tantraId: 5, verseNumber: 1489,
    tamil: `மருவுந் துவாதச மார்க்கமில் லாதார்
குருவுஞ் சிவனுஞ் சமயமுங் கூடாம்
வெருவுந் திருமகள் வீட்டில்லை யாகும்
உருவுங் கிளையும் ஒருங்கிழப் பாரே`,
    transliteration: `maruvun tuvātaca mārkkamil lātār
kuruvuñ civaṉuñ camayamuṅ kūṭām
veruvun tirumakaḷ vīṭṭillai yākum
uruvuṅ kiḷaiyum oruṅkiḻap pārē`,
    english: `1489: Without Sahamarga They Lost All
They that follow not twelve-tiered Path of Sahamarga,
Neither will they know Guru nor God, nor Faith True;
The Goddess of Grace will frown at them;
Salvation shall never their portion be;
And they do lose both-
Their stature and kith.`,
    elaborationTamil: `தியானத்தின் மூலம் தலைக்கு மேலே பன்னிரண்டு அங்குல தூரத்தில் இருக்கின்ற துவாதச வெளியில் இருக்கின்ற இறைவனை அறிகின்ற யோக வழிமுறையை அறிந்து கொள்ளாதவர்களும் குருவின் மூலம் ஞானத்தை பெறாதவர்களும் இறைவன் மேல் பக்தி செய்யாதவர்களும் இறைவனை வழிபடும் தமது குல வழக்கத்தை கைவிடுபவர்களும் ஆகிய இவர்களுடன் சேர்ந்து இருப்பது வீண் என்று லட்சுமி தேவியும் அவர்களை விட்டு வேண்டாம் என்று விலகி விடுவாள். அவர்களின் உடலும் உடலைச் சுற்றி இருக்கின்ற நன்மைகளும் அழிந்து இழந்து விடுவார்கள். கருத்து: உயர்ந்த மனித பிறவி என்பது இறைவனை அறிந்து கொண்டு அவனை அடைவதற்காக அருளப்பட்டது. இதில் இறைவனை அடையும் வழிகளாக பக்தி கர்மம் யோகம் ஞானம் ஆகிய நான்கு வழிகளை தோழமையுடன் உடனிருந்து இறைவன் அருளியிருந்தும் இது எதையுமே பின்பற்றாமல் ஆசையின் வழியில் செல்பவர்களை விட்டு தோழமையுடன் இருந்த இறைவன் விலகி நிற்பதால் அவர்களின் உயர்ந்த பிறவிக்கான நன்மைகள் அழிந்து போய் அடுத்த பிறவியில் கீழ் நிலை பிறவிக்கு சென்று விடுவார்கள்.`,
  },
  {
    id: 1491, tantraId: 5, verseNumber: 1490,
    tamil: `யோகச் சமாதியின் உள்ளே யகலிடம்
யோகச் சமாதியின் உள்ளே யுளரொளி
யோகச் சமாதியின் உள்ளே யுளசத்தி
யோகச் சமாதி யுகந்தவர் சித்தரே`,
    transliteration: `yōkac camātiyiṉ uḷḷē yakaliṭam
yōkac camātiyiṉ uḷḷē yuḷaroḷi
yōkac camātiyiṉ uḷḷē yuḷacatti
yōkac camāti yukantavar cittarē`,
    english: `1490: Fruits of Yoga Samadhi
In Yoga Samadhi is Space Infinite;
In Yoga Samadhi is Light Abiding;
In Yoga Samadhi is Sakti Omnipotent;
They that joy in Yoga Samadhi
Are verily Siddhas great.`,
    elaborationEnglish: `Mantras 1490 & 1491

Infinite space, abiding light, omnipotent Sakti are the fruits of yoga samadhi. The immortal yogi can enjoy bhoga which confers earthly blessings, and yoga which can confer Siva-Form on him.`,
    elaborationTamil: `யோகம் என்று அறியப் படுகின்ற சாதனையானது ஆதியாக இருக்கின்ற இறைவனின் உள்ளேயே அடங்கி அண்ட சராசரங்கள் அனைத்திலும் இறைவனோடு இடம் பெற்று இருக்கின்றது. அந்த யோகத்தில் ஆழ்ந்து இருக்கின்ற சமாதி நிலையில் சாதகருக்கு உள்ளே என்றும் நிலைபெற்று இருக்கின்ற ஒளியாக இறைவன் இருக்கின்றான். அந்த ஒளியாகிய இறைவனின் சக்தியை சமாதி நிலையில் இருந்து கொண்டே அனுபவித்துக் கொண்டு பேரின்பத்திலேயே திளைத்து இருக்கின்ற சாதகர்களே சித்தர்கள் ஆவார்கள்.`,
  },
  {
    id: 1492, tantraId: 5, verseNumber: 1491,
    tamil: `யோகமும் போகமும் யோகியர்க் காகுமால்
யோகஞ் சிவரூபம் உற்றிடும் உள்ளத்தோர்
போகம் புவியிற் புருடார்த்த சித்திய
தாகும் இரண்டும் அழியாத யோகிக்கே`,
    transliteration: `yōkamum pōkamum yōkiyark kākumāl
yōkañ civarūpam uṟṟiṭum uḷḷattōr
pōkam puviyiṟ puruṭārtta cittiya
tākum iraṇṭum aḻiyāta yōkikkē`,
    english: `1491: Yoga Confers Blessings of Here and Hereafter
Both yoga and bhoga, yogis may have;
Through yoga is attained Siva's Form divine;
Through bhoga all earthly blessings;
Thus may he enjoy both-he, Yogi immortal.`,
    elaborationTamil: `யோகமும் அதனால் கிடைக்கின்ற பேரின்பமும் யோக சாதனை புரிகின்ற யோகியர்களுக்கே அவர்களின் தகுதிக்கு ஏற்றவாறு கிடைக்கும். யோகத்தில் இறைவனின் ஒளி உருவத்தை தமக்குள்ளே தரிசிக்கின்ற யோகியர்களின் உள்ளத்திற்குள் என்றும் இடைவிடாத இறை சிந்தனையாக இருக்கின்ற ஒரு யோகமே இந்த உலகத்தில் இருக்கின்ற யோகியர்களின் ஆன்மாவிற்கு ஆதியாகிய பரமாத்மாவின் அருள் சக்தியாக கிடைக்கும். அந்த அருள் சக்தியால் உடல் மனம் ஆகிய இரண்டும் என்றும் அழியாமல் இருக்கின்ற நிலையை யோகியர்கள் பெறுவார்கள்.`,
  },
  {
    id: 1493, tantraId: 5, verseNumber: 1492,
    tamil: `ஆதார சோதனை யானாடி சுத்திகள்
மேதாதி யீரெண் கலாந்தத்து விண்ணொளி
போதா லயத்துப் புலன்கர ணம்புந்தி
சாதா ரணங்கெட லாஞ்ச மார்க்கமே`,
    transliteration: `ātāra cōtaṉai yāṉāṭi cuttikaḷ
mētāti yīreṇ kalāntattu viṇṇoḷi
pōtā layattup pulaṉkara ṇampunti
cātā raṇaṅkeṭa lāñca mārkkamē`,
    english: `1492: Yoga Leads to Supreme Awareness
Through this path of Sahamarga
The Yogis pierce the Adharas
And the Nadis they purify;
Envision the Kalas sixteen,
And glimpse their heavenly radiance;
And then are they merged in Awareness Supreme
Their organs of sense, internal and external,
All atrophied.`,
    elaborationEnglish: `Mantras 1492 & 1493

Through Sanmarga, the yogis pierce the adharas, purify the nadis, vision the sixteen kalas, glimpse their heavenly radiance, internal and external organs atrophied - and merge in the supreme consciousness. The yogi, who harries and subdues the five contentious with the sharp sword of steadfastness, merges in the consciousness of the Lord whom the eighteen heavenly hosts seek.`,
    elaborationTamil: `சாதனைகளின் மூலம் உடலுக்குள் இருக்கின்ற ஆறு ஆதார சக்கரங்களையும் ஆராய்ச்சி செய்து அதன் வழியாக உடலுக்குள் இருக்கின்ற நாடிகளை சுத்தம் செய்து உடல் இயக்கத்திற்கு காரணமாக இருக்கின்ற மேதைக் கலை முதலாகிய பதினாறு கலைகளோடு விண்ணில் இருக்கின்ற ஒளி வடிவமான இறை சக்தியானது கலந்தது. அதன் பிறகு அறிவின் ஆலயமாக இருக்கின்ற உடலுக்குள் இருக்கின்ற ஐந்து புலன்களும் நான்கு கரணங்களும் புத்தியும் தங்களின் இயல்பான செயல்களை இழந்து இறை நிலையை பெறுவதே இறைவனோடு தோழமையாக இருக்கின்ற வழி முறையாகும். உயிர்களின் உடலின் இயக்கத்திற்கு காரணமாக இருக்கின்ற பதினாறு கலைகள்: மேதைக்கலை அருக்கீசக்கலை விடக்கலை விந்துக்கலை அர்த்தசந்திரன் கலை நிரோதினிக்கலை நாதக்கலை நாதாந்தக்கலை சக்திக்கலை வியாபினிக்கலை சமனைக்கலை உன்மனைக்கலை வியோமரூபினிக்கலை அனந்தைக்கலை அனாதைக்கலை அனாசிருதைக்கலை ஐந்து புலன்கள்: கண் – பார்த்தல் காது – கேட்டல் மூக்கு – நுகர்தல் வாய் – பேசுதல் தோல் – தொடுதல் நான்கு அந்தக்கரணங்கள்: மனம் புத்தி சித்தம் அகங்காரம்`,
  },
  {
    id: 1494, tantraId: 5, verseNumber: 1493,
    tamil: `பிணங்கிநிற் கின்றவை ஐந்தையும் பின்னை
அணங்கி யெறிவ னயிர்மன வாளாற்
கணம்பதி னெட்டுங் கருதும் ஒருவன்
வணங்கவல் லான் சிந்தை வந்துநின் றானே`,
    transliteration: `piṇaṅkiniṟ kiṉṟavai aintaiyum piṉṉai
aṇaṅki yeṟiva ṉayirmaṉa vāḷāṟ
kaṇampati ṉeṭṭuṅ karutum oruvaṉ
vaṇaṅkaval lāṉ cintai vantuniṉ ṟāṉē`,
    english: `1493: Siva is in Yogi's Thought
He harries and subdues the conflicting senses five
With the sharp sword of his determinate will;
In his thought emerges Lord
Whom the eighteen Ganas seek;
Verily, the yogi deserves our obeisance.`,
    elaborationTamil: `தமது ஆன்மாவோடு ஒன்றாக பிணைந்து தோழமையுடன் நிற்கின்ற எமது தந்தையாகிய இறைவனை அறிந்து கொள்ளாமல் இருக்கின்ற உயிரும் அந்த உயிரை வருத்தக் கூடிய கர்மங்களையும் உயிரின் நுண்ணியமான மனம் என்கின்ற கூர்மையான வாளைக் கொண்டு தமது அருளால் அறுத்து எறிகின்றான் இறைவன். பதினெட்டு வகையான தேவ கணங்களாலும் எப்போதும் எண்ணப் படுகின்ற ஒருவனாகிய இறைவனை தமக்குள்ளேயே அறிந்து வணங்கும் வல்லமை பெற்ற சாதகரின் சிந்தைக்குள் அந்த இறைவன் தோழமையுடன் வந்து நின்று அருளுகின்றான். 18 விதமான தேவ கணங்கள்: சுரர் – உலக இயக்கத்திற்கு உதவும் தேவ லோகத்து தேவர்கள். சித்தர் – இறை நிலையில் இருப்பவர்கள். அசுரர் – அசுரர்கள். தைத்தியர் – அரசுரர்களில் ஒரு பிரிவினரான தானவர்கள். கருடர் – கருடர்கள். கின்னரர் – நடனம் ஆடுவதில் வல்லவர்கள். நிருதர் – அரக்கர்கள். கிம்புருடர் – யாளி என்று அழைக்கப்படும் சிங்க முகமும் மனித உருவமும் கொண்ட கணங்கள். காந்தர்வர் – கந்தவர்கள் (தேவர்களுக்கு அடுத்த நிலை). இயக்கர் – யட்சர்கள். விஞ்சையர் – கலைகளில் பெரும் ஞானம் உடையவர்கள். பூதர் – சிவனுக்கு சேவர்களாக இருக்கும் பூத கணங்கள். பிசாசர் – கொடூரமான கோபக் குணத்துடன் வடிவமற்றவர்கள். அந்தரர் – சுவர்க்க லோகத்தில் இருக்கும் தேவர்கள். யோகர் – ரிஷிகளும் முனிவர்களும். உரகர் – நாகர்கள். ஆகாய வாசர் – விண்ணுலக வாசிகள். விண்மீன் நிறைகணம் – நட்சத்திர மண்டலங்களில் நிறைந்திருக்கும் கணங்கள்.`,
  },
  {
    id: 1495, tantraId: 5, verseNumber: 1494,
    tamil: `வளங்கனி யொக்கும் வளநிறத் தார்க்கும்
வளங்கனி யொப்பதோர் வாய்மைய னாகும்
உளங்கனிந் துள்ள முகந்திருப் பார்க்குப்
பழங்கனிந் துள்ளே பகுந்துநின் றானே`,
    transliteration: `vaḷaṅkaṉi yokkum vaḷaniṟat tārkkum
vaḷaṅkaṉi yoppatōr vāymaiya ṉākum
uḷaṅkaṉin tuḷḷa mukantirup pārkkup
paḻaṅkaṉin tuḷḷē pakuntuniṉ ṟāṉē`,
    english: `1494: Love Basis of Yoga
Even for the Yogi austere
Who attains the glossy hue of the rich ripe fruit
The Lord is hard of shell unto the wood-apple fruit,
But to them whose hearts ripe in love,
And taste the sweets of divine rapture,
He opens all of Himself
Unto a rich fruit mature.`,
    elaborationEnglish: `Loving hearts can taste the sweetness of divine’ rapture and the Lord reveals Himself as a fully ripened fruit.`,
    elaborationTamil: `செழுமையாக பழுத்த பழத்தை போலவே செழுமையாக பிரகாசிக்கின்ற தேஜஸான உடலை பெற்று இருக்கின்ற அடியவர்களுக்கு அவர்களுடைய தேகம் செழுமை பொருந்திய பழுத்த பழத்தைப் போல இருப்பதற்கு காரணம் அவர்களுடைய வாழ்க்கை முழுவதும் தவறாமல் கடைபிடித்த ஒரு வாய்மை எனும் தர்மத்தினால் ஆகும். அந்த அடியவர்களது உள்ளமானது இறைவன் மேல் கொண்ட தூய்மையான அன்பினால் கனிந்து இருப்பதனாலும் அவர்கள் கடைபிடித்து வந்த தர்மத்தின் பயனாலும் எப்போதும் இன்பத்தோடு இருக்கின்றார்கள். நன்றாக பழுத்த பழத்திற்குள் கனிந்து இருக்கும் சுவை போலவே அவர்களின் பழுத்த பழம் போன்ற உள்ளுக்குள் சுவை போல சேர்ந்து தோழமையுடன் நிற்கின்றான் இறைவன். கருத்து: எந்த மார்க்கத்தையும் கடை பிடிக்காவிட்டாலும் சத்தியத்தையும் தர்மத்தையும் ஒருவர் தமது வாழ்நாள் முழுவதும் கடை பிடித்து வந்தால் அவர்களுக்குள் தோழமையுடன் இறைவன் எப்போதும் சேர்ந்து இருப்பான்.`,
  },
  {
    id: 1496, tantraId: 5, verseNumber: 1495,
    tamil: `மேவிய சற்புத்திர மார்க்க மெய்த்தொழில்
தாவிப்ப தாஞ்சக மார்க்கம் சகத்தொழில்
ஆவ திரண்டும் அகன்று சகமார்க்கத்
தேவியோ டொன்றல் சன்மார்க்கத் தெளிவதே`,
    transliteration: `mēviya caṟputtira mārkka meyttoḻil
tāvippa tāñcaka mārkkam cakattoḻil
āva tiraṇṭum akaṉṟu cakamārkkat
tēviyō ṭoṉṟal caṉmārkkat teḷivatē`,
    english: `1495: Path of Filial Piety Leads to Jnana
The Path of Filial Piety is the Way of Kriya true;
The Kriya Path leads to Yoga Path;
Transcending both,
And uniting in Sakti of Yoga State
Indeed is consummation of Sanmarga Path.`,
    elaborationEnglish: `Mantras 1495 & 1496

The path of filial piety, through Yoga (Saha marga) leads to Jnana, which consummates the Sanmarga path. Performing pujas, reading the holy scriptures, praising the Lord, chanting His Holy Name, practicing tapas, being truthful, bearing no malice - these constitute the path of filial piety of Kriya.
Mular refers to Kriya(Rituals) as Satputra Marga (or the path of 'pious son').`,
    elaborationTamil: `உறவினால் உண்மையான தந்தையாக இறைவனையும் அவருக்கு பிள்ளையாக தம்மையும் பாவிக்கின்ற வழி முறையானது உடலால் செய்கின்ற அனைத்து விதமான செயல்கள் மற்றும் சரியாக செய்ய வைக்க இறை சக்தி உடனிருந்து தோழமை வழி முறையில் மனதுடன் எப்போதும் சேர்ந்து இருந்து செய்கின்ற அனைத்து விதமான செயல்கள் ஆகிய இந்த இரண்டு விதமான செயல்களையும் நாம் செய்கின்றோம் என்கின்ற எண்ணமும், நமது உடலும் மனமும் இவற்றை செய்கின்றன என்கின்ற எண்ணமும் நீங்கும் படி செய்து, தோழமை வழி முறையில் தம்மோடு எப்போதும் தொடர்ந்து வருகின்ற இறை சக்தியோடு ஒன்றாக சேர்ந்து அனைத்தையும் இறை சக்தியே செய்கிறது என்கின்ற எண்ணத்தில் இருப்பதே உண்மை வழி முறையில் மேன்மையான நிலையில் கிடைக்கின்ற தெளிவு ஆகும்.`,
  },
  {
    id: 1497, tantraId: 5, verseNumber: 1496,
    tamil: `பூசித்தல் வாசித்தல் போற்றல் செபித்திடல்
ஆசற்ற நற்றவம் வாய்மை அழுக்கின்மை
நேசித்திட் டன்னமும் நீசுத்தி செய்தன்மர்
றாசற்ற சற்புத் திரமார்க்க மாகுமே`,
    transliteration: `pūcittal vācittal pōṟṟal cepittiṭal
ācaṟṟa naṟṟavam vāymai aḻukkiṉmai
nēcittiṭ ṭaṉṉamum nīcutti ceytaṉmar
ṟācaṟṟa caṟput tiramārkka mākumē`,
    english: `1496: What Constitutes Kriya Path
To perform Pujas, to read the scriptures holy
To praise the Lord, to chant His holy name,
To practise Tapas, to be truthful,
To bear no envy,
Thyself to cook the offering for Lord with loving care
These and other acts of reverence
Constitute Pure Path of Filial Piety.`,
    elaborationTamil: `இறைவனை உண்மையான தந்தையாக பாவித்து அவருக்கு பூஜை செய்தல், மந்திரங்களை பாடுதல், போற்றி வணங்குதல், தரிசனம் செய்தல், குற்றம் இல்லாத நன்மையான தவத்தை மேற்கொள்ளுதல், உண்மையே பேசுதல், அழுக்கு இல்லாமல் சுற்றுப் புறத்தையும் தம்மையும் சுத்தமாக வைத்தல், அன்போடு சமைத்து வைத்த உணவை நைவேத்யமாக படைத்தல், நீரினால் சுத்தம் செய்து சமர்ப்பணம் செய்தல் ஆகிய இவை அனைத்தையும் தாம் செய்கின்றோம் என்கின்ற எண்ணம் இல்லாமல் இருந்து செய்வதே இறைவனின் பிள்ளையாக தன்னை பாவித்து அவனை அடைகின்ற வழி முறை ஆகும்.`,
  },
  {
    id: 1498, tantraId: 5, verseNumber: 1497,
    tamil: `அறுகாற் பறவை அலர்தேர்ந் துழலும்
மறுகா நரையன்னந் தாமரை நீலங்
குறுகா நறுமலர் கொய்வன கண்டுஞ்
சிறுகால் அறநெறி சேர்கி லாரே`,
    transliteration: `aṟukāṟ paṟavai alartērn tuḻalum
maṟukā naraiyaṉṉan tāmarai nīlaṅ
kuṟukā naṟumalar koyvaṉa kaṇṭuñ
ciṟukāl aṟaneṟi cērki lārē`,
    english: `1497: All Nature Seeks Flowers; Why Not You?
The humming bees roam unceasing from flower to flower;
The snow-white swans float amidst lotus and blue-bells,
They all, all, seek flowers fragrant;
Yet, you who have beheld all this,
Adore not the Lord with flowers for a while even.`,
    elaborationTamil: `ஆறு கால்களைக் கொண்ட தேனீக்கள் தேனுள்ள மகரந்த மலர்களை ஆராய்ந்து தேடி அலைந்து தேனை சேகரிப்பதையும் இன்னொரு வகையில் வெள்ளை நிறத்தில் உள்ள அன்னப் பறவைகள் தாமரை மலர்களையும் நீலோற்பல மலர்களையும் தேடிச் சென்று அதன் தண்டுகளில் இருக்கும் பாலை சேகரிப்பதையும் இறைவனின் அடியவர்கள் நறுமணம் மிக்க மலர்களை கொய்து மாலையாக கோர்த்து இறைவனுக்கு சாற்றி வணங்கி அருளை சேகரிப்பதையும் பார்த்தும் சிறுது காலம் கூட தமக்கு தந்தை போல அரனாக இருக்கின்ற இறைவனின் அருளைப் பெறும் வழியில் செல்லாமல் இருக்கின்றார்கள்.`,
  },
  {
    id: 1499, tantraId: 5, verseNumber: 1498,
    tamil: `அருங்கரை யாவது அவ்வடி நீழற்
பெருங்கரை யாவது பிஞ்ஞக னாணை
வருங்கரை யேகின்ற மன்னுயிர்க் கெல்லாம்
ஒருங்கரை யாயுல கேழினொத் தானே`,
    transliteration: `aruṅkarai yāvatu avvaṭi nīḻaṟ
peruṅkarai yāvatu piññaka ṉāṇai
varuṅkarai yēkiṉṟa maṉṉuyirk kellām
oruṅkarai yāyula kēḻiṉot tāṉē`,
    english: `1498: Lord is Our Defence and Refuge
His Holy Feet are our Rock of Refuge;
His commandments, our defence's battlements;
He is verily the finite Shore
For the surging tide of Jivas on earth;
He pervades thus, the seven worlds alike.`,
    elaborationEnglish: `Mantras 1498 & 1499

The Lord is truly the Ultimate Goal, who with His Feet and His commandments pervades the seven worlds alike. Adoring Him in diverse ways, He becomes your own.`,
    elaborationTamil: `சென்று சேருவதற்கு மிகவும் அரியதான எல்லையாக இருப்பது இறைவனின் திருவடிகளின் நிழலாகும். பிறை நிலாவை சூடிக்கொண்டு இருக்கும் இறைவனின் ஆணைகளே பிறப்பு இல்லாத மாபெரும் நிலையை பெறுகின்ற எல்லையாக இருக்கின்றன. தத்தமது வினைகளுக்கு ஏற்றபடி வருகின்ற கர்மங்களின் எல்லைகளுக்கு ஏற்றபடி இந்த உலகத்தில் நிலை பெற்று வாழுகின்ற உயிர்களுக்கு எல்லாம் அவற்றின் வினைகளை தீர்த்துக் கொண்டு சென்று சேரும் கரையாக இருக்கின்ற உலகங்கள் ஏழு விதத்திற்கும் ஒத்து இருக்கின்ற தந்தையாக இறைவனே இருக்கின்றான். கருத்து: உயிர்கள் தங்களின் கர்மங்களை தீர்த்துக் கொள்ளவே ஏழு விதமான உலகங்களிலும் தத்தமது வினைகளுக்கு ஏற்ப பிறவிகள் எடுத்துக் கொண்டே இருக்கின்றன. இந்த ஏழு விதமான உலகங்களிலும் எடுக்கின்ற அனைத்து பிறவிகளிலும் தந்தையாக இருந்து காக்கின்ற இறைவனே முக்தி எனும் எல்லையாகவும் இருக்கின்றான்.`,
  },
  {
    id: 1500, tantraId: 5, verseNumber: 1499,
    tamil: `உயர்ந்தும் பணிந்தும் முகந்துந் தழுவி
வியந்தும் அரனடிக் கேமுறை செய்மின்
பயந்தும் பிறவிப் பயனது வாகும்
பயந்து பிரிக்கிலப் பான்மையு னாமே`,
    transliteration: `uyarntum paṇintum mukantun taḻuvi
viyantum araṉaṭik kēmuṟai ceymiṉ
payantum piṟavip payaṉatu vākum
payantu pirikkilap pāṉmaiyu ṉāmē`,
    english: `1499: Adore Lord in Diverse Ways; He Shall Be Yours
Rise high, bend low, kiss and embrace Lord;
Praise Him, sing Him and pray at His Holy Feet;
That shall your birth's fulfilment be;
In trembling love do adore Him;
He, indeed, shall be beloved unto you.`,
    elaborationTamil: `ஒழுக்கத்தில் உயர்ந்து நின்றும் இறைவனின் திருவடிகளை பணிந்து தொழுதும் அவனுக்கு செய்கின்ற பணிவிடைகளை விரும்பி செய்தும் இறைவனின் திருவுருவத்தை தழுவிக் கொண்டும் அதனால் கிடைக்கின்ற இறையனுபவத்தால் வியப்படைந்தும் இறைவனின் திருவடிகளுக்கு தமது கைகளால் தொண்டுகளை செய்தால் அந்த தொண்டே தாம் எடுத்த பிறவிக்கு கிடைக்கின்ற மிகப் பெரும் பயனாக இருக்கும். அப்படி கிடைத்த அருளினால் இறைவனை தந்தையாக பாவித்து தொடர்ந்து அந்த தொண்டுகளை செய்து கொண்டே வந்தால் தந்தையாக இருந்து அதை செய்ய வைக்கின்ற இறைவனே அதனால் கிடைக்கின்ற அனைத்து நன்மையாகவும் இருக்கின்றான்.`,
  },
  {
    id: 1501, tantraId: 5, verseNumber: 1500,
    tamil: `நின்றுதொழுவன் கிடந்தெம் பிரான்தன்னை
என்றுந் தொழுவன் எழிற்பரஞ் சோதியைத்
துன்று மலர்தூவித் தொழுமின் தொழுந்தோறுஞ்
சென்று வெளிப்படுந் தேவர் பிரானே`,
    transliteration: `niṉṟutoḻuvaṉ kiṭantem pirāṉtaṉṉai
eṉṟun toḻuvaṉ eḻiṟparañ cōtiyait
tuṉṟu malartūvit toḻumiṉ toḻuntōṟuñ
ceṉṟu veḷippaṭun tēvar pirāṉē`,
    english: `1500: Approach Lord Through Kriya Path
In reverence I stand and adore mine lord;
In humility I prostrate and praise Him;
And for ever and ever shall I worship the Divine Light of Beauty;
You too shall seek Him with flowers fragrant,
The more you adore Him
The fuller He reveals Himself unto you,
He the Lord of Beings Heavenly.`,
    elaborationEnglish: `Mantras 1500 & 1501
Adore the Lord in reverence, praise Him in humility, worship the divine light of beauty, seek Him with odorous flowers, and He shall reveal Himself. The more you adore Him, the more He reveals Himself. To this Kriya path, that exalts and showers countless blessings, the Chariya path leads.`,
    elaborationTamil: `எம் தந்தையாகிய இறைவனை மனதை ஒருநிலைப் படுத்தி தொழுகின்றேன் எதை செய்தாலும் அதை அவனை நினைத்தே செய்கின்றேன். தானாகவே இருக்கின்ற பரம்பெரும் சோதியாக இருக்கின்ற அந்த இறைவனை எப்போதும் தொழுது கொண்டே இருக்கின்றேன். உங்களுக்கும் தந்தையாகிய அந்த இறைவனை மாசு இல்லாத மலர்களைத் தூவி நீங்களும் தொழுங்கள் அப்படி தொழுது கொண்டே எப்போதும் இருக்கின்ற போது நீங்கள் செய்கின்ற அனைத்திற்குள்ளும் சென்று சோதியாக வெளிப்பட்டு அருள்வான் தேவர்களுக்கும் தந்தையாக இருக்கின்ற இறைவன்.`,
  },
  {
    id: 1502, tantraId: 5, verseNumber: 1501,
    tamil: `திருமன்னுஞ் சற்புத் திரமார்க்கச் சரியை
உருமன்னி வாழும் உலகத்தீர்கேண்மின்
கருமன்னு பாசங் கைகூம்பத் தொழுது
இருமன்னு நாடோறும் இன்புற் றிருந்தே`,
    transliteration: `tirumaṉṉuñ caṟput tiramārkkac cariyai
urumaṉṉi vāḻum ulakattīrkēṇmiṉ
karumaṉṉu pācaṅ kaikūmpat toḻutu
irumaṉṉu nāṭōṟum iṉpuṟ ṟiruntē`,
    english: `1501: Kriya Comes of Chariya
Hearken! You, worldly men
That stand in Chariya Path,
It leads to the Kriya Path,
That exalts you;
Then shall your primordial Pasas lie prostrate,
And you live in unending bliss for ever.`,
    elaborationTamil: `இறை சக்தியானது ஆன்மாவிற்குள் நிலை பெற்று இருக்கும் இறைவனை தந்தையாக பாவித்து தம்மை மகனாக பாவிக்கின்ற வழி முறையே இறைவனை அடைவதற்கு மூல காரணமாக செயல் படுகின்ற வழி முறையை சொல்லுகிறேன் உடல் இருக்கும் வரை நிலை பெற்று வாழுகின்ற உலகத்தவர்களே கேளுங்கள். கருவிலேயே நிலை பெற்று வருகின்ற பாசத் தளைகளை நீக்கி இறைவனை அடைவதற்கு அவனை இரண்டு கைகளையும் ஒன்றாக கூப்பி தொழுது வணங்கி அவனை நினைத்துக் கொண்டே இருப்பதில் நிலை பெற்று தினம் தோறும் அதன் மூலம் கிடைக்கின்ற பேரின்பத்தை அனுபவித்துக் கொண்டே இருங்கள்.`,
  },
  {
    id: 1503, tantraId: 5, verseNumber: 1502,
    tamil: `எளியனல் தீப மீடல்மலர் கொய்தல்
அளிதின் மெழுக லதுதூர்த்தல் வாழ்த்தல்
பளிமணி பற்றல் பன்மஞ் சனமாதி
தளிதொழில் செய்வது தான்தாசமார்க்கமே`,
    transliteration: `eḷiyaṉal tīpa mīṭalmalar koytal
aḷitiṉ meḻuka latutūrttal vāḻttal
paḷimaṇi paṟṟal paṉmañ caṉamāti
taḷitoḻil ceyvatu tāṉtācamārkkamē`,
    english: `1502: Ways of Dasamarga
Gently light the lamp,
Gather flowers fragrant,
Humbly ground the holy paste,
Softly sweep,
Sing Lord's Praise,
Count the crystal beads,
Anoint in many ways,
And perform the diverse acts of temple service.`,
    elaborationEnglish: `Lighting the lamps gracefully, collecting fragrant flowers, pasting the holy floor and sweeping it, praising the Lord and counting the crystal beads, anointing Him in diverse ways — doing all these requirements of temple service, belongs to Dasa Marga.

Dasa means servant`,
    elaborationTamil: `தங்களால் இயன்ற வரை தீபங்களை ஏற்றி வைத்தல் நறுமணமிக்க மலர்ந்த மலர்களை கொய்து சாற்றுதல் இறைவன் இருக்கின்ற இடங்களை சாணி பூசி மெழுகி அந்த இடத்தை சுத்தமாக வைத்தல் இறைவனின் புகழ்களை பாடி வாழ்த்துதல் இறைவன் அமர்ந்து வருகின்ற பல்லக்கு சேவை செய்வதற்கு பல்லக்கின் கழிகளை பற்றிக் கொண்டு வலம் வருதல் பல விதமான அபிஷேகப் பொருள்களை கொண்டு அபிஷேகம் செய்தல் முதல் கொண்டு கோயில்களுக்கு தேவையான தொண்டுகளில் தங்களால் இயன்ற அளவு செய்து பணி புரிவது தான் இறைவனை எஜமானராகவும் தம்மை அடியவராகவும் பாவிக்கின்ற வழி முறையாகும்.`,
  },
  {
    id: 1504, tantraId: 5, verseNumber: 1503,
    tamil: `அதுவிது வாதிப் பரமென் றகல்வர்
இதுவழி யென்றங் கிறைஞ்சின ரில்லை
விதிவழி யேசென்று வேந்தனை நாடு
மதுவிது நெஞ்சில் தணிக்கின்ற வாறே`,
    transliteration: `atuvitu vātip parameṉ ṟakalvar
ituvaḻi yeṉṟaṅ kiṟaiñciṉa rillai
vitivaḻi yēceṉṟu vēntaṉai nāṭu
matuvitu neñcil taṇikkiṉṟa vāṟē`,
    english: `1503: Hold Fast to Chariya Path
This the Primal Being, that the Primal Being
Thus in doubt tossed,
Away they moved farther and farther from It;
They know not this is the true Path,
And worship not;
Do pursue this appointed way,
And seek the King of Kings;
That, in truth, shall quell
All doubts within you swell.`,
    elaborationEnglish: `Mantras 1503 & 1504

Wavering between this path and that path seldom leads to worship. Therefore, firmly hold to the Chariya path and seek the King of Kings; all doubts will vanish. All worship by yogis - that is meditating on the moon (nadi on the left) and shifting on to the sun (nadi on the right) - and worship by the celestial beings commenced in Dasa Marga.`,
    elaborationTamil: `அதுவும் இதுவும் ஆதியாக இருக்கின்ற பரம் பொருள் என்று நினைத்துக் கொண்டு பரந்து விரிந்து இருக்கின்ற உலகில் இதுவே இறைவனை அடையும் வழி என்று எடுத்துக் கொண்டு அதன் மூலம் இறைவனை அடைய முயற்சி செய்கின்றவர்கள் யாரும் இல்லை. அப்படி இல்லாமல் தங்களுக்கு விதிக்கப் பட்ட வழியில் சென்று தமக்குள் மறைந்து இருந்து தம்மை ஆளுகின்ற இறைவனை அடியவராக தேடி அடைகின்ற வழி முறையே விதி என்று கடைபிடிக்கின்றவர்களின் மனதில் இருந்து ஆசைகளை அழித்து இறைவனிடம் சேர்க்கின்ற வழி முறை இதுவே ஆகும்.`,
  },
  {
    id: 1505, tantraId: 5, verseNumber: 1504,
    tamil: `அந்திப்பன் திங்க ளதன்பின்பு ஞாயிறு
சிந்திப்பன் என்றும் ஒருவன் செறிகழல்
வந்திப்ப வானவர் தேவனை நாடோறும்
வந்திப்ப தெல்லாம் வகையின் முடிந்ததே`,
    transliteration: `antippaṉ tiṅka ḷataṉpiṉpu ñāyiṟu
cintippaṉ eṉṟum oruvaṉ ceṟikaḻal
vantippa vāṉavar tēvaṉai nāṭōṟum
vantippa tellām vakaiyiṉ muṭintatē`,
    english: `1504: All Worship Began From Chariya
"I meditate on the Moon Nadi on the left,
I shift on to the Sun Nadi on the right"
-The worship the yogins thus
At the Feet of the One perform
And the worship the Celestial Beings
Daily to Lord offer,
All these but begin
In the Path of Chariya ultimate.`,
    elaborationTamil: `காலையிலும் மாலையிலும் மனதாலும் அதன் பிறகு அதற்கு ஏற்றபடி உடலாலும் வழிபாடு செய்து சிந்தித்துக் கொண்டே இருப்பேன். எப்போதும் எமக்கு எஜமானராக இருக்கின்ற ஒருவனையும் நினைப்பதை அருளுபவனுமாகிய அவனின் திருவடிகளை போற்றி வணங்குவேன். வானவர்களுக்கு எல்லாம் அதிபதியாக இருக்கின்ற இறைவனை தினம் தோறும் இவ்வாறு நான் போற்றி வணங்குவது எல்லாமே இறைவனை எஜமானராகவும் எம்மை அடியவராகவும் பாவிக்கின்ற வழி முறைப் படியே ஆகும்.`,
  },
  {
    id: 1506, tantraId: 5, verseNumber: 1505,
    tamil: `அண்ணலை வானவர் ஆயிரம் பேர்சொல்லி
உன்னுவர் உள்மகிழ்ந்துண்ணின் றடிதொழக்
கண்ணவ னென்று கருது மவர்கட்குப்
பண்ணவன் பேரன்பு பற்றிநின் றானே`,
    transliteration: `aṇṇalai vāṉavar āyiram pērcolli
uṉṉuvar uḷmakiḻntuṇṇiṉ ṟaṭitoḻak
kaṇṇava ṉeṉṟu karutu mavarkaṭkup
paṇṇavaṉ pēraṉpu paṟṟiniṉ ṟāṉē`,
    english: `1505: Lord Appears in Love Entwined
The Celestial Beings seek Lord
Chanting His glory in names thousand;
They that adore His Holy Feet
In abiding rapture of their hearts,
And hold him as their eyes' apple
Unto them is He sweet melody,
To them He appears in divine love entwined.`,
    elaborationEnglish: `Mantras 1505 & 1506

The Lord appears in the divine love of those who seek and adore Him in the abiding rapture of their hearts. What is the use of reading holy works and conducting pujas when the heart is obfuscated by darkness and overspread with the moss of ignorance. Unless the heart is rid of all these impurities, God the Supreme Light, cannot be visioned.`,
    elaborationTamil: `அனைத்திற்கும் எஜமானனாகிய இறைவனை அடியவர்களாகிய வானவர்கள் ஆயிரம் விதமான பெயர்களை சொல்லி போற்றி தமது எண்ணத்திற்குள் வைத்து நினைந்து உள்ளம் மகிழ்ந்து தமக்குள் நிற்கின்ற அவனது திருவடியை தொழுவார்கள். தமது கண்ணுக்கு கண்ணாக இருப்பவன் அவனே என்று எண்ணுகின்ற அவர்களுக்கு உள்ளே இருந்து இலயிக்கின்ற இசையைப் போல அந்த இறைவன் மாபெரும் அன்பு காட்டி அவர்களை அரவணைத்து நிற்கின்றான்.`,
  },
  {
    id: 1507, tantraId: 5, verseNumber: 1506,
    tamil: `வாசித்தும் பூசித்தும்மாமலர் கொய்திட்டும்
பாசிக் குளத்தில்வீழ் கல்லா மனம்பார்க்கின்
மாசற்ற சோதி மணிமிடற் றண்ணலை
நேசத் திருந்த நினைவறி யாரே`,
    transliteration: `vācittum pūcittummāmalar koytiṭṭum
pācik kuḷattilvīḻ kallā maṉampārkkiṉ
mācaṟṟa cōti maṇimiṭaṟ ṟāṇṇalai
nēcat tirunta niṉaivaṟi yārē`,
    english: `1506: Be of Love and See the Lord
What avails it
That you read holy scriptures,
Perform Pujas,
Gather flowers in cluster?
As long as your heart is unto a pebble
Dropped into a dark pool
Over-spread with moss of ignorance,
You can never realize the Lord;
Lord that is in your heart's love;
Lord that is blue-throated;
He, the Pure Light.`,
    elaborationTamil: `இறைவனை போற்றி பாடியும் மந்திரங்களை செபித்தாலும், பூஜை செய்தாலும், அதிக அளவில் மலர்களை கொய்து வந்து சாற்றினாலும், பாசி படிந்த குளத்தில் விழுந்த கல்லை போலவே மனம் மாயையில் மூழ்கி இருக்கின்ற நிலையை பார்த்தால் மாசு மரு எதுவும் இல்லாத தூய்மையான சோதியாக நீல நிற கழுத்தைக் கொண்டு அனைத்திற்கும் எஜமானராக இருக்கின்ற இறைவனை தங்களின் தூய்மையான அன்பில் வைத்து இருக்கும் எண்ணத்தை அவர்கள் அறியாமல் இருக்கின்றார்கள். கருத்து: பாசி நிறைந்த குளத்தில் கல் விழுகின்ற போது சிறிது நேரம் பாசியானது அகன்று பின்னர் மூடிக்கொள்ளும். அதுபோல மாயையில் மூழ்கி இருக்கின்ற மனமானது பூசை முதலியன செய்யும் போது சிறிது அளவு மனம் தெளியும், பின்னர் அதனை அன்போடு தொடர்ந்து செய்யாமல் போனால் மறுபடியும் மாயையில் மூழ்கிவிடும். எனவே மாயையில் மூழ்கி இருக்கின்ற மனதில் இறைவனைப் பற்றிய எண்ணம் வருவதில்லை.`,
  },
  {
    id: 1508, tantraId: 5, verseNumber: 1507,
    tamil: `சாலோக மாதி சரியாதி யிற்பெறுஞ்
சாலோகஞ் சாமீபந் தங்குஞ் சரியையால்
மாலோகஞ் சேரில் வழியாகுஞ் சாரூபம்
பாலோகம் இல்லாப் பரனுரு வாமே`,
    transliteration: `cālōka māti cariyāti yiṟpeṟuñ
cālōkañ cāmīpan taṅkuñ cariyaiyāl
mālōkañ cēril vaḻiyākuñ cārūpam
pālōkam illāp paraṉuru vāmē`,
    english: `1507: Successive Stages to Finite Beatitude
The four stages of attainment
Saloka, Samipa, Sarupa and Sayujya
Are in gradation reached from Chariya;
The path of Chariya leads to Saloka;
And that in turn to Samipa;
And Samipa shows the way to Sarupa;
And ultimately to Para of Infinite Space (Sayujya)
Beyond which there is state none.`,
    elaborationEnglish: `The four stages of attainment, namely, Saloka, Samipa, Sarupa and Sayujya reached from Chariya in gradation, finally end with Para of Infinite Space (Sayujya), beyond which there is no state.

‘Saloka’, ‘Samipa’, ‘Sarupa’, and ‘Sayujya’ mean respectively

“Being in the same world as the Lord’, Being with Him continually’. ‘adopting His Form’, and ‘United with Him’. These are different ways of imagining Oneself to be in, during worship. They are explained in verse 1509, post.`,
    elaborationTamil: `இறைவன் இருக்கின்ற உலகத்தை சார்ந்தே இருக்கின்ற நிலை முதலாகிய சாலோகம் சாமீபம் சாரூபம் சாயுச்சியம் ஆகிய நான்கு விதமான முக்திக்கான நிலைகளும் இறைவனை அடைவதற்கான சரியை முதலாகிய சரியை கிரியை யோகம் ஞானம் ஆகிய நான்கு விதமான முறைகளால் பெறப்படும். இறைவன் இருக்கின்ற உலகத்தை சார்ந்தே இருக்கின்ற நிலை பெற்று அதன் மூலம் இறைவனுக்கு அருகில் இருக்கின்ற நிலையானது சரியையை தொடர்ந்து முறைப்படி செய்து கொண்டு இருப்பதால் நமக்கு கிடைக்கும். இறைவன் இருக்கின்ற மாபெரும் உலகத்தையே சேர்ந்து இருந்தால் அதற்கு அடுத்த நிலையாகிய இறைவனுடைய உருவத்தையே பெறுகின்ற நிலையை அடைவதற்கு அதுவே வழியாக இருக்கும். அப்போது இந்த பரந்த விரிந்த உலகங்கள் அனைத்திலும் இருக்கின்ற வடிவங்களில் இல்லாத பரம்பொருளின் ஒளி உருவத்தோடு அவருடனே எப்போதும் இருக்கின்ற சாயுச்சிய நிலையும் கிடைக்கும். இறைவனை அடைந்த முக்திக்கான நிலைகள்: சாலோகம் – இறைவன் இருக்கும் இடத்தில் அவனோடு சேர்ந்து வாழ்வது. சாமீபம் – இறைவனுக்கு பக்கத்தில் அமர்ந்து நெருக்கமாக வாழ்வது. சாரூபம் – இறைவனுக்கு பிரதிநிதியாக அவருக்கு செய்வதை ஏற்றுக்கொள்வது. சாயுச்சியம் – இறைவனோடு எப்போதும் சேர்ந்து இருப்பது. இறைவனை அடைவதற்கான வழிகள்: சரியை – கோயில்கள் செல்வது, பூஜைகள் செய்வது. கிரியை – மந்திரம் சொல்லி சக்கரங்கள் வைத்து வழிபடுவது. யோகம் – தியானம் தவம் செய்வது. ஞானம் – அனைத்திற்கும் மேலான நிலையில் சலனங்கள் இன்றி இருப்பது.`,
  },
  {
    id: 1509, tantraId: 5, verseNumber: 1508,
    tamil: `சமயங் கிரியையிற் றன்மனங் கோயில்
சமய மனுமுறை தானே விசேடஞ்
சமயத்து மூலந் தனைத்தேறன் மூன்றாஞ்
சமயாபி டேகந் தானாஞ் சமாதியே`,
    transliteration: `camayaṅ kiriyaiyiṟ ṟaṉmaṉaṅ kōyil
camaya maṉumuṟai tāṉē vicēṭañ
camayattu mūlan taṉaittēṟaṉ mūṉṟāñ
camayāpi ṭēkan tāṉāñ camātiyē`,
    english: `1508: The Four Ordinations in Kriya Worship
In Kriya worship are sacraments four;
Samaya sacrament prepares heart to be a Tabernacle of God ;
Visesha sacrament installs the Faith firm;
Nirvana helps realize the Truth of Faith;
Abhisheka confereth the state of Samadhi Supreme.`,
    elaborationEnglish: `This Mantra should appropriately come at the end of 6, kriya ante, after Mantra 1456.`,
    elaborationTamil: `சமயம் எனப்படுவது கிரியையில் தன் மனதையே இறைவன் இருக்கின்ற கோயிலாக மாற்றுவதன் மூலம் இறைவன் இருக்கின்ற இடத்தை சார்ந்தே இருக்கின்ற சாலோக நிலையை அடைவது ஆகும். சமயத்தில் மனித உயிர்களுக்கு என்று வகுக்கப்பட்ட வழி முறைகளாக இருப்பது தானே கோயிலாக வைத்து உள்ளே இருக்கின்ற இறைவனுக்கு செய்கின்ற கிரியைகளின் விஷேசத்தினால் இறைவனுக்கு அருகிலேயே இருக்கின்ற சாமீப நிலையை அடைவது ஆகும். அந்த சமயத்தின் மூலமே தாம் யாராக இருக்கின்றோம் என்று அறிந்து அதில் தெளிவை பெறுவது சரியை, கிரியை, யோகம் ஆகிய மூன்று விதமான முறைகளாலும் சாலோகம், சாமீபம், சாரூபம் ஆகிய மூன்று முக்திக்கான நிலைகளை அடைவது ஆகும். சமயத்தில் அபிஷேகம் என்பது தானே இறைவனாக இருக்கின்றதை உணர்ந்த ஞான முறையில் அவருடனேயே எப்போதும் சேர்ந்து இருக்கின்ற சாயுச்சிய நிலையை அடைவது ஆகும். கருத்து: மனதையே இறைவன் இருக்கின்ற கோயிலாக மானசீகமாக அமைத்து சரியை முறையை பின்பற்றுவது இறைவன் இருக்கின்ற உலகத்தையே சார்ந்து இருக்கின்ற நிலை ஆகும். மனதுக்குள் இருக்கின்ற இறைவனுக்கு பூஜைகளும் மந்திர உச்சாடனங்களும் செய்து கிரியை முறையை பின்பற்றுவது இறைவனுக்கு அருகிலேயே இருக்கின்ற நிலை ஆகும். தமக்குள் இருக்கின்ற ஆன்மாவே இறைவன் என்று அறிந்து கொண்டு அவனையே தியானம் செய்கின்ற யோக முறையை பின்பற்றுவது இறைவனுடைய உருவத்திலேயே இருக்கின்ற நிலை ஆகும். தமக்குள் இருக்கின்ற ஆன்மாவாகிய இறைவனை உணர்கின்ற ஞான முறையை அடைவது இறைவனுடனே எப்போதும் சேர்ந்து இருக்கின்ற நிலை ஆகும். குறிப்பு: இந்தப் பாடலில் வருகின்ற சமயம் என்பது என்னவென்றால் தாங்கள் எந்த மதத்தை சார்ந்து எந்த வழிமுறையை பின் பற்றினாலும் அதற்கு என்று வகுத்துக் கொடுக்கப் பட்ட விதிமுறைகளே சமயம் என்று அழைக்கப் படுகின்றது.`,
  },
  {
    id: 1510, tantraId: 5, verseNumber: 1509,
    tamil: `பாசம் பசுவான தாகும்இச் சாலோகம்
பாச மருளான தாகும்இச் சாமீபம்
பாசஞ் சிரமான தாகும்இச் சாரூபம்
பாசங் கரைபதி சாயுச் சியமே`,
    transliteration: `pācam pacuvāṉa tākumic cālōkam
pāca maruḷāṉa tākumic cāmīpam
pācañ ciramāṉa tākumic cārūpam
pācaṅ karaipati cāyuc ciyamē`,
    english: `1509: Transformation of World-Knowledge
In Saloka Pasa Jnana (World knowledge) becomes Pasu Jnana (Spiritual
knowledge)
In Samipa it becomes Arul Jnana (Grace-knowledge)
In Sarupa it is transformed into Pati Jnana (God-knowledge)
In Sayujya it is for ever dissolved.`,
    elaborationTamil: `உலகப் பற்றுக்களானது ஆன்மாவாக இருக்கின்ற உயிர்களுக்குள் மாயையால் மறைத்து இருக்கும் போது இறைவனை அடைய வேண்டும் என்று சரியை கிரியை யோகம் ஞானம் ஆகியவற்றின் மூலம் சாதகம் செய்கின்ற உயிர்களுக்கு இந்த உலகத்திலேயே இறைவன் இருக்கின்ற இடத்திற்கு அருகில் செல்லுகின்ற நிலை கிடைக்கும். அந்த சாதகத்தை தொடர்ந்து செய்யும் போது உலகப் பற்றுக்களானது சிறுது சிறிதாக விலகி இறையருள் பெருகி தம்மை அதுவே இந்த உலகத்திலேயே இறைவனுக்கு மிகவும் அருகில் செல்லுகின்ற நிலையை கொடுக்கும். அந்த நிலையிலும் தொடர்ந்து சாதகத்தை செய்யம் போது உலகப் பற்றுக்களானது நீங்கி இறைவனின் மேல் பற்று கொள்ளும் படி சிவமாகவே தம்மையும் ஆகும் படி செய்து இந்த உலகத்திலேயே இறைவனின் ஒளி உருவத்தை பெறுகின்ற நிலையை கொடுக்கும். அந்த நிலையிலும் மேன்மை பெற்று சாதகத்தை தொடரும் போது பற்றுக்கள் அனைத்தும் முழுவதுமாக நீங்கி முக்திக்கு எல்லையாக இருக்கின்ற இறைவனிடம் சென்று சேரும் படி செய்து இறைவனுடனே எப்போதும் இருக்கின்ற நிலையை கொடுக்கும்.`,
  },
  {
    id: 1511, tantraId: 5, verseNumber: 1510,
    tamil: `தங்கிய சாரூபந் தானெட்டாம் யோகமாந்
தங்குஞ்சன்மார்க்கந் தனிலன்றிக் கைகூடா
அங்கத் துடல்சித்தி சாதன ராகுவர்
இங்கிவ ராக விழிவற்ற யோகமே`,
    transliteration: `taṅkiya cārūpan tāṉeṭṭām yōkamān
taṅkuñcaṉmārkkan taṉilaṉṟik kaikūṭā
aṅkat tuṭalcitti cātaṉa rākuvar
iṅkiva rāka viḻivaṟṟa yōkamē`,
    english: `1510: Only Jnana-in-Yoga Leads to Sarupa State
The State of Sarupa is, no doubt, reached
Through the eight-pronged yoga way;
But unless it be Sanmarga-in-Yoga,
The Sarupa state cannot be;
The yoga way but leads to bodily Siddhis diverse;
But for the Sarupa state to realize,
None these but the pure way of Jnana-in-Yoga.`,
    elaborationEnglish: `Though the eight-pronged yoga way reaches up’ to the Sarupa state, unless San Marga in Yoga Unana in Yoga) is attained, there capnot be the state of Sarupa.

Sanmarga-in-yoga is identical with jnana-in-yoga. Mular explains that mere practice of yoga without ‘Sanmarga’ (worshipful faith and good conduct) will only produce Siddhis (Powers) but will not lead to Liberation.`,
    elaborationTamil: `நிலை பெற்ற இறை உருவம் என்பது சாதகர்கள் அட்டாங்க யோகத்தில் எட்டாவது யோகமாகிய சமாதி நிலையில் கிடைப்பதாகும். நிலை பெற்ற உண்மை வழி முறையாக இருக்கின்ற இறைவனை அடைகின்ற ஞான வழிமுறை அல்லாமல் வேறு எதனாலும் சாதகர்களுக்கு இந்த சமாதி நிலை கிடைக்காது. இந்த சமாதி நிலையை அடைந்த சாதகர்களின் உடலில் உள்ள அனைத்து உறுப்புகளும் இறைவனையே நினைத்து செயலாற்றிக் கொண்டு இருக்கின்ற சித்த நிலை பெற்ற சாதகராக ஆகி விடுவார். இதன் பயனால் இந்த உலகத்திலேயே இந்த சாதகர் தாமே ஒரு குற்றமும் இல்லாத தூய்மையான யோகத்தின் வடிவமாக வீற்றிருப்பார்.`,
  },
  {
    id: 1512, tantraId: 5, verseNumber: 1511,
    tamil: `சயிலலோ கத்தினைச் சார்ந்த பொழுதே
சயிலம தாகுஞ் சராசரம் போலப்
பயிலுங் குருவின் பதிபுக்க போதே
கயிலை இறைவன் கதிர்வடி வாமே`,
    transliteration: `cayilalō kattiṉaic cārnta poḻutē
cayilama tākuñ carācaram pōlap
payiluṅ kuruviṉ patipukka pōtē
kayilai iṟaivaṉ katirvaṭi vāmē`,
    english: `1511: Sarupa State by Nearness to God
All things, living and non-living,
As they reach the Golden Mount of Meru
Are themselves into gold transformed;
Even so,
They that reach the world of Master Divine
Attain Form the Light Divine
His, of the King of Kailas.`,
    elaborationTamil: `இறைவன் இருக்கின்ற தர்ம உலகத்தை சாதகர் சார்ந்து இருக்கும் போதே அங்கே வீற்றிருக்கின்ற இறைவனுக்கு சாந்து பூசியது போல அண்டத்தில் இருக்கின்ற அனைத்து உலகங்களும் சுற்றி இருக்கின்றது போலவே அங்கு புகுந்த சாதகரையும் சுற்றி இருக்கும் படி ஆகிவிடும். அது போலவே சாதகர் தமக்கு கற்று கொடுக்கும் இறைவனை உணர்ந்த ஞான குருவின் இடத்திற்குள் நுழைந்த போதே கயிலாய மலையில் வீற்றிருக்கின்ற இறைவனின் ஒளி பொருந்திய உருவமாகவே சாதகரும் ஆகி விடுவார்.`,
  },
  {
    id: 1513, tantraId: 5, verseNumber: 1512,
    tamil: `சைவஞ் சிவனுடன் சம்பந்த மாவது
சைவந் தனையறிந் தேசிவஞ் சாருதல்
சைவஞ் சிவந்தன்னைச் சாராமல் நீங்குதல்
சைவஞ் சிவானந்தஞ் சாயுச் சியமே`,
    transliteration: `caivañ civaṉuṭaṉ campanta māvatu
caivan taṉaiyaṟin tēcivañ cārutal
caivañ civantaṉṉaic cārāmal nīṅkutal
caivañ civāṉantañ cāyuc ciyamē`,
    english: `1512: Stages in the Soul's Pilgrimage
In the Soul's Pilgrimage towards God
The Path of Saivam describes stages four;
It is Saivam, when the Self forges a kindred tie with Siva (in Saloka)
It is Saivam, when the Soul realizes itself and nears God (in Samipa)
It is Saivam, when it leaves Samipa (and reaches Sarupa)
It is Saivam when it enjoys the final bliss of Sivananda,
The inextricable union in Sayujya.`,
    elaborationEnglish: `The Sayujya marga is, it appears the same as the one termed ‘Sahaja’ in Tantricism which is ‘’the marga or way of. spiritual exercise which is the earliest or most natural. It is also the term for ultimate reality among the Sahajiyas, i.e., those who believe in this marga””. (N.N. Bhattacharyya in “’History of Tantricism™’, p.465.).`,
    elaborationTamil: `சைவம் என்று அறியப்படுகின்ற தர்மத்தில் இறைவனுடன் நெருங்கிய உறவினர் போல தாமும் ஆவது சாலோகம் எனும் முதல் நிலையாகும். இந்த நிலையை அடைவதற்கு அந்த வழி முறையின் மூலம் இறைவனை அறிந்து கொண்டு இறைவனை மிகவும் நெருங்கி அவரையே சார்ந்து இருப்பது சாமீபம் எனும் இரண்டாவது நிலையாகும். அந்த தர்மத்திலேயே சிவப் பரம்பொருளை அறிந்து அடைந்த பிறகு தாம் எனும் எண்ணத்தை சார்ந்து இருப்பதை நீக்கி விட்டு தாமே சிவமாக இருப்பதை உணர்ந்து சிவ உருவத்திலேயே இருப்பது சாரூபம் எனும் மூன்றாவது நிலையாகும். அந்த தர்மத்தின் பயனால் சிவப் பரம்பொருளின் மேலான பேரின்பத்தை பெற்று அதிலேயே மூழ்கி இறைவனுடனே எப்போதும் சேர்ந்தே இருப்பது சாயுச்சியம் எனும் நான்காவது நிலையாகும்.`,
  },
  {
    id: 1514, tantraId: 5, verseNumber: 1513,
    tamil: `சாயுச் சியஞ்சாக் கிராதீதஞ் சாருதல்
சாயுச் சியமுப சாந்தத்துத் தங்குதற்
சாயுச் சியஞ்சிவ மாதல் முடிவிலாச்
சாயுச் சியமனத் தானந்த சத்தியே`,
    transliteration: `cāyuc ciyañcāk kirātītañ cārutal
cāyuc ciyamupa cāntattut taṅkutaṟ
cāyuc ciyañciva mātal muṭivilāc
cāyuc ciyamaṉat tāṉanta cattiyē`,
    english: `1513: Sayujyam
Sayujya is the state of Jagra-Atita-the Beyond-Consciousness
Sayujya is to abide for ever in Upasantha,
The peace that knows no understanding
Sayujya is to become Siva Himself,
Sayujya is to experience the infinite power of inward bliss,
Forever and ever.`,
    elaborationEnglish: `Sayujya is the state of jagra-alita, the state beyond consciousness, it is to abide forever in upasantha, the peace that is beyond understanding and finally to become Siva Himself, experiencing the infinite power of inward bliss.`,
    elaborationTamil: `இறைவனுடன் எப்போதும் சேர்ந்தே இருக்கின்ற நிலையானது இறைவனுடன் இலயித்து இருக்கின்ற ஆழ் நிலையில் மூழ்கி இருந்தாலும் நினைவு உலகத்திலும் விழிப்பு நிலையில் இருப்பது சாலோகம் எனும் முதல் நிலை ஆகும். இந்த நிலைக்கு உதவுகின்ற பேரமைதி எனும் நிலையிலேயே தங்கி இருப்பது சாமீபம் எனும் இரண்டாம் நிலை ஆகும். இந்த நிலையில் தாமே சிவமாக ஆகி இறைவனின் எல்லை இல்லாத ஒளி உருவத்தை பெற்று இருப்பது சாரூபம் எனும் மூன்றாவது நிலை ஆகும். அந்த நிலையில் மனதிற்குள் இறைவனின் பேரின்பத்தில் மூழ்கி இருந்து அவனின் அளவில்லாத சக்தியை அனுபவித்துக் கொண்டே இருப்பது சாயுச்சியம் எனும் நான்காம் நிலை ஆகும்.`,
  },
  {
    id: 1515, tantraId: 5, verseNumber: 1514,
    tamil: `இருட்டறை மூலை யிருந்த கிழவி
குருட்டுக் கிழவனைக் கூடல் குறித்துக்
குருட்டினை நீக்கிக் குணம்பல காட்டி
மருட்டி யவனை மணம்புரிந் தாளே`,
    transliteration: `iruṭṭaṟai mūlai yirunta kiḻavi
kuruṭṭuk kiḻavaṉaik kūṭal kuṟittuk
kuruṭṭiṉai nīkkik kuṇampala kāṭṭi
maruṭṭi yavaṉai maṇampurin tāḷē`,
    english: `1514: Wooing of the Soul by the Lady of Grace
In the corner dark of the Chamber of Primal Stuff
There She was-the Virgin Lady of Grace;
Intent on consorting with the Blind Old Man-the Soul immortal,
She rent his veil of night,
Showered full many a favour,
Wooed with temptations diverse,
And lo! to Her bosom took him,
In wedlock holy.`,
    elaborationEnglish: `Mantras 1514 & 1515

In the dark corner of the chamber of primal stuff, the Goddess of Grace courted the 'blind old man' - immortal soul - in marriage took him to Her bosom. Meditation on the primal source from where sprang the delusive senses, grants Her vision. Those who are given this clear vision are truly in the infinite ground of Sakti of the highest seeking.`,
    elaborationTamil: `இருளில் இருக்கின்ற அறைக்குள் ஒரு மூலையில் வீற்றிருக்கின்ற ஒரு இளம் கன்னியானவள் கண் தெரியாத குருடனாகிய கிழவனோடு ஒன்றாக சேருவது எனும் குறிக்கோளுடன் அவனது குருட்டை நீக்கி நல்ல அழகுகளை பல விதங்களில் காண்பித்து அவளுடைய அழகில் மயங்க வைத்து அந்த கிழவனோடு திருமணம் புரிந்து எப்போதும் அவனோடு சேர்ந்தே இருந்தாளே. கருத்து விளக்கம்: மாயை எனும் இருளில் இருக்கின்ற உடம்பிற்குள் மூலாதாரத்தில் வீற்றிருக்கின்ற அருள் சக்தியானவள் மாயை மறைத்து இருப்பதால் உண்மை தெரியாமல் இருக்கின்ற பல பிறவி எடுத்த ஆன்மாவோடு ஒன்றாக சேருவது எனும் அருள் கருணையுடன் அந்த ஆன்மாவின் மாயையை நீக்கி நன்மையான உண்மைகளை பல விதங்களில் உணர வைத்து பேரின்பத்தில் ஆன்மாவை மயங்க வைத்து பல பிறவி எடுத்த ஆன்மாவோடு கலந்து நின்று எப்போதும் ஆன்மாவோடு சேர்ந்தே இருந்தாளே.`,
  },
  {
    id: 1516, tantraId: 5, verseNumber: 1515,
    tamil: `தீம்புல னான திசையது சிந்திக்கில்
ஆம்புல னாயறிவார்க்கமு தாய்நிற்குந்
தேம்புல னான தெளிவறி வார்கட்குக்
கோம்புல னாடிய கொல்லையு மாமே`,
    transliteration: `tīmpula ṉāṉa ticaiyatu cintikkil
āmpula ṉāyaṟivārkkamu tāyniṟkun
tēmpula ṉāṉa teḷivaṟi vārkaṭkuk
kōmpula ṉāṭiya kollaiyu māmē`,
    english: `1515: The Infinite Ground of Sakti's Descent
If you meditate on the primal source
Whence the evil senses sprang
You shall know it as Land of Becoming,
The ambrosia of the Realized;
They that have been given the clear vision, nectar sweet,
Are verily the Infinite Ground
Of Sakti's highest seeking.`,
    elaborationTamil: `நல்ல சுவையோடு இனிமையான தண்ணீரானது எந்த திசையில் இருக்கின்றது என்பதை சிந்தித்து பார்த்தால் மேலிருந்த வருகின்ற ஆற்றுத் தண்ணீராகவே அதை அறிந்தவர்களுக்கு நல்ல நீராக அதுவே நிற்கும். அப்போது சேர்ந்து இருக்கின்ற ஆற்றுத் தண்ணீராகிய கிணற்றில் சேமித்து வைக்கும் முறை அறிந்தவர்களுக்கு ஓடுகின்ற ஆற்றுத் தண்ணீரினால் பயிர்களுக்கு நீர்ப்பாசனம் செய்து விவசாய நிலத்தில் பயிர்களை வளர்க்கும் முறை அதுவாகும். கருத்து விளக்கம்: மூலாதார அக்னியில் இருக்கின்ற அமிழ்தமானது எந்த திசையில் இருக்கின்றது என்பதை சிந்தித்து பார்த்தால் சகஸ்ரதளத்தில் இருந்து வருகின்ற அமிழ்த நீராகவே அதை அறிந்தவர்களுக்கு நன்மை தரும் அமிழ்தமாக அதுவே நிற்கும். அப்போது சகஸ்ரதளத்திலிருந்து இறங்கி வந்து அன்னாக்கில் தங்கி இருக்கின்ற அமிழ்தமாகிய ஞானத்தை தெளிவாக அறிந்து உணர்ந்தவர்களுக்கு அன்னாக்கிலிருந்து உடல் முழுவதும் பரவுகின்ற அமிழ்த நீரினால் உடலுக்கு சக்தியும் பேரின்பமும் கொடுத்து ஞானத்தை வளர்க்கின்ற முறை அதுவாகும்.`,
  },
  {
    id: 1517, tantraId: 5, verseNumber: 1516,
    tamil: `இருள்நீக்கி எண்ணில் பிறவி கடத்தி
அருள்நீங்கா வண்ணமே யாதியருளும்
மருள்நீங்கா வானவர் கோனொடுங் கூடிப்
பொருள்நீங்கா இன்பம் புலம்பயல் தானே`,
    transliteration: `iruḷnīkki eṇṇil piṟavi kaṭatti
aruḷnīṅkā vaṇṇamē yātiyaruḷum
maruḷnīṅkā vāṉavar kōṉoṭuṅ kūṭip
poruḷnīṅkā iṉpam pulampayal tāṉē`,
    english: `1516: Arul Sakti Helps Attain Liberation
The Primal Sakti releases Jiva from enveloping gloom,
Rows it across the sea of myriad births,
Grants the Grace Abiding;
And lands it on the shores of Truth's Bliss
United in the Lord of Heavenly Beings,
-Themselves as yet unfree
From Impurity's obscuration.`,
    elaborationEnglish: `Mantras 1516 & 1517

Releasing jiva from the enveloping darkness, the Primal Sakti aids it to land on the banks of Truth's bliss and to attain liberation. The presence of Lord Nandi and the Lady of Grace pierces and illuminates the bewildering ignorance that engulfs the jiva in this gloom.`,
    elaborationTamil: `மாயையை நீக்கி விட்டு தாம் எடுக்க வேண்டிய எண்ண முடியாத பிறவிகளை அந்தந்த பிறவிகளை எடுக்காமலேயே கடந்து போகும் படி செய்து, இறையருளானது எப்போதும் தம்மை விட்டு நீங்கி விடாத படியே ஆதிப் பரம்பொருள் அருளி, தனக்கென்று ஒரு பெயருடன் அகங்காரம் நீங்காமல் இருக்கின்ற வானவர்களின் அரசனாக இருக்கின்ற இறைவனோடு எப்போதும் சேர்ந்தே இருக்கும் படி செய்து, என்ன வேண்டுமென்றாலும் அதை பெற்றுக் கொண்டே இருக்கின்ற நிலையில் இருந்து நீங்கி விடாத படி பேரின்பத்திலேயே இந்த உலகத்தில் தாம் இருக்கின்ற இடத்திலேயே தாம் செய்து கொண்டு இருக்கின்ற சாதகத்தை தொடர்ந்து செய்து கொண்டு இருக்கும் படி செய்து அருளுகின்றது இறை சக்தி.`,
  },
  {
    id: 1518, tantraId: 5, verseNumber: 1517,
    tamil: `இருள்சூ ழறையில் இருந்தது நாடிற்
பொருள்சூழ் விளக்கது புக்கெரிந் தாற்போன்
மருள்சூழ் மயக்கத்து மாமலர் நந்தி
அருள்சூழ் இறைவனும் அம்மையு மாமே`,
    transliteration: `iruḷcū ḻaṟaiyil iruntatu nāṭiṟ
poruḷcūḻ viḷakkatu pukkerin tāṟpōṉ
maruḷcūḻ mayakkattu māmalar nanti
aruḷcūḻ iṟaivaṉum ammaiyu māmē`,
    english: `1517: Grace Illumines
As when groping in a chamber enveloped in thick gloom,
A sudden shaft of light pierces and illumines,
Unto it into the gloom of bewildering Ignorance
Is the Presence of Lord and Lady of Grace,
Lord that is Nandi, worshipped in the blossom of heart.`,
    elaborationTamil: `மாயையால் சூழப் பட்டு இருக்கின்ற அறையாகிய உடம்பிற்குள் மறைந்து இருக்கின்ற உண்மை பொருளை தேடி அடைந்தால், இருண்ட அறையில் தம்மை சுற்றி இருக்கின்ற பொருள்களை காண்பிக்கும் விளக்கைப் போலவே மூலாதாரத்தில் இருக்கின்ற சோதியை சாதகத்தின் மூலம் ஏற்றி வைத்தால், மாயை சூழ்ந்த மயக்கத்தில் இதுவரை வெளிப்படாமல் இதயத் தாமரையாகிய மாபெரும் மலரில் வீற்றிருக்கின்ற குருநாதராகிய இறைவன் வெளிப்பட்டு அவரே அருள் சூழ்ந்து இருக்கின்ற தந்தையாகவும் தாயாகவும் இருப்பார்.`,
  },
  {
    id: 1519, tantraId: 5, verseNumber: 1518,
    tamil: `மருட்டிப் புணர்ந்து மயக்கமும் நீக்கி
வெருட்டி வினையறுத் தின்பம் விளைத்துக்
குருட்டினை நீக்கிக் குணம்பல காட்டி
அருட்டிகழ் ஞான மதுபுரிந் தானே`,
    transliteration: `maruṭṭip puṇarntu mayakkamum nīkki
veruṭṭi viṉaiyaṟut tiṉpam viḷaittuk
kuruṭṭiṉai nīkkik kuṇampala kāṭṭi
aruṭṭikaḻ ñāṉa matupurin tāṉē`,
    english: `1518: Grace Leads Soul Through Successive Stages
She tempted the Soul with guiles,
Took him to Her bosom,
Shook him from stupor,
Dispelled his Karmaic hordes,
Destroyed them to the roots,
Filled him with rapture
Lifted the veil of his Ignorance
Granted many a favour
And then, then, bestowed on him Her Grace that illumines.`,
    elaborationEnglish: `Mantras 1518 & 1519
Through successive stages, like drawing him away from temptations to which the jiva falls a prey and eradication of the karmic hordes and primordial ignorance, the Damsel of Grace liberates the soul. Sporting in the holy waters of the Sakti's Grace makes the jiva forget the filthy waters of virgin's lust, for the Holy Virgin's waters of Grace snap the cycle of births.`,
    elaborationTamil: `சாதகர்கள் தன்னை நினைந்து உருகும் படி செய்து அவர்களோடு எப்போதும் சேர்ந்தே இருந்து மாயையாகிய மயக்கத்தை நீக்கி விட்டு விரைவாக நீங்கிச் செல்லும் படி மிரட்டி வினைகளை அறுத்து விட்டு பேரின்பத்தை அனுபவிக்கும் படி செய்து மாயையினால் உண்மையை அறியும் ஞானக்கண் இல்லாத குருட்டுத் தன்மையை நீக்கி விட்டு இறைவனின் தன்மைகளை பல விதங்களில் கண்டு உணரும் படி செய்து பேரருள் திகழ்கின்ற உண்மை ஞானத்தை சாதகர்கள் அடையும் படி செய்து அருளுகின்றாள் இறை சக்தி.`,
  },
  {
    id: 1520, tantraId: 5, verseNumber: 1519,
    tamil: `கன்னித் துறைபடிந் தாடிய ஆடவர்
கன்னித் துறைபடிந் தாடுங் கருத்திலர்
கன்னித் துறைபடிந் தாடுங் கருத்துண்டேற்
பின்னைப் பிறவி பிறிதில்லை தானே`,
    transliteration: `kaṉṉit tuṟaipaṭin tāṭiya āṭavar
kaṉṉit tuṟaipaṭin tāṭuṅ karuttilar
kaṉṉit tuṟaipaṭin tāṭuṅ karuttuṇṭēṟ
piṉṉaip piṟavi piṟitillai tāṉē`,
    english: `1519: Descent of Grace Snaps Cycle of Births
They that have sported in the waters of Virgin Grace,
No more shall wallow in the filthy waters of virgin's lust;
If they but seek to sport in the Holy Virgin's Waters of Grace,
No more births shall they in future take.`,
    elaborationTamil: `அருள் சக்தி வருகின்ற வழியின் முறையை கடைபிடித்து அதன் படியே நடக்கின்ற சாதகர்கள் அந்த முறையை கடைபிடிப்பதின் மூலம் பிறவிக்கான வினைகளை அறுத்து பிறவி இல்லாத நிலையை எவ்வாறு பெறுவது எனும் ஞானம் இல்லாதவராக இருக்கின்றார்கள். அருள் சக்தி வருகின்ற வழியின் முறையை கடைபிடித்து அதன் படியே நடந்து பிறவிக்கான வினைகளை அறுத்து பிறவி இல்லாத நிலையை பெறுகின்ற ஞானத்தை தமது இடைவிடாத சாதகத்தினால் சாதகர்கள் அறிந்து கொண்டு விட்டால் இனி பிறக்க வேண்டிய பிறவி என்று வேறு எதுவும் அவர்களுக்கு இல்லாமல் போய் விடும்.`,
  },
  {
    id: 1521, tantraId: 5, verseNumber: 1520,
    tamil: `செய்யன் கரியன் வெளியன் நற் பச்சையன்
எய்த வுணர்ந்தவர் எய்வர் இறைவனை
மைவென் றகன்ற பகடுரி போர்த்தவெங்
கைய னிவனென்று காதல்செய் வீரே`,
    transliteration: `ceyyaṉ kariyaṉ veḷiyaṉ naṟ paccaiyaṉ
eyta vuṇarntavar eyvar iṟaivaṉai
maiveṉ ṟakaṉṟa pakaṭuri pōrttaveṅ
kaiya ṉivaṉeṉṟu kātalcey vīrē`,
    english: `1520: Lord is Soul's Redeemer
He is the Red One (Destroyer)
The Dark One (Preserver)
The White One (Creator)
The Green One (Redeemer)
They who know Him thus, free of doubt
Of a certain shall seek Him;
Remember this;
His are the sinewy arms
That skinned the dark massive elephant
And donned it for a vesture;
Do therefore, seek Him and adore Him.`,
    elaborationEnglish: `The Lord plays the multi-role of Destroyer, Preserver, Creator and Redeemer. Realisation of this truth and adoration of Him will make the jiva feel the might of His sinewy arms.

The ‘significance of attributing different colours to Siva’s form is explained here.

Mantras 1520 & 1521

Siva and Sakti are one and the same. So praise Him in devotion daily. He is truly the unfailing proof. Beholding the vision of Sakti and Siva together dispels darkness.`,
    elaborationTamil: `சிவந்த மேனியில் அருளை வழங்குபவன் கரிய மேனியில் மாயையால் மறைக்கின்றவன் வெள்ளை மேனியில் அண்ட சராசரங்களிலும் ஜோதியாய் பரவி இருக்கின்றவன் நன்மையைத் தந்து பச்சை மேனியில் ஆன்மாக்களை காத்து அருளுகின்றவன் இப்படி பலவிதமான தன்மைகளை கண்டு உணர்ந்து கொண்டவர்களுக்கு அவர்கள் கண்ட தன்மையிலேயே அருளை வழங்குகின்ற இறைவனை கருமை நிறம் கொண்டு அகங்காரத்தை இல்லாமல் செய்து யானையின் தோல் போன்ற ஆணவத்தை உரித்து எடுத்து தம்மேல் போர்த்திக் கொண்டு நெருப்புக் கணலை கையில் கொண்டு பிறவிகளை அறுத்து முக்தியை அருளபவன் அவனே என்று உணர்ந்து அவன் மேல் பேரன்பு கொள்ளுங்கள்.`,
  },
  {
    id: 1522, tantraId: 5, verseNumber: 1521,
    tamil: `எய்திய காலங்கள் எத்தனை யாயினுந்
தையலுந் தானுந் தனிநா யகமென்பர்
வைகலுந் தன்னை வணங்கு மவர்கட்குக்
கையிற் கருமஞ்செய் காட்டது வாமே`,
    transliteration: `eytiya kālaṅkaḷ ettaṉai yāyiṉun
taiyalun tāṉun taṉinā yakameṉpar
vaikalun taṉṉai vaṇaṅku mavarkaṭkuk
kaiyiṟ karumañcey kāṭṭatu vāmē`,
    english: `1521: Siva and Sakti are One and Same
Infinite the passage of Time's Flood
Yet they say, He and His Consort stand one;
For them that adore Him daily in devotion,
He is verily the unfailing proof
Of labour readily rewarded.`,
    elaborationTamil: `சாதகர்கள் இறைவனை எந்த வடிவத்திலும் எந்த தன்மையிலும் தாம் எடுத்துக் கொண்ட எந்த சாதகத்தின் மூலமாகவும் சாதகம் செய்து வழிபடுகின்ற காலங்கள் எத்தனை எத்தனை வருடங்களாக இருந்தாலும் ஒன்றோடு ஒன்று தைப்பது போல பிண்ணிப் பிணைந்து இருக்கின்ற இறைவியும் இறைவனும் சாதகர்கள் வணங்கக் கூடிய அனைத்து வடிவத்திற்கும் அனைத்து தன்மைக்கும் ஒரே தலைவராக இருக்கின்றார் என்பதை தமக்குள் உணர்ந்தவர்கள் சொல்லுவார்கள். ஆகவே தினந்தோறும் சூரிய உதயத்திற்கு முன்பே எழுந்து எந்த வடிவத்திலும் எந்த தன்மையிலும் இறைவனை வணங்குகின்ற சாதகர்களுக்கு அவர்களின் கைகளினால் சாதகங்கள் செய்த வழிபாட்டிற்கு அவர்களின் கையில் இருக்கின்ற ரேகைகள் போலவே உடனுக்குடன் பலன்களை தருபவனாக இறைவன் இருக்கின்றான்.`,
  },
  {
    id: 1523, tantraId: 5, verseNumber: 1522,
    tamil: `கண்டுகொண்டோமிரண்டுந்தொடர்ந் தாங்கொளி
பண்டுபண் டோயும் பரமன் பரஞ்சுடர்
வண்டுகொண் டாடு மலர்வார் சடையண்ணல்
நின்றுகண் டார்க்கிருள் நீக்கிநின் றானே`,
    transliteration: `kaṇṭukoṇṭōmiraṇṭuntoṭarn tāṅkoḷi
paṇṭupaṇ ṭōyum paramaṉ parañcuṭar
vaṇṭukoṇ ṭāṭu malarvār caṭaiyaṇṇal
niṉṟukaṇ ṭārkkiruḷ nīkkiniṉ ṟāṉē`,
    english: `1522: Vision of Sakti and Siva in Union
Given unto me was to vision the Light
That shone from the Twain in unison;
It was verily the Light Divine of the Ancient One,
In whose matted locks festooned with flowers,
The bees dance drunk with nectar;
They that waited in patience and prayer
They indeed saw Him-their darkness dispelled.`,
    elaborationTamil: `கண்டு கொண்டோம் இறைவியும் இறைவனும் பிண்ணிப் பிணைந்து தொடர்ச்சியாக விளங்குகின்ற ஆகாயத்தில் இருக்கின்ற ஒளியை. ஆதிகாலத்திலிருந்தே இருக்கின்ற அந்த ஒளியை கண்டு அந்த ஒளியின் நுணுக்கத்தை உணர்ந்தது என்னவென்றால் பரம்பொருளாகிய இறைவனே அந்த பரம் ஜோதியாகவும் இருக்கின்றான் என்பதே ஆகும். வண்டுகள் நறுமணமிக்க மலர்களில் உள்ள தேனை உண்டு களிப்பில் ஆடுவது போல அடியவர்களை தன் அமிழ்தத்தினை உண்டு பேரின்பத்தில் ஆடச் செய்கின்ற நீண்டு வளருகின்ற பிண்ணிய சடையை அணிந்து இருக்கின்ற தலைவனும் அடியவனுமாகிய இறைவனை தமக்குள் இருக்கும் ஜோதியாக கண்டு உணர்ந்து கொண்டவர்களுக்கு மாயையை நீங்கி இறைவன் எப்போதும் அருள் சக்தியாக நிற்கின்றான்.`,
  },
  {
    id: 1524, tantraId: 5, verseNumber: 1523,
    tamil: `அண்ணிக்கும் பெண்பிள்ளை அப்பனார் தோட்டத்தில்
எண்ணிக்கும் ஏழேழ் பிறவி யுணர்விக்கும்
உண்ணிற்ப தெல்லாம் ஒழிய முதல்வனைக்
கண்ணுற்று நின்ற கனியது வாகுமே`,
    transliteration: `aṇṇikkum peṇpiḷḷai appaṉār tōṭṭattil
eṇṇikkum ēḻēḻ piṟavi yuṇarvikkum
uṇṇiṟpa tellām oḻiya mutalvaṉaik
kaṇṇuṟṟu niṉṟa kaṉiyatu vākumē`,
    english: `1523: Fruit of Grace
In the garden of the Heavenly Father
Is that Damsel of Grace;
She approaches you,
Reveals the mystery of the births beyond count,
And destroys their very seed;
And then you vision the Primal One;
That, indeed, is the fruit of Her Grace.`,
    elaborationEnglish: `Mantras 1523 & 1524

Sakti is the Goddess of the mountain regions and of exotic blossoms. Vision of the Primal One is the fruit of Her Grace. That is granted when the Bride of Grace, seated in the garden of the heavenly Bride-Groom, destroys the very seeds of birth. Devotion to her grants the prowess of potential tapas that leads to liberation.`,
    elaborationTamil: `எப்போதும் இளமையுடன் இயங்கிக் கொண்டே இருக்கின்ற பெண் தன்மை கொண்ட பிள்ளையாகிய இறைவியின் அருட் சக்திக்கு தந்தையாக இருக்கின்ற இறைவனுக்கு சொந்தமாகிய அண்ட சராசரங்கள் எனும் தோட்டத்தில் இருக்கும் எண்ணிலடங்காத அளவிற்கு இருக்கின்ற மொத்தம் பதினான்கு உலகங்களிலும் பல விதமாக எடுக்கின்ற அனைத்து பிறவிகளையும் சாதகருக்கு உணர வைத்து, சாதகருக்குள் நிற்கின்ற மும்மலங்களாகிய ஆணவம் கன்மம் மாயை ஆகிய அனைத்தையும் அழிய வைக்கின்ற ஆதி மூலமாகிய இறைவனை அடைய செய்து சாதகரின் கண்ணிற்கு உள்ளே நின்று அனைத்தையும் உணர வைக்கின்ற பேரின்ப ஞானமாக அந்த அருள் சக்தியே இருக்கின்றாள்.`,
  },
  {
    id: 1525, tantraId: 5, verseNumber: 1524,
    tamil: `பிறப்பை யறுக்கும் பெருந்தவம் நல்கும்
மறப்பை யறுக்கும் வழிபட வைக்குங்
குறப்பெண் குவிமுலை கோமள வல்லி
சிறப்பொடு பூசனை செய்யநின் றார்க்கே`,
    transliteration: `piṟappai yaṟukkum peruntavam nalkum
maṟappai yaṟukkum vaḻipaṭa vaikkuṅ
kuṟappeṇ kuvimulai kōmaḷa valli
ciṟappoṭu pūcaṉai ceyyaniṉ ṟārkkē`,
    english: `1524: They That Adore Sakti Shall Be Granted Things Spiritual
She is the Damsel of the montane regions;
Of shapely breasts and delicate beauty;
If you in devotion adore Her,
She cuts the bonds of birth asunder;
Grants the prowess of mighty tapas;
Scorches the soul's forgetfulness;
And leads you to liberation path.`,
    elaborationTamil: `இனிமேல் எடுக்க வேண்டிய அனைத்து பிறவிகளையும் அறுத்து விடக் கூடிய மிகப் பெரும் தவத்தை அருளுபவளாகவும் இறைவனிடமிருந்தே பிரிந்து வந்திருக்கின்றோம் என்பதை மறந்து விட்டு மாயையில் இருக்கின்ற நிலையை அறுக்கின்ற வழியில் சாதகர்களை செல்ல வைக்கின்றவளாகவும் அதற்கு தேவையான அனைத்து ஞானங்களையும் அருளுகின்ற சக்தியாகவும் குவிந்த மார்பகங்களின் மூலம் அமிழ்தத்தை வழங்குபவளாகவும் அடியவர்களை தன் பால் ஈர்க்கின்ற பேரழகுடன் என்றும் இளமையானவளாகவும் இருக்கின்ற இறைவியானவள் சிறப்பு பொருந்தியவளாக அவர்களை பூஜைகள் செய்ய வைத்துக் கொண்டே அருட் சக்தியாக எப்போதும் சேர்ந்தே நிற்கின்றாள்.`,
  },
  {
    id: 1526, tantraId: 5, verseNumber: 1525,
    tamil: `தாங்குமின் எட்டுத் திசைக்குந் தலைமகன்
பூங்கமழ் கோதைப் புரிகுழ லாளொடும்
ஆங்கது சேரும் அறிவுடை யார்கட்குத்
தூங்கொளி நீலந் தொடர்தலு மாமே`,
    transliteration: `tāṅkumiṉ eṭṭut ticaikkun talaimakaṉ
pūṅkamaḻ kōtaip purikuḻa lāḷoṭum
āṅkatu cērum aṟivuṭai yārkaṭkut
tūṅkoḷi nīlan toṭartalu māmē`,
    english: `1525: Light of Grace Illumines Path of Devotee
He is the Lord of all Space in directions eight;
Bear His holy Feet on your head,
And He shall appear to you
With His Consort of Grace
Wreathed in clusters of fragrant blooms
In Her twisted tresses;
And for them who are thus made wise
The Blue Flame of Her floating Grace
Shall, for ever, illumine the Path.`,
    elaborationEnglish: `Mantras 1525 & 1526

Near the Holy Feet of the Lord are all worlds. He shall descend with his Lady Companion - Sakti of Grace - who will enlighten the path of the devotees. Wisdom gives the unsurpassable boon of Grace; and when Grace visits, the Lord, whom nothing can equal draws near. When Grace descends, jiva is purified. He then mingles in Siva.`,
    elaborationTamil: `எட்டு விதமான திசைகளுக்கும் தலைவியாக வீற்றிருக்கின்ற இறைவியை சாதகர்கள் தங்களின் உள்ளத்திற்குள் தாங்கிக் கொண்டால் சகஸ்ரதளத்தில் இருக்கின்ற ஆயிரம் இதழ் கொண்ட தாமரை மலரில் இருந்து அருளானது உடல் முழுவதும் பரந்து விரிகின்ற அமிழ்தம் ஊறி பெருகுவதில் அருள் புரிகின்ற கூந்தலைக் கொண்ட இறைவியோடு அவள் இருக்கின்ற சகஸ்ரதளத்தில் தமது குண்டலினி சக்தியை கொண்டு சேர்க்கின்ற ஞானத்தை அறிந்து கொண்டவர்களுக்கு இது வரை நெற்றிக்கு நடுவில் தூங்கிக் கொண்டு இருந்த ஜோதியாகிய நீல நிற ஒளியானது விழிப்பு பெற்றதால் உருவாகும் பேரறிவு ஞானமானது சாகதருக்கு எப்போதும் தொடர்ந்து கொண்டே இருக்கும்.`,
  },
  {
    id: 1527, tantraId: 5, verseNumber: 1526,
    tamil: `நணுகினு ஞானக் கொழுந்தொன்று நல்கும்
பணிகிலும் பன்மலர் தூவிப் பணிவன்
அணுகிய தொன்றறி யாத வொருவன்
அணுகும் உலகெங்கு மாவியு மாமே`,
    transliteration: `naṇukiṉu ñāṉak koḻuntoṉṟu nalkum
paṇikilum paṉmalar tūvip paṇivaṉ
aṇukiya toṉṟaṟi yāta voruvaṉ
aṇukum ulakeṅku māviyu māmē`,
    english: `1526: Lord Draws Near When Grace Visits
Seek close,
That soft Flame of Wisdom shall grant you
The peerless gift of Grace;
When you adore Him
Do so, showering blooms at His Feet
As I do,
Then shall He draw near you
Whom nothing can ever near;
He is truly the life pervasive of worlds all.`,
    elaborationTamil: `அருள் சக்தியை நெருங்கிச் சென்று அடைந்தால் ஞானத்தின் உச்சமாக இருக்கின்ற பேரறிவு ஞானத்தை அந்த அருட் சக்தியே வழங்குவாள். அப்படி இல்லாமல் அருள் சக்தியை ஞானத்தால் நெருங்கி அடைய முடியாவிட்டாலும் பல விதமான மலர்களை தூவி வணங்கி வழிபடும் போது அந்த வழிபாட்டின் பயனால் நம்மை நெருங்கி வரும் அருட் சக்தியை தன் அறிவால் முழுவதுமாக அறிந்து கொள் முடியாத சாதகனாக ஒருவன் இருந்தாலும் அருள் சக்தி வழங்கும் ஞானத்தால் அறியும் போது அவன் இருக்கின்ற உலகம் மட்டுமின்றி அனைத்து உலகங்கள் எங்கும் இருக்கின்ற அனைத்து பொருள்களிலும் நிற்கின்ற ஆன்மாவாக அந்த அருட் சக்தியே இருக்கின்றாள் என்பதை அறிந்து கொள்ளலாம். கருத்து: யோகத்தாலும் ஞானத்தினாலும் இறைவியை அடைய முடியாதவர்கள் கூட சரியை மற்றும் கிரியையின் மூலமே இறைவியை அடைந்து விட முடியும்.`,
  },
  {
    id: 1528, tantraId: 5, verseNumber: 1527,
    tamil: `இருவினை நேரொப்பில் இன்னருட் சத்தி
குருவென வந்து குணம்பல நீக்கித்
தருமெனு ஞானத்தால் தன்செய லற்றால்
திரிமலந் தீர்ந்து சிவனவ னாமே`,
    transliteration: `iruviṉai nēroppil iṉṉaruṭ catti
kuruveṉa vantu kuṇampala nīkkit
tarumeṉu ñāṉattāl taṉceya laṟṟāl
tirimalan tīrntu civaṉava ṉāmē`,
    english: `1527: When Grace Descends as Guru
When Jiva attains the state of Neutrality
To deeds, good and evil,
Then does divine Grace in Guru form descend,
Removes attributes all,
Implants Jnana that is unto a heavenly cool shade;
The Jiva thus rid of egoity,
And other Impurities Three,
Shall with Siva in union merge.`,
    elaborationTamil: `நன்மை தீமை ஆகிய இரண்டு விதமான வினைகளையும் சரிசமமாக பாவித்து அனுபவிக்கும் நிலையை அடைந்த சாதகருக்குள் தனக்கு ஒப்பானது என்று ஒன்றும் இல்லாதவளாகிய இனிமையான பேரருளைக் கொண்ட இறைவியானவள் குரு எனும் நிலையில் வந்து சாதகருக்குள் நன்மை தீமை என்று பல விதமாக இருக்கின்ற அனைத்து தன்மைகளையும் நீக்கி விட்டு, அவளது பெரும் கருணையினால் தரப்படுவது என்று அறியப்படுகின்ற பேரறிவு ஞானத்தை தந்து அருளுவாள். அந்த ஞானத்தால் சாதகர் தன்னுடைய செயல் என்று ஒன்றும் இல்லாமல் இருக்கும் நிலையை அடைந்து விட்டால் சாதகருக்குள் இருக்கின்ற ஆணவம், கன்மம், மாயை ஆகிய மூன்று விதமான மலங்களும் நீங்கப் பெற்று சிவம் எனும் பரம் பொருளாகவே சாதகரும் ஆகி விடுவார்.`,
  },
  {
    id: 1529, tantraId: 5, verseNumber: 1528,
    tamil: `இரவும் பகலும் இலாத இடத்தே
குரவஞ் செய்கின்ற குழலியை உன்னி
அரவஞ்செய் யாமல் அவளுடன் சேரப்
பரிவொன்றி லாளும் பராபரை தானே`,
    transliteration: `iravum pakalum ilāta iṭattē
kuravañ ceykiṉṟa kuḻaliyai uṉṉi
aravañcey yāmal avaḷuṭaṉ cērap
parivoṉṟi lāḷum parāparai tāṉē`,
    english: `1528: How to Win Lady of Grace
In the Emptiness Vast where neither night nor day is
The Lady of Long Tresses dances in rapture;
Think of Her, make no sound
And in silence woo Her;
In endearment all
She draws you unto Her bosom,
And grants you Her favours;
Verily, Verily, She is the Paraparai,
The Power Supreme.`,
    elaborationEnglish: `Mantras 1528 & 1529

Woo the Goddess of Supreme Power and Prowess (Paraparai). Dancing in rapture in the Vast Space, She will grant Her favours. Then, He, the sun, the moon, and the light of Grace which illumined the corporeal body dispelling darkness - all abide in you forever.`,
    elaborationTamil: `இரவு பகல் எனும் இரண்டு விதமான நிகழ்வுகளையும் உணராத அளவிற்கு தன் நிலை மறந்து இருக்கின்ற சாதகரின் உள்ளத்தில் குரவம் எனும் மலரை பின்னியிருக்கின்ற கூந்தலைக் கொண்ட இறைவியை அந்த உள்ளத்தில் நினைத்துக் கொண்டே எந்த விதமான ஆரவாரமும் செய்யாமல் அவளோடு சேர்ந்து ஒன்றாக இலயித்து இருந்தால் தனது மாபெரும் கருணை எனும் அருளினால் சாதகரை ஆட்கொண்டு அருளுவாள் பராவாகிய இறைவனும் பரையாகிய இறைவியும் சேர்ந்து இருக்கும் அருள் சக்தி.`,
  },
  {
    id: 1530, tantraId: 5, verseNumber: 1529,
    tamil: `மாலை விளக்கும் மதியமும் ஞாயிறுஞ்
சாலை விளக்குந் தனிச்சுடர் அண்ணலுள்
ஞானம் விளக்கிய நாதன்என் உள்புகுந்(து)
ஊனை விளக்கி யுடனிருந் தானே`,
    transliteration: `mālai viḷakkum matiyamum ñāyiṟuñ
cālai viḷakkun taṉiccuṭar aṇṇaluḷ
ñāṉam viḷakkiya nātaṉeṉ uḷpukun(tu)
ūṉai viḷakki yuṭaṉirun tāṉē`,
    english: `1529: Inner Light of Grace
He is the Sun and the Moon
That dispells darkness;
He is the Light on the path,
The Peerless Flame, the Supreme Lord;
The Master that illumined the Light within me;
He entered in me and lighted up the corporeal body;
And then, aye, with me bided for ever and ever.`,
    elaborationTamil: `அந்தி சாயும் வேளையில் வெளிச்சத்திற்காக ஏற்றப்படுகின்ற விளக்குகளில் இருந்து வருகின்ற ஒளியையும், இரவு நேரங்களில் நிலவில் இருந்து வருகின்ற ஒளியையும், பகல் நேரங்களில் சூரியனில் இருந்து வருகின்ற ஒளியையும், இறைவனை வணங்கும் பூஜைகளில் ஏற்றி வைக்கின்ற தீபங்களில் இருந்து வருகின்ற ஒளியையும், தனிப் பெரும் சுடராக இருக்கின்ற இறைவனின் ஜோதி உருவமாகவே சாதகர் பார்த்து உணர்ந்தால், உலகத்தை விளக்கி அருளுகின்ற தலைவனாகிய இறைவன் அவரது உடலுக்குள் புகுந்து வந்து, அவரது உடலுக்குள் இருக்கின்ற உண்மை பொருளையும் விளக்கி அவர் அறியும் படி செய்து அவருடன் எப்போதும் இருப்பான்.`,
  },
  
  {
    id: 1531, tantraId: 5, verseNumber: 1530,
    tamil: `ஆயத்துள் நின்ற அறுசம யங்களுங்
காயத்துள் நின்ற கடவுளைக் காண்கிலர்
மாயக் குழியில் விழுவர் மனைமக்கள்
பாசத்தில் உற்றுப் பதைக்கின்ற வாறே`,
    transliteration: `āyattuḷ niṉṟa aṟucama yaṅkaḷuṅ
kāyattuḷ niṉṟa kaṭavuḷaik kāṇkilar
māyak kuḻiyil viḻuvar maṉaimakkaḷ
pācattil uṟṟup pataikkiṉṟa vāṟē.`,
    english: `1530: The Six Faiths Avail Not
The Six faiths severally congregate,
Yet, not one knows the God within;
Deep into the pit of illusion, their adherents drop,
And fastened hard by familial ties of bondage,
They shake and tremble, in vain impotence.`,
    elaborationEnglish: `Mantras 1530 - 1533

The six faiths, being tied fast to the earthly fetters shake and shiver in vain, unable to cognise God, who is within. The Lord, the Pinnacle and the Magnificent seated in the lotus of our hearts, enters this hollow abode of human flesh and then silently parts. This deep design of His is beyond the apprehension of the formal faiths. Intense faith and steadfastness help in the realisation of the omnipresence of the Lord.

What are the “Six Faiths’’ (want, Samayam means here ‘religion’, ‘sect’ or that Mular refers to here? They are not those described in it can be safely affirmed.`,
    elaborationTamil: `மக்கள் கூட்டத்திற்கு உள்ளே வழிகாட்டிகளாக நிற்கின்ற ஆறு விதமான சமயங்களும் உடலுக்கு உள்ளே நிற்கின்ற இறைவனை காண்பது இல்லை. அதனால் இறைவனை அடைய வேண்டும் என்று வழிபாடு செய்யாமல் ஆசைகளுக்காக வெளிப்புறமாக இந்த ஆறு விதமான சமயங்களைப் பின் பற்றி அவற்றின் வழியே நடக்கின்றவர்கள் உண்மையை அறியாத மாய குழியிலேயே விழுந்து கிடப்பார்கள். அவர்களுடைய மனைவியின் மீதும் பிள்ளைகளின் மீதும் இருக்கின்ற பாசத்தினால் ஆட் கொள்ளப் பட்டு எப்போதும் பரிதவிப்பில் இருக்கின்ற வழியிலேயே வாழ்கின்றார்கள். கருத்து: சமையங்கள் என்பதன் பொருள் இறைவனை அடைவதற்கு முறைப்படி கடைபிடித்து செல்லும் வழிகளாகும். இவற்றை தமக்கு உள்ளே இருக்கின்ற இறைவனை உணர்ந்து அடைய வேண்டும் என்ற எண்ணத்தோடு அன்போடும் பக்தியோடும் செய்யாமல் வெளிப்புறமாக உலக ஆசைகளுக்காக செய்வதால் இறைவனை அடைய முடியாது. ஆகையால் புறத்தில் செய்கின்ற ஆறு வழிகளும் நிந்தனை செய்யப் படுகின்றது. இறைவனை அடையும் முறையான ஆறு வித வழிகள்: தியானம் – மந்திரத்தை மனதிற்குள் தியானித்தல் செபம் – அக வழிபாடு மூலம் செபித்தல் பூஜை – புற வழிபாடு மூலம் செபித்தல் சக்கரம் – சக்கரங்கள் அமைத்து செபித்தல் ஞானம் – மந்திரத்தின் பொருளை தேடி ஆராய்ந்து அறிந்து கொள்ளுதல் புத்தி – மந்திரத்தின் ஒவ்வொரு எழுத்தையும் ஆராய்ந்து அறிந்து கொள்ளுதல்`,
  },
{
    id: 1532, tantraId: 5, verseNumber: 1531,
    tamil: `உள்ளத்து ளேதான் கரந்தெங்கும் நின்றவன்
வள்ளல் தலைவன் மலருறை மாதவன்
பொள்ளற் குரம்பைப் புகுந்து புறப்படுங்
கள்ளத் தலைவன் கருத்தறி யார்களே`,
    transliteration: `uḷḷattu ḷētāṉ karanteṅkum niṉṟavaṉ
vaḷḷal talaivaṉ malaruṟai mātavaṉ
poḷḷaṟ kurampaip pukuntu puṟappaṭuṅ
kaḷḷat talaivaṉ karuttaṟi yārkaḷē`,
    english: `1531: Formal Faiths Know not God Within
He hides in your heart
Yet does He pervade all;
He is the Munificient One;
The Lord Supreme;
Of austere penance
He is seated on the lotus of our hearts;
The cunning Master-Thief
In stealth enters this hollow abode of human flesh
And then leaves it;
None knows His deep design.`,
    elaborationTamil: `உயிர்களின் உள்ளத்திற்கு உள்ளே தானாகவே விரும்பி வீற்றிருக்கின்றவனும், அண்ட சராசரங்கள் எங்கும் நிறைந்து நிற்கின்றவனும், உயிர்களுக்குத் தேவையான அனைத்தையும் அருளுகின்ற வள்ளலும், அனைத்திற்கும் தலைவனும், உயிர்களின் நெஞ்சத் தாமரை மலரின் மேல் வீற்றிருக்கின்ற மாபெரும் தவத்தை உடையவனும், துவாரங்களை கொண்ட உடலுக்குள் கருவிலேயே புகுந்து இருப்பவனும், அந்த உடலின் ஆயுள் முடியும் போது வெளியேறி செல்பவனும், இவை அனைத்தையும் மறைந்து இருந்தே செய்கின்ற தலைவனும் ஆகிய இறைவனை அறிந்து கொள்ளும் முறையை ஆசைகளுக்காக புற வழிபாடு செய்கின்றவர்கள் அறியாமல் இருக்கின்றார்கள்.`,
  },
  {
    id: 1533, tantraId: 5, verseNumber: 1532,
    tamil: `உள்ளத்தும் உள்ளன் புறத்துள்ளன் என்பவர்க்
குள்ளத்தும் உள்ளன் புறத்துள்ளன் எம்மிறை
உள்ளத்தும் இல்லை புறத்தில்லை என்பவர்க்
குள்ளத்தும் இல்லை புறத்தில்லை தானே`,
    transliteration: `uḷḷattum uḷḷaṉ puṟattuḷḷaṉ eṉpavark
kuḷḷattum uḷḷaṉ puṟattuḷḷaṉ emmiṟai
uḷḷattum illai puṟattillai eṉpavark
kuḷḷattum illai puṟattillai tāṉē`,
    english: `1532: Existence of God is an Act of Faith
Say, Lord is within you and without you
Then sure my Lord is within you and without you;
To them they say,
He is neither within you or without you
Sure is He nowhere for them.`,
    elaborationTamil: `உள்ளத்திற்கு உள்ளேயும் கலந்து இருக்கின்றான் வெளியேயும் அனைத்திலும் கலந்து இருக்கின்றான் என்று நம்புபவர்களுக்கு உள்ளத்திற்கு உள்ளேயும் கலந்து இருக்கின்றான் வெளியேயும் அனைத்திலும் கலந்து இருக்கின்றான் எமது உரிமையான இறைவன். உள்ளத்திற்கு உள்ளேயும் இல்லை வெளியேயும் எங்கும் இல்லை என்று நினைப்பவர்களுக்கு உள்ளத்திற்கு உள்ளே உணரும் படியும் இல்லாமல் வெளியேயும் எங்கும் அறிந்து கொள்ளும் படியும் இல்லாமல் இருக்கின்றான் இறைவன்.`,
  },
  {
    id: 1534, tantraId: 5, verseNumber: 1533,
    tamil: `ஆறு சமயமும் கண்டவர் கண்டிலர்
ஆறு சமயப் பொருளும் அவனலன்
தேறுமின் தேறித் தெளிமின் தெளிந்தபின்
மாறுதல் இன்றி மனைபுக லாமே`,
    transliteration: `āṟu camayamum kaṇṭavar kaṇṭilar
āṟu camayap poruḷum avaṉalaṉ
tēṟumiṉ tēṟit teḷimiṉ teḷintapiṉ
māṟutal iṉṟi maṉaipuka lāmē`,
    english: `1533: God is Beyond All Formal Faiths
They founded the Six Faiths,
Yet they found Him not;
What the Six Faiths talk of is not He;
Do you yourself in faith seek Him,
And be resolved of doubts all;
And then sure shall you enter your Father's Mansion.`,
    elaborationTamil: `இறைவனை அடைவதற்கான ஆறு விதமான வழி முறைகளையும் கண்டு அதன் பொருளை மேம்போக்காக அறிந்து கொண்டவர்கள் அந்த வழிமுறைகளின் உட் பொருளாக இருக்கின்ற தத்துவங்களை அறிந்து கொள்ள வில்லை. இறைவனை அடைவதற்கான ஆறு விதமான வழி முறைகளும் சொல்லுகின்ற உட் பொருளான தத்துவங்களை அறிந்து கொள்ளாத காரணத்தால் அவர்களுக்கு எந்தவிதமான பயனும் இல்லை. ஆகவே ஆறு விதமான வழி முறைகளின் உட் பொருளை ஆராய்ந்து அறிந்து கொள்ளுங்கள். அறிந்த பிறகு அதனை தெளிவாக உணர்ந்து கொள்ளுங்கள். அவ்வாறு தெளிவாக உணர்ந்த பிறகு எந்த விதமான மாறுபாடும் இல்லாமல் உறுதியாக வீடு பேறு என்று அறியப்படுகின்ற முக்தியை அடைவது கைகூடும். குறிப்பு: ஆறு சமயங்கள் என்பது இறைவனை அடைவதற்கான ஆறு வழி முறைகளாகும். இதனை பாடல் #1530 இல் பார்க்கவும்.`,
  },
  {
    id: 1535, tantraId: 5, verseNumber: 1534,
    tamil: `சிவமல்ல தில்லை யறையே சிவமாந்
தவமல்ல தில்லை தலைப்படு வார்க்கிங்(கு)
அவமல்ல தில்லை அறுசம யங்கள்
தவம்வல்ல நந்திதாள் சார்ந்துய்யு நீரே`,
    transliteration: `civamalla tillai yaṟaiyē civamān
tavamalla tillai talaippaṭu vārkkiṅ(ku)
avamalla tillai aṟucama yaṅkaḷ
tavamvalla nantitāḷ cārntuyyu nīrē`,
    english: `1534: God Can Be Reached Only by Devotion
Proclaim you this:
There is nothing except Siva
No tapas except it be for Him
The Six Faiths are nothing but a dreary waste;
Do seek Nandi of mighty penance;
You shall indeed be redeemed truly.`,
    elaborationEnglish: `Mantras 1535 - 1537

Siva is the only Lord; and the six faiths are but a dreary waste. Being materialistic, the six faiths do not lead to the final state. Devotion to Siva alone grants liberation.`,
    elaborationTamil: `சிவம் என்று அறியப்படுகின்ற பரம்பொருளைத் தவிர வேறு பரம்பொருள் எதுவும் இல்லை. இறை என்று அறியப்படுவது சிவப் பரம்பொருளே ஆகும். இந்த உலகத்தில் இறைவனை அடைய வேண்டும் என்று உறுதியாக செயல் படுபவர்களுக்கு தவம் என்கின்ற உயர்ந்த நிலையை தவிர வேறு உயர்ந்த நிலை எதுவும் இல்லை. ஆனால் ஆறு விதமான வழி முறைகளையும் ஆசைகளுக்காக புற வழிபாடு செய்பவர்களுக்கு இந்த உலகத்தில் பயனில்லாததைத் தவிர வேறு எதுவும் இல்லை. அதனால் தவத்திற்கு உறுதியாக நிற்கின்ற குருநாதனாகிய இறைவனின் திருவடியை சரணடைந்து மேன்மை நிலையை அடையாமல் இருக்கின்றீர்களே.`,
  },
  {
    id: 1536, tantraId: 5, verseNumber: 1535,
    tamil: `அண்ணலை நாடிய ஆறு சமயமும்
விண்ணவ ராக மிகவும் விரும்பியே
முண்ணின் றழியு முயன்றில ராதலான்
மண்ணின் றொழியும் வகையறி யார்களே`,
    transliteration: `aṇṇalai nāṭiya āṟu camayamum
viṇṇava rāka mikavum virumpiyē
muṇṇiṉ ṟaḻiyu muyaṉṟila rātalāṉ
maṇṇiṉ ṟoḻiyum vakaiyaṟi yārkaḷē`,
    english: `1535: The Six Faiths Sought not Freedom from Pasas
They of the Six Faiths sought Lord
Only for heavenly state to gain;
They sought not to be rid of bondage thorns,
And so know not to be rid of this world materiality.`,
    elaborationEnglish: `The path of Siva alone is our defence from earthly sorrows. \\ Tt is the sole path that leads to ultimate liberation through pasa annihilation. Neither the six faiths nor the swollen stream of hundreds of other faiths, tall as their claims are, can lead to the path of Param.`,
    elaborationTamil: `அண்ணலாகிய இறைவனை தேடி அடைய உதவும் ஆறு விதமான வழி முறைகளும் முக்தி அடையவும் தேவர்களாக ஆக வேண்டும் என்று மிகவம் விரும்புகின்ற உயிர்களுக்கு வழி காட்டவே உருவாக்கப் பட்டுள்ளன. ஆனாலும் அந்த ஆறு வழி முறைகளின் உட் பொருளை ஆராய்ந்து அறிந்து கொண்டு உணர்ந்து தெளிவடைவதற்கான முயற்சியை இல்லாதவர்களாக இருக்கின்றார்கள். ஆதலால் வெறும் ஆசைகளுக்காக புற வழிபாடு செய்பவர்களுக்கு அவர்கள் ஆசைப் படுகின்ற அனைத்தும் அழிந்து போவதையும் மற்றவர்கள் ஆசைப் படுகின்ற அனைத்தும் அழிந்து போவதையும் அறிந்து கொண்டு அழியாமல் இருக்கின்ற முறையை அறிந்து கொள்ளாமலேயே இவர்கள் இருக்கின்றார்கள். குறிப்பு: ஆறு சமயங்கள் என்பது இறைவனை அடைவதற்கான ஆறு வழி முறைகளாகும். இதனை பாடல் #1530 இல் பார்க்கவும்.`,
  },
  {
    id: 1537, tantraId: 5, verseNumber: 1536,
    tamil: `சிவகதி யேகதி மற்றுள்ள எல்லாம்
பவகதி பாசப் பிறவியொன் றுண்டு
தவகதி தன்னொடு நேரொன்று தோன்றில்
அவகதி மூவரும் அவ்வகை யாமே`,
    transliteration: `civakati yēkati maṟṟuḷḷa ellām
pavakati pācap piṟaviyoṉ ṟuṇṭu
tavakati taṉṉoṭu nēroṉṟu tōṉṟil
avakati mūvarum avvakai yāmē`,
    english: `1536: Path of Siva Leads to Final Liberation
The Path of Siva alone is Finite Path;
The Other paths but lead to earthly sorrows;
And sure birth in bondage returns to you;
Do you walk in the Holy Path;
And when the One appears,
The triad Impurities that your destruction encompasses
Will, of themselves, meet their own destruction.`,
    elaborationTamil: `சிவப் பரம்பொருளை சரணடைவதே முக்திக்கான வழியாகும். சரணாகதியைத் தவிர வேறு விதமாக இருக்கின்ற வழி முறைகள் அனைத்தும் உலக வாழ்க்கைக்கான வழியாக பாசத் தளைகளுடன் மீண்டும் மீண்டும் பிறவி எடுப்பதற்காகவே இருக்கின்ற வழி முறைகளாகும். சரணாகதியாக தவம் செய்கின்ற வழி முறையை சாதகர்கள் முக்திக்கு நேரான ஒரே வழிமுறையாக எடுத்துக் கொண்டு செய்யாமல் போனால் துன்பமான பிறவிகளுக்கே வழியாக இருக்கின்ற ஆணவம், கன்மம், மாயை ஆகிய மூன்று விதமான மலங்களும் துன்பமான பிறவி எடுப்பதற்கான வழி முறைகளாகவே இருக்கும்.`,
  },
  {
    id: 1538, tantraId: 5, verseNumber: 1537,
    tamil: `நூறு சமயம் உளவா நுவலுங்கால்
ஆறு சமயமவ் ஆறுட் படுவன
கூறு சமயங்கன் கொண்டநெறிநில்லா
ஈறு பரநெறி யில்லா நெறியன்றே`,
    transliteration: `nūṟu camayam uḷavā nuvaluṅkāl
āṟu camayamav āṟuṭ paṭuvaṉa
kūṟu camayaṅkaṉ koṇṭaneṟinillā
īṟu paraneṟi yillā neṟiyaṉṟē`,
    english: `1537: The False Paths Lead not to Param
Forsooth,
The Faiths here below are a hundred in number,
In that swollen stream are the Six Faiths too;
These Faiths take not to the goal they boast of;
They are true Faiths never,
They take you not to Path of Param.`,
    elaborationTamil: `இறைவனை அடைவதற்காக என்று சொல்லப் படுகின்ற நூற்றுக் கணக்கான வழி முறைகள் இருக்கின்றன ஆதலால் அவற்றில் அவரவர்க்கு ஏற்றதை எடுத்துக் கொண்டு கடைபிடிக்கும் போது இறைவனை அடைவதற்கான ஆறு விதமான வழி முறைகளுக்கு உள்ளேயே அந்த நூற்றுக் கணக்கான வழி முறைகளும் அடங்கி விடும். இப்படி ஆறு பிரிவுகளாக இருக்கின்ற வழி முறைகள் அனைத்தும் தாம் எடுத்துக் கொண்ட வழி முறையிலேயே நின்று விடாமல் ஒவ்வொரு வழி முறையிலும் பக்குவம் பெற்ற மிகவும் மேன்மையான நிலையாகிய பரம் பொருளை சென்று அடைகின்ற முக்திக்கான வழி முறை ஒன்று இருக்கின்றது. ஆனால் அதில் நின்று இறைவனை அடையாமல் வெறும் உலக ஆசைகளுக்காக செய்யப் படுகின்ற வழி முறைகளிலேயே நிற்கின்றார்கள்.`,
  },
  {
    id: 1539, tantraId: 5, verseNumber: 1538,
    tamil: `கத்துங் கழுதைகள் போலுங் கலதிகள்
சுத்த சிவமெங்குந் தோய்வற்று நிற்கின்றான்
குற்றம் தெளியார் குணங்கொண்டு கோதாட்டிப்
பித்தேறி நாளும் பிறந்திறப் பாரே`,
    transliteration: `kattuṅ kaḻutaikaḷ pōluṅ kalatikaḷ
cutta civameṅkun tōyvaṟṟu niṟkiṉṟāṉ
kuṟṟam teḷiyār kuṇaṅkoṇṭu kōtāṭṭip
pittēṟi nāḷum piṟantiṟap pārē`,
    english: `1538: Contending Faiths Do Not Help
The contending Paths are unto the braying asses:
The Pure Siva is all-pervasive;
They seek Him not by the right Path,
And so free are not from Impurities;
They shall grow insane
Forever entangled in whirl of birth and death.`,
    elaborationEnglish: `Contending faiths are like the braying asses. They lead but to the swirling of birth and death. Pure Siva is beyond their reach.`,
    elaborationTamil: `காரணமே தெரியாமல் கத்துகின்ற கழுதைகள் போலவே தீய குணம் உள்ளவர்கள் இருக்கின்றார்கள். அதனால் எங்கும் இருக்கின்ற தூய்மையான சிவப் பரம்பொருள் அவர்களால் அறிய முடியாத படி தம்மை மாயையால் மறைத்துக் கொண்டு நிற்கின்றான். தம்மிடம் இருக்கின்ற தீய குணங்களை அறிந்து கொள்ளாமல் நல்ல குணங்களை கடை பிடித்து தீய குணங்களை நீக்கிக் கொள்ளாதவர்கள் தீய குணத்திலேயே மூழ்கி அதனால் பித்து அதிகமாகி தினந்தோறும் வாழ் நாளை வீணடித்து மீண்டும் மீண்டும் பிறந்து இறக்கின்ற பிறவி சுழலிலேயே சிக்கிக் கொண்டு இருப்பார்கள்.`,
  },
  {
    id: 1540, tantraId: 5, verseNumber: 1539,
    tamil: `மயங்குகின் றாரு மதிதெளிந் தாரும்
முயங்கி யிருவினை முழைமுகப் பாச்சி
இயங்கிப் பெறுவரே லீறது காட்டிற்
பயங்கெட் டவர்க்கோர் பரநெறி யாமே`,
    transliteration: `mayaṅkukiṉ ṟāru matiteḷin tārum
muyaṅki yiruviṉai muḻaimukap pācci
iyaṅkip peṟuvarē līṟatu kāṭṭiṟ
payaṅkeṭ ṭavarkkōr paraneṟi yāmē`,
    english: `1539: To Attain Finite Goal
Those who are assailed by doubts
And those who are freed from doubts
When together commingle,
Drive the wild beasts of Karma twine to caves,
And persevere in the pursuit
Then shall Finite Goal be reached;
They that are rid of the terrors of the wild
Shall see the Path that to Para leads.`,
    elaborationEnglish: `Mantras 1539 & 1540

To attain the final goal - freedom from harassing doubts, and perseverance in Siva pursuit are essential. God is with the steadfast and clear-visioned souls. To the doubting and inconstant. He is beyond reach. They realise not His mysterious plan, for which the fleshy body is fashioned.`,
    elaborationTamil: `மாயையிலேயே மயங்கி இருக்கின்றவர்களும், இறைவனை அடையும் வழி முறைகளை கடைபிடித்து அதனால் மாயை நீங்கி தெளிவு பெற்றவர்களும், தம்மால் இயன்ற வரை முயற்சி செய்து நன்மை தீமை ஆகிய இரண்டு விதமான வினைகளையும் அறுப்பதற்கு காரணமாக சுழு முனை நாடியின் துளைக்கு உச்சியில் இருக்கின்ற சகஸ்ரதளத்தில் தமது மூச்சுக்காற்றை இயக்குவதன் மூலம் குண்டலினி சக்தியை கொண்டு சென்று சேர்த்து அமிழ்தத்தை பெற முடிந்தால் முக்தியை அதுவே காண்பித்து, இறப்பு பிறப்பு ஆகிய இரண்டு விதமான பயமும் அழிந்து போய் அவர்களுக்கு ஒரே பரம் பொருளுடன் சேருவதாகிய முக்திக்கு வழியாக அதுவே இருக்கும்.`,
  },
  {
    id: 1541, tantraId: 5, verseNumber: 1540,
    tamil: `சேயன் அணியன் பிணியிலன் பேர்நந்தி
தூயன் துளக்கற நோக்கவல் லார்கட்கு
மாயன் மயக்கிய மானுட ராமவர்
காயம் விளைக்குங் கருத்தறி யார்களே`,
    transliteration: `cēyaṉ aṇiyaṉ piṇiyilaṉ pērnanti
tūyaṉ tuḷakkaṟa nōkkaval lārkaṭku
māyaṉ mayakkiya māṉuṭa rāmavar
kāyam viḷaikkuṅ karuttaṟi yārkaḷē`,
    english: `1540: God is Distant and Near
He is far away,
He is near at hand
He is rid of ailments,
He is of immortal name Nandi;
Transparent to those that have unwavering vision;
Elusive to those who are tossed in doubt;
Such know not the mysterious purpose
For which the fleshly body is fashioned.`,
    elaborationTamil: `நிலையான மனமில்லாதவர்களுக்கு தூரத்தில் இருந்து அருளுபவனும் நிலையான மனமுடையவர்களுக்கு அருகிலே இருப்பவனும் இந்த இரு நிலையில் இருப்பவர்களின் மேலும் பற்று இல்லாதவனும் பெயரில் நந்தி என்று அழைக்கப் படும் இறையே குரு என்ற நிலையில் இருப்பவனும் தூய்மையானவனும் ஆகிய இறைவனை அசைவு இல்லாத மனதுடன் தமக்குள்ளேயே பார்க்க முடிந்தவர்களுக்கு அவ்வாறெல்லாம் இருக்கின்றான் இறைவன். அவ்வாறு பார்க்க முடியாமல் இருக்கின்ற மனிதர்களாகிய மற்றவர்கள் அனைவருக்கும் அவன் மாயனாகவே இருந்து மாயையில் மயக்கி வைத்திருப்பதால் அவர்கள் அனைவரும் தம்முடைய உடலின் மேல் இருக்கின்ற பற்றை குறைத்து உடலுக்குள் இருக்கின்ற ஆன்மாவை அறிந்து கொள்ளுகின்ற முறையை அறியாமல் இருக்கின்றார்கள்.`,
  },
  {
    id: 1542, tantraId: 5, verseNumber: 1541,
    tamil: `வழியரண் டுக்குமோர் வித்தது வான
பழியது பார்மிசை வாழ்தல் உறுதல்
சுழியறி வாளன்றன் சொல்வழி முன்னின்
றழிவழி வார்நெறி நாடநில் லாரே`,
    transliteration: `vaḻiyaraṇ ṭukkumōr vittatu vāṉa
paḻiyatu pārmicai vāḻtal uṟutal
cuḻiyaṟi vāḷaṉṟaṉ colvaḻi muṉṉiṉ
ṟaḻivaḻi vārneṟi nāṭanil lārē`,
    english: `1541: The End of Seeking
To be born and to live again and again here below,
Verily is the curse of all;
It is the seed of Karma twain;
If you but listen to Him that knows
The origin of swirl that is birth and death,
No more shall you seek
The ways of the perishing men.`,
    elaborationEnglish: `The cycle of births is the bane of the soul and the seed of the coupled karma. So, listen to Him, who knows the origin of this cycle`,
    elaborationTamil: `இறைவனை அடையும் முக்திக்கு வழி என்று யோக மார்க்கமும் ஞான மார்க்கமும் அறிந்து செல்பவர்களுக்கும் இறைவனை அடைவதற்கான வழி எது என்று அறியாமலேயே பக்தி மார்க்கத்திலும் கர்ம மார்க்கத்திலும் செல்பவர்கள் ஆகிய இரண்டு வழியில் செல்பவர்களுக்கும் ஒரே மூல விதையாக அவர்களுக்குள் இருப்பதாகிய சுழுமுனை நாடி எனும் நடு நாடியின் மூலம் குண்டலினி சக்தியை ஏற்றி சென்று இந்த உலகத்தின் மேல் வாழ்வதும் கர்மங்களை அனுபவிப்பதும் ஆகிய இரண்டிலிருந்தும் விடுதலை பெறுவதற்கு சுழுமுனை நாடியின் உச்சித் துளையில் வீற்றிருக்கும் அனைத்தும் அறிந்தவனாகிய இறைவனே குருவாக இருந்து சொல்லி அருளுகின்ற வழியை முயற்சி செய்து விட்டுவிடாமல் கடைபிடித்து அதன் மூலம் கர்மங்கள் அனைத்தும் அழிந்து போவதை அறிந்து கொண்டவர்களின் வழி முறையை தேடி அடைவதற்கு முயற்சி செய்யாமலேயே ஆசைகளின் வழியே சென்று கொண்டு இருக்கின்றார்கள்.`,
  },
  {
    id: 1543, tantraId: 5, verseNumber: 1542,
    tamil: `மாதவர் எல்லாம் மாதேவன் பிரான்என்பர்
நாதம தாக அறியப்படுநந்தி
பேதஞ்செய் யாதே பிரான்என்று கைதொழில்
ஆதியும் அந்நெறி யாகிநின் றானே`,
    transliteration: `mātavar ellām mātēvaṉ pirāṉeṉpar
nātama tāka aṟiyappaṭunanti
pētañcey yātē pirāṉeṉṟu kaitoḻil
ātiyum anneṟi yākiniṉ ṟāṉē`,
    english: `1542: Lord and Nandi are One
All the holy ones hail Him as Great God, the Supreme Lord,
He that is Nada and bears the name Nandi;
You too shall make no distinction,
But in prayer lift your hands to Him as Being Supreme;
And the Primal One shall as such reveal Himself.`,
    elaborationEnglish: `Mantras 1542 & 1543

Little is the distinction between the Supreme Lord and holy Nandi. Hara, the Holy Father, is immanent in the hearts of men. Alienation from Him makes Him incognizable by jiva.`,
    elaborationTamil: `மாபெரும் தவங்களை செய்தவர்கள் அனைவரும் மாபெரும் தேவர்களுக்கெல்லாம் தலைவன் என்று தமக்குள் உணர்ந்த இறைவனை கூறுவார்கள். அந்த இறைவனை சாதகர்கள் தமக்குள் நாத வடிவமாக ஆகி அறியப்படுகின்ற நந்தி எனும் பெயரால் குருநாதனாக இருந்து வழி காட்டும் போது அவனை வேறு யாராகவும் பிரித்து எண்ணிப் பார்க்காமல் எமது தலைவன் இவனே என்று எண்ணிக் கொண்டு தம்மால் இயன்ற வழியில் அவனை அடைவதற்கு முயற்சி செய்தால் ஆதிப் பரம் பொருளாக இருக்கின்ற அந்த இறைவனும் தாங்கள் முயன்ற அந்த வழியாகவே ஆகி நிற்கின்றான்.`,
  },
  {
    id: 1544, tantraId: 5, verseNumber: 1543,
    tamil: `அரநெறி யப்பனை யாதிப் பிரானை
உரநெறி யாகி யுளம்புகுந் தானைப்
பரநெறி தேடிய பத்தர்கள் சித்தம்
பரனெறி யாவிடிற் பல்வகைத் தூரமே`,
    transliteration: `araneṟi yappaṉai yātip pirāṉai
uraneṟi yāki yuḷampukun tāṉaip
paraneṟi tēṭiya pattarkaḷ cittam
paraṉeṟi yāviṭiṟ palvakait tūramē`,
    english: `1543: God is Within You; and Yet Far Away
He is Hara, Holy Father, Primal Lord
As implacable Truth He entered heart;
But if hearts of devotees sought alien paths
They know Him not;
Then is He far, far away.`,
    elaborationTamil: `தங்களை காத்து அருளுகின்ற வழி முறையில் அப்பனாகவும் ஆதிப் பரம்பொருளாகவும் அனைத்திற்கும் தலைவனாகவும் இருக்கின்ற இறைவனே தங்களுக்கு உத்வேகத்தை கொடுத்து முயற்சி செய்ய வைக்கின்ற வழி முறைகளாகவே ஆகி வந்து தங்களின் உள்ளத்திற்குள் புகுந்து வீற்றிருப்பான். பரம் பொருளை அடைகின்ற வழி முறைகளை தேடி அலைகின்ற பக்தர்கள் தங்களின் எண்ணத்தினால் அந்தப் பரம் பொருளை அறிந்து கொள்ளாமல் போய் விட்டால் இறைவனும் அவர்களால் நெருங்க முடியாத அளவிற்கு தூரமாகவே இருப்பான்.`,
  },
  {
    id: 1545, tantraId: 5, verseNumber: 1544,
    tamil: `பரிசறி வானவன் பண்பன் பகலோன்
பெரிசறி வானவர் பேற்றில் திகழுந்
துரிசற நீநினை தூய்மணி வண்ணன்
அரிதவன் வைத்த அறநெறி தானே`,
    transliteration: `paricaṟi vāṉavaṉ paṇpaṉ pakalōṉ
pericaṟi vāṉavar pēṟṟil tikaḻun
turicaṟa nīniṉai tūymaṇi vaṇṇaṉ
aritavaṉ vaitta aṟaneṟi tāṉē`,
    english: `1544: Precious is Hara's Path
The Heavenly Lord, He knows our goal
He is tender hearted;
He is the Effulgent Sun that guides the destiny
Of Heavenly Beings of wisdom great;
Do think of Him in thought unsullied;
He is of crystal pure hue;
Precious the path of Virtue
He for us has laid.`,
    elaborationEnglish: `Mantras 1544 - 1546

God, the tender-hearted, is aware of our ultimate goal. He is the Effulgent Sun who designs our destiny. Precious and crystal pure becomes Hara’s path in intense meditation. Fidelity to God, who is far above all the religions, transcends the fleshy imperfections. True faith leads to the destined goal; adverse ones grant not His Grace.`,
    elaborationTamil: `கிடைப்பதற்கு மேலான பரிசு அவனே என்று அறிந்து கொண்ட தேவர்களுக்கு பெருங் கருணையோடு அருளுபவனும் பிரகாசமான சூரியனைப் போல் வெளிச்சத்தை கொடுத்து வழிகாட்டுபவனும் அடையக் கூடிய அனைத்தையும் விட பெரியதானவன் அவனே என்று அறிந்து கொண்ட தேவர்கள் அழைக்கின்ற பலவிதமான பெயர்களிலும் அப்படியே திகழ்பவனும் ஆகிய இறைவனை ஒரு குற்றமும் இல்லாமல் சாதகர்கள் நினைத்து வழிபட்டால் தூய்மையான மாணிக்கத்தில் நுழைகின்ற வெளிச்சம் அப்படியே எதிரொலிப்பது போல அவர்களின் எண்ணங்களுக்கு ஏற்ற தன்மையைக் கொடுத்து வழி காட்டி அருளுகின்றான். சாதகர்களை காத்து அருளுகின்ற இறைவனை அடைகின்ற வழி முறைகளே கிடைப்பதற்கு மிகவும் அரியதாக அவன் வகுத்து கொடுத்த அருளிய அந்த வழி முறைகள் ஆகும்.`,
  },
  {
    id: 1546, tantraId: 5, verseNumber: 1545,
    tamil: `ஆன சமயம் அதுஇது நன்றெனும்
மாய மனிதர் மயக்க மதுவொழி
கானங் கடந்த கடவுளை நாடுமின்
ஊனங் கடந்த வுருவது வாமே`,
    transliteration: `āṉa camayam atuitu naṉṟeṉum
māya maṉitar mayakka matuvoḻi
kāṉaṅ kaṭanta kaṭavuḷai nāṭumiṉ
ūṉaṅ kaṭanta vuruvatu vāmē`,
    english: `1545: God is Beyond All Religions
This the right path, that the right path
Be not tossed in such frail human doubts;
Seek the Being that is beyond wilderness of doubts
His is the Form that transcends fleshly imperfections.`,
    elaborationTamil: `பலரால் சொல்லப்படுவதான சமயங்களில் அதுவும் இதுவும் நல்லது என்று பல விதமான சமயங்களைப் பற்றி மற்றவர்களை ஏமாற்றி பிழைக்கின்ற மனிதர்கள் தங்களை மயக்கி விட முயற்சி செய்வார்கள். அதில் சென்று மயங்குவதை ஒழித்து விட்டு நாதங்களை கடந்து நிற்கின்ற இறைவனை தேடுங்கள். அவ்வாறு தேடினால் அழிவை கடந்து நிற்கின்ற என்றும் அழியாத உருவமாகிய இறைவனை காணலாம்.`,
  },
  {
    id: 1547, tantraId: 5, verseNumber: 1546,
    tamil: `அந்நெறி நாடி அமரரு முனிவருஞ்
செந்நெறி கண்டார் சிவனெனப் பெற்றார்பின்
முன்னெறி நாடி முதல்வன் அருளிலார்
சென்னெறி செல்லார் திகைக்கின்ற வாறே`,
    transliteration: `anneṟi nāṭi amararu muṉivaruñ
cenneṟi kaṇṭār civaṉeṉap peṟṟārpiṉ
muṉṉeṟi nāṭi mutalvaṉ aruḷilār
ceṉṉeṟi cellār tikaikkiṉṟa vāṟē`,
    english: `1546: True and False Faiths
That Path they took
The immortal Devas and the saintly tapasvins;
And so reached Goal True
And merged in one with Siva;
But they that followed froward faiths
Received not His grace;
They lost their way,
And forever wander.`,
    elaborationTamil: `இறைவனை அடைகின்ற வழி முறையை தேடி அமரர்களும் முனிவர்களும் தாங்கள் செல்ல வேண்டிய வழி முறையை கண்டு கொண்டு அதிலேயே சிறிதும் மாறாமல் சென்று சிவம் என்கின்ற பரம் பொருளை பெற்று அடைந்தார்கள். ஆனால் அவர்கள் சென்ற வழி முறையை அறியாத மற்றவர்களோ தமக்கு பின்னாலும் முன்னாலும் இருக்கின்ற வழி முறைகள் என்று பலவாறாக தேடி அலைந்து எந்த வழியையும் நிலையாக கடை பிடிக்காததால் அனைத்திற்கும் முதல்வனாகிய இறைவனின் திருவருளை இல்லாதவர்களாக அவர்கள் ஆகி விடுகிறார்கள். அமரர்களும் முனிவர்களும் சென்று அடைந்த வழி முறையில் செல்லாமல் எந்த வழியில் சென்று அடைவது என்று அறியாத மாயையில் திகைத்துக் கொண்டே அலைகின்றார்கள்.`,
  },
  {
    id: 1548, tantraId: 5, verseNumber: 1547,
    tamil: `உறுமா றறிவதும் உள்நின்ற சோதி
பெறுமா றறியிற் பிணக்கொன்றும் இல்லை
அறுமா றதுவான வங்கியு ளாங்கே
இறுமா றறிகிலர் ஏழைகள் தாமே`,
    transliteration: `uṟumā ṟaṟivatum uḷniṉṟa cōti
peṟumā ṟaṟiyiṟ piṇakkoṉṟum illai
aṟumā ṟatuvāṉa vaṅkiyu ḷāṅkē
iṟumā ṟaṟikilar ēḻaikaḷ tāmē`,
    english: `1547: Definition of True Path
He is Light within you;
To know how to reach Him
Is True Path of Becoming;
If you know thus,
You know contradiction none;
That is Path Finite, your Goal's End;
They are but folks poor in spirit
That know not merging in Light Divine.`,
    elaborationEnglish: `Mantras 1547 & 1549

Apprehension of the light within is the true path of becoming. That is the goal which is free from contradictions. Worldly paths are nothing but a mirage. So, give up the sorrowful path of whirling karma and crass evil; surely you will worship at the Lord's Feet. The true path results in the consummation of holiness. Journey forward, straight inside, and the presence of the Lord will be with you forever.`,
    elaborationTamil: `இறைவனை அடைகின்ற வழி முறையை அறிந்து கொள்வதும் அதன் மூலம் தமக்கு உள்ளே நிற்கின்ற ஜோதியாகிய இறைவனை பெறுகின்ற வழி முறையை அறிந்து கொண்டால் குழப்பமானது என்று ஒன்றும் இல்லாமல் போய்விடும். அப்போது இறைவனை அடைவதற்கு தடையாக இருக்கின்ற அனைத்தையும் அறுக்கின்ற வழியாக அதுவே ஆகிவிடும். இதை கடை பிடித்து நன்மை செய்கின்ற ஜோதியாக உள்ளே இருக்கின்ற இறைவனை அடைந்து தான் எனும் அகங்காரத்தை நீக்குகின்ற வழி முறையை அறியாதவர்கள் மாயையில் சிக்கிக் கொண்டு இறைவனின் அருளைப் பெறாத ஏழைகளாகவே இருக்கின்றார்கள்.`,
  },
  {
    id: 1549, tantraId: 5, verseNumber: 1548,
    tamil: `வழிநடக் கும்பரி சொன்றுண்டு வையங்
கழிநடக் குண்டவர் கற்பனை கேட்பர்
சுழிநடக் குந்துய ரம்மது நீக்கிப்
பழிநடப் பார்க்குப் பரவலு மாமே`,
    transliteration: `vaḻinaṭak kumpari coṉṟuṇṭu vaiyaṅ
kaḻinaṭak kuṇṭavar kaṟpaṉai kēṭpar
cuḻinaṭak kuntuya rammatu nīkkip
paḻinaṭap pārkkup paravalu māmē`,
    english: `1548: Worldly Path is not True Path
There is a True Path for the Journey;
They that follow the swampy paths worldly
See but the mirage;
They that avoid the sorrowful path of swirling Karma
Cross evil safe;
And shall sure worship at Lord's Feet.`,
    elaborationTamil: `இறைவனை அடைகின்ற வழியில் நடக்கும் போது கிடைக்கின்ற பலன் ஒன்று இருக்கின்றது. இந்த உலகத்தில் தனது உடலுக்கு உண்டான வினையின் போக்கில் செல்பவர்கள் மற்றவர்கள் மாயையால் தமக்கு உண்மை என்று நம்பி கூறுகின்ற கற்பனையான விஷயங்களை நம்பி கேட்கிறார்கள். இவர்கள் தங்களின் வினைகளின் வழியாகவே மற்றவர்கள் சொல்லுவதை உண்மை என்று நம்பி செல்லுவதால் பல விதமான துன்பங்களை அனுபவிக்கின்றனர். இதற்கு காரணமாக இருக்கின்ற வினைகளை நீக்குவதற்கு உலகத்தில் உள்ளவர்கள் தம் மீது எவ்வளவு பழியை சுமத்தினாலும் அதனால் கவலை படாமல் இறைவனை அடைகின்ற வழியை விட்டுவிடாமல் நடப்பவர்களுக்கு இறைவனை அடைவதற்கான அனைத்து விதமான வழிகளும் அந்த வழிகளில் செல்வதற்கான பக்குவங்களும் கிடைக்கும்.`,
  },
  {
    id: 1550, tantraId: 5, verseNumber: 1549,
    tamil: `வழிசென்ற மாதவம் வைகின்ற போது
பழிசெல்லும் வல்வினைப் பற்றறுத் தாங்கே
வழிசெல்லும் வல்வினை யாம்திறம் விட்டிட்
டுழிசெல்லில் உம்பர் தலைவன்முன் னாமே`,
    transliteration: `vaḻiceṉṟa mātavam vaikiṉṟa pōtu
paḻicellum valviṉaip paṟṟaṟut tāṅkē
vaḻicellum valviṉai yāmtiṟam viṭṭiṭ
ṭuḻicellil umpar talaivaṉmuṉ ṉāmē`,
    english: `1549: True Path Leads Straight to Lord's Presence
Walking in the True Path
Your holiness consummates;
The host of thine Karmaic deeds scatters
And they flee away;
Leave you the tortuous path
Of the Karmaic ridden men of world
Onward you journey, straight inside;
Thou shall, for certain, stand
In the Presence of the Lord of Heavenly Beings.`,
    elaborationTamil: `இறைவனை அடைகின்ற வழியில் ஆசைகள் இல்லாமல் சென்று புரிகின்ற மாபெரும் தவமானது அதன் பயனால் நிலை பெற்று நிற்கின்ற போது, ஞானிகள் பழிக்கின்ற உலக வழிகளில் செல்லும் போது வலிமையான வினைகளினால் கட்டி இருக்கின்ற பற்றை அறுத்து விட்டு, தாம் இருக்கின்ற இடத்திலேயே இறைவனை நோக்கிய வழியில் செல்லுகின்றவர்கள், வலிமையான வினைகளில் ஆட்பட்டு வினை வழியே செல்லுகின்ற உலகத்தவர்களின் உறுதியான பந்த பாசங்களை விட்டு விட்டு, இறைவன் இருக்கின்ற இடம் நோக்கி அவனை அடைகின்ற வழியில் சென்றால், தேவர்களுக்கு எல்லாம் தலைவனாகிய இறைவனின் முன்பு சென்று நிற்பார்கள்.`,
  },
  {
    id: 1551, tantraId: 5, verseNumber: 1550,
    tamil: `இமையங்க ளாய்நின்ற தேவர்கள் ஆறு
சமையங்கள் பெற்றனர் சாத்திரம் ஓதி
யமையறிந் தோமென்ப ராதிப் பிரானுங்
கமையறிந் தாருட் கலந்துநின் றானே`,
    transliteration: `imaiyaṅka ḷāyniṉṟa tēvarkaḷ āṟu
camaiyaṅkaḷ peṟṟaṉar cāttiram ōti
yamaiyaṟin tōmeṉpa rātip pirāṉuṅ
kamaiyaṟin tāruṭ kalantuniṉ ṟāṉē`,
    english: `1550: Who Attained Divine Tranquility
The Heavenly Beings, immortal as the mountain Himalayas,
Received the Darshanas that are Six;
"We learned them all and attained the Other World"
-Thus quote they;
But, in sooth,
The Primal Lord is in intimacy within
Of those that have Divine Tranquility attained.`,
    elaborationEnglish: `Mantras 1550 & 1551

The immortal heavenly beings having received the six darshans believe that they have attained liberation, but true liberation is within and belongs to those who have attained divine tranquility. Humble yourself at the Feet of the Lord, and you become one with Siva. Unquenchable desires lead but to eternal sorrow.`,
    elaborationTamil: `இமயத்தை போல உயர்ந்த நிலையில் நிற்கின்ற தேவர்கள் இறைவனை அடைவதற்கான ஆறு விதமான வழி முறைகளை இறைவனிடமிருந்து பெற்றனர். அவர்கள் பெற்ற வழி முறைகளின் படி சாஸ்திரங்களை ஓதுவதின் மூலமே இறைவனை அடைவதற்கான வழியை அறிந்து கொண்டோம் என்று அவர்கள் கூறுகின்றார்கள். அனைத்திற்கும் ஆதியாகவும் தலைவனாகவும் இருக்கின்ற இறைவனை எந்தவிதமான எண்ணங்களும் இல்லாத பேரமைதியில் இருந்து அறிந்து கொண்டவர்களின் உள்ளுக்குள் ஒன்றாக கலந்து நிற்கின்றான் இறைவன். கருத்து: ஆறு சமயங்கள் சொல்லுகின்ற வழி முறையில் சாஸ்திரங்களை ஓதுவதன் மூலம் மட்டுமே இறைவனை அடைவதற்கான வழியை அறிந்து கொண்டோம் என்று மேன்மையான நிலையில் இருக்கின்ற தேவர்கள் சொல்லுவார்கள். ஆனால், எந்த சாஸ்திரத்தையும் ஓதாமல் இருந்தாலும் மனதில் அமைதியுடன் எண்ணங்கள் அற்ற நிலையில் ஒருவர் இருந்தாலே அவர்களால் தமக்குள்ளேயே கலந்து நிற்கின்ற இறைவனை அறிந்து கொள்ள முடியும். இறைவனை அடையும் முறையான ஆறு வித வழிகள்: தியானம் – மந்திரத்தை மனதிற்குள் தியானித்தல் செபம் – அக வழிபாடு மூலம் செபித்தல் பூஜை – புற வழிபாடு மூலம் செபித்தல் சக்கரம் – சக்கரங்கள் அமைத்து செபித்தல் ஞானம் – மந்திரத்தின் பொருளை தேடி ஆராய்ந்து அறிந்து கொள்ளுதல் புத்தி – மந்திரத்தின் ஒவ்வொரு எழுத்தையும் ஆராய்ந்து அறிந்து கொள்ளுதல் குறிப்பு: இந்த பாடலின் தலைப்பு நிராசாரம் என்றும் நிராகாரம் என்றும் பல புத்தகங்களில் கொடுக்கப் பட்டிருக்கிறது. ஆனால் ஓலை சுவடியில் நிராதாரம் என்று கொடுக்கப் பட்டு இருக்கிறது மேலும் இந்த தலைப்பில் உள்ள பாடல் #1556 இல் மூன்றாவது அடியில் வரும் “சார் உறார்” எனும் பதத்தை ஒத்து இருப்பதாலும் இதனை ஆதாரமாகக் கொண்டு நிராதாரம் என்ற தலைப்பு எடுத்துக் கொள்ளப் பட்டது.`,
  },
  {
    id: 1552, tantraId: 5, verseNumber: 1551,
    tamil: `பாங்கமர் கொன்றைப் படர்சடை யானடி
தாங்கு மனிதர் தரணியில் நேரொப்பர்
நீங்கிய வண்ணம் நினைவுசெய் யாதவர்
ஏங்கி உலகில் இருந்தழு வாரே`,
    transliteration: `pāṅkamar koṉṟaip paṭarcaṭai yāṉaṭi
tāṅku maṉitar taraṇiyil nēroppar
nīṅkiya vaṇṇam niṉaivucey yātavar
ēṅki ulakil iruntaḻu vārē`,
    english: `1551: Worship Siva and Siva Become
They who bow their head at the Feet of Lord
Of spreading matted locks and Konrai bloom bedecked,
They shall, like unto Him, become;
But they that yearn not for Him in constant eagerness
Shall be in sorrow immersed,
Sighing eternal here below.`,
    elaborationTamil: `அழகாக அமைக்கப் பட்ட கொன்றை மலர்கள் படர்ந்து இருக்கின்ற திருச் சடையைத் தரித்து இருக்கின்ற இறைவனின் திருவடிகளை எப்போதும் நினைக்கின்ற எண்ணங்களை தமது நெஞ்சத்தில் தாங்கி இருக்கின்ற மனிதர்கள் இந்த உலகத்திலேயே இறைவனின் திருவடிகளுக்கு இணையானவர்களாக இருப்பார்கள். அவ்வாறு இல்லாமல் இறைவன் வேறு தாம் வேறு என்று நினைத்துக் கொண்டு இறைவனை எப்பொழுதும் நினைக்காமல் இருப்பவர்கள் தாம் விரும்பிய எதுவும் கிடைக்காமல் ஏக்கத்திலேயே இந்த உலகத்தில் இருந்து எப்போது இந்த பிறவி முடியும் என்று துன்பப் படுவார்கள்.`,
  },
  {
    id: 1553, tantraId: 5, verseNumber: 1552,
    tamil: `இருந்தழு வாரும் இயல்புகெ ட்டாரும்
அருந்தவ மேற்கொண்டங் கண்ணலை எண்ணில்
வருந்தா வகைசெய்து வானவர் கோனும்
பெருந்தன்மை நல்கும் பிறப்பில்லை தானே`,
    transliteration: `iruntaḻu vārum iyalpuke ṭṭārum
aruntava mēṟkoṇṭaṅ kaṇṇalai eṇṇil
varuntā vakaiceytu vāṉavar kōṉum
peruntaṉmai nalkum piṟappillai tāṉē`,
    english: `1552: Worship Brings Immortal Life
Despair not!
You that thus sit and bewail
And you that have lost your better nature!
Seek Lord in penance true,
The Heavens' Lord shall wipe your tears away,
And grant you Greatness;
And you shall then know births no more.`,
    elaborationEnglish: `Mantras 1552 & 1553

Neither despair nor wail. That will affect your better nature. Instead, perform tapas and atonement. The Lord will wipe your tears and grant you greatness. Life goes in vain for those who seek Him not. Befriend God by seeking Him. He will shower His manifold Grace and countless blessings.`,
    elaborationTamil: `பாடல் #1551 இல் உள்ளபடி பிறவி எனும் துன்பத்தில் இருந்து அழுகின்றவர்களும், மனித இனத்திற்கான ஒழுக்கங்கள் கெட்டவர்களும், செய்வதற்கு அரியதான தவங்களை செய்வதையே குறிக்கோளாக மேற் கொண்டு அந்த தவங்களை செய்யும் போதும் தலைவனாகவும் அடியவனாகவும் இருக்கின்ற இறைவனை எண்ணிக் கொண்டே இருந்தால், அவர்களின் துன்பம் நீங்கி இனி எப்போதும் வருந்தாமல் இருப்பதற்கான வழி முறையை செய்து கொடுத்து வானவர்களின் அரசனாகியவன் மாபெரும் கருணையோடு அருளுவான் பிறப்பு இல்லாதவனாகிய இறைவன். கருத்து: பிறவி எனும் துன்பத்தில் சிக்கிக் கொண்டு தவிப்பவர்கள் இறைவனை நினைத்து தவமிருந்தால் இறைவன் மாபெரும் கருணையோடு அவர்களுக்கு வழி காட்டி பிறவி இல்லாத நிலையை கொடுத்து அருளுவான்.`,
  },
  {
    id: 1554, tantraId: 5, verseNumber: 1553,
    tamil: `தூரறி வாளர் துணைவர் நினைப்பிலர்
பாரறி வாளர் படுபயன் றானுண்பர்
காரறி வாளர் கலந்து பிறப்பர்கள்
நீரறி வார்நெடு மாமுகி லாமே`,
    transliteration: `tūraṟi vāḷar tuṇaivar niṉaippilar
pāraṟi vāḷar paṭupayaṉ ṟāṉuṇpar
kāraṟi vāḷar kalantu piṟapparkaḷ
nīraṟi vārneṭu māmuki lāmē`,
    english: `1553: Lord is Unto Gentle Rain
Who seeks Finite Truth
They His friend are;
Who does not seek Him
They but know the Worldly Men's Misery-Way,
Enveloped in darkness of bondage
In vain shall they be born again and again;
Who seeks Path True
To them, the Lord is unto richly laden clouds
That drops gentle rain of Heavenly Grace.`,
    elaborationTamil: `மும் மலங்களை மட்டுமே அறிந்து கொண்டவர்கள் தன்னுடன் துணையாகவே நிற்கின்ற இறைவனை பற்றிய நினைவே இல்லாதவர்களாக இருக்கின்றார்கள். உலக அறிவை மட்டுமே அறிந்து கொண்டவர்கள் அதற்குள்ளேயே விழுந்து கிடந்து அதன் பயன்களை தானே அனுபவித்துக் கொண்டு இருப்பார்கள். மாயை எனும் இருளால் அறிந்து கொள்ளக் கூடியதை மட்டுமே அறிந்து கொண்டவர்கள் வினைகளோடு கலந்து மீண்டும் மீண்டும் பிறவி எடுப்பார்கள். இறைவன் எனும் மேகத்தில் இருந்து ஆன்மா எனும் நீராக தாம் வந்து இருக்கின்றோம் என்பதை உணர்ந்து கொண்டவர்களுக்கு நீண்ட மாபெரும் மேகத்தை போல அருளை மழையாகப் பொழிபவனாக இறைவன் இருக்கின்றான்.`,
  },
  {
    id: 1555, tantraId: 5, verseNumber: 1554,
    tamil: `அறிவுடன் கூடி அழைத்தோர் தோணி
பறியுடன் பாரம் பழம்பதி சிந்துங்
குறியது கண்டுங் கொடுவினை யாளர்
செறிய நினைக்கிலர் சேவடி தானே`,
    transliteration: `aṟivuṭaṉ kūṭi aḻaittōr tōṇi
paṟiyuṭaṉ pāram paḻampati cintuṅ
kuṟiyatu kaṇṭuṅ koṭuviṉai yāḷar
ceṟiya niṉaikkilar cēvaṭi tāṉē`,
    english: `1554: Lord Guides the Boat of Life
The Boat of Life
By Divine Wisdom guided
Discharges quick its cargo
At the City Ancient;
Having seen that unerring prospect
These wretched men of ignoble deeds
Think not of His Holy Feet,
In devotion replete.`,
    elaborationEnglish: `Mantras 1554 & 1555

In spite of having realised that God guides the 'boat of life', wretched men of ignoble deeds do not think of Him in intense devotion. They are witless fools who laugh at the fact that Siva, the Eternal Being, is immanent within. If they but pray to Him, they will meet the Supreme One.`,
    elaborationTamil: `இறைவனிடமிருந்தே தாம் வந்திருக்கின்றோம் என்பதை அறிந்தவர்களின் அறிவோடு கூடி அழைக்கின்ற பழமையான தலைவனாகிய இறைவன் ஒரு ஓடக்காரணும் படகுமாக வந்து உடலுடன் சேர்ந்து பாரமாக இருக்கின்ற பற்றுக்களையும் கர்மங்களையும் அழித்து பிறவி எனும் பெரும் கடலை கடக்க உதவுகின்றான். இந்த வழி முறையை தெரிந்து கொண்டும் கொடுமையான வினைகளைக் கொண்டு இருப்பதால் அதை உணராமல் இருப்பவர்கள் பிறவியை கடப்பதற்காக இறைவனின் செம்மையான திருவடிகளை நினைக்காமல் இருக்கின்றார்கள்.`,
  },
  {
    id: 1556, tantraId: 5, verseNumber: 1555,
    tamil: `மன்னும் ஒருவன் மருவு மனோமயன்
என்னின் மனிதர் இகழ்வரிவ் வேழைகள்
துன்னி மனமே தொழுமின் துணையிலி
தன்னையும் அங்கே தலைப்பட லாமே`,
    transliteration: `maṉṉum oruvaṉ maruvu maṉōmayaṉ
eṉṉiṉ maṉitar ikaḻvariv vēḻaikaḷ
tuṉṉi maṉamē toḻumiṉ tuṇaiyili
taṉṉaiyum aṅkē talaippaṭa lāmē`,
    english: `1555: Lord is Within You
The Only Being, the Eternal Being
Within you He dwells;
When you say so,
These ignorant men laugh low;
Poor folk! if they but seek Him in prayer within
Then shall they meet Him-the Peerless One.`,
    elaborationEnglish: `Poor folk! if they but seek Him in prayer within’ Then shall they meet Him — the Peerless One.`,
    elaborationTamil: `எப்போதும் நிலையாக இருக்கின்ற ஒருவனாகிய இறைவன் நினைக்கும் வடிவமாகவே கலந்து மனதின் தன்மைக்கு ஏற்றவாறு இருக்கின்றான். இப்படி இறைவன் இருப்பதை எடுத்துக் கூறினால் அறியாமையில் மூழ்கி அறிவுக் குறைபாடினால் ஏழைகளாக இருக்கின்ற மனிதர்கள் இகழ்ந்து சிரிப்பார்கள். இவ்வாறு எண்ணத்திற்கு ஏற்றபடி தம்மோடு பொருந்தி இருக்கின்ற இறைவனை தமது மனதினால் தொழுது வந்தால் தனக்கு சரிசமமாக எதுவும் இல்லாதவனாகிய இறைவன் தங்களின் மனதிற்குள் வெளிப்பட்டு அவனை உணர்வதற்கான வழியில் செல்ல வைப்பான்.`,
  },
  {
    id: 1557, tantraId: 5, verseNumber: 1556,
    tamil: `ஓங்காரத் துள்ளொளி உள்ளே உதயமுற்
றாங்கார மற்ற அனுபவங் கைகூடார்
சாங்கால முன்னார் பிறவாமை சார்வுறார்
நீங்காச் சமயத்துள் நின்றொழிந் தார்களே`,
    transliteration: `ōṅkārat tuḷḷoḷi uḷḷē utayamuṟ
ṟāṅkāra maṟṟa aṉupavaṅ kaikūṭār
cāṅkāla muṉṉār piṟavāmai cārvuṟār
nīṅkāc camayattuḷ niṉṟoḻin tārkaḷē`,
    english: `1556: Who Pursued False Faiths
They wake not to Inner Light of Aum within;
And joy not in ego-effaced bliss ensuing
They wot not of approaching death,
They seek not end of recurring birth,
Lo! they pursued the unending path of contending faiths,
And stood forlorn, for ever lost in faith false.`,
    elaborationEnglish: `They who pursue false faiths do not wake to the inner light of Aum, that is within themselves. These faiths do not reveal the bliss that ensues when the’ ego is totally annihilated. Indifferent both to the of approaching death and recurring birth, alas, they stand in forlom hope.`,
    elaborationTamil: `பிரணவ மந்திரமான ஓங்காரத்தின் சத்தத்திற்கு உள்ளே இருக்கின்ற ஒளி வடிவான இறைவனே சாதகருக்குள்ளும் ஜோதியாக வெளிப்படுவதை மனதை ஒரு முகப்படுத்தி உணர்வதன் மூலம் அகங்காரத்தை அழித்து இறைவனும் தானும் வேறு வேறு இல்லை எனும் நிலையை பெற்று அடைய முடியாதவர்கள் தாம் இறக்கும் காலம் ஒன்று வரும் என்பதை நினைக்காமல் இருக்கின்றார்கள். ஆதலால், இனி எப்போதும் பிறக்காமல் இருக்கின்ற பெரும் நிலையை சார்ந்து இருக்கின்ற வழி முறைகளில் செல்லாமல் எப்போதும் தாம் கடைபிடிக்கின்ற வழியே சிறந்தது என்று ஓயாமல் தங்களுக்குள் சண்டை போட்டுக் கொண்டு இருக்கின்ற சமயங்களின் கொள்கைகளின் வழியில் நின்று இறந்து அழிந்து போகின்றார்கள்.`,
  },
  {
    id: 1558, tantraId: 5, verseNumber: 1557,
    tamil: `இமையவர் தம்மையும் எம்மையும் முன்னம்
அமைய வகுத்தவன் ஆதி புராணன்
சமயங்க ளாறும்தன் றாளிணை நாட
அமையங் குழல்கின்ற ஆதிப் பிரானே`,
    transliteration: `imaiyavar tammaiyum emmaiyum muṉṉam
amaiya vakuttavaṉ āti purāṇaṉ
camayaṅka ḷāṟumtaṉ ṟāḷiṇai nāṭa
amaiyaṅ kuḻalkiṉṟa ātip pirāṉē`,
    english: `1557: Lord Pervades All Six Inner Faiths
He is the Ancient One,
He created the beings of earth and heaven,
In days of yore, in Order Divine;
The Six Faiths seek the Feet
But of the One Primal Peerless God;
And in them all He pervades
In measure appropriate.`,
    elaborationEnglish: `Mantras 1557 & 1558

The ancient Lord, the Creator of all worlds, pervades all the six inner faiths. The Lord is the 'great city' to which the six roads (six inner faiths) lead. They who stand in contention are similar to the dog that barks at its own echo from the hillside.`,
    elaborationTamil: `விண்ணுலக தேவர்கள் அனைவரையும் மண்ணுலக மனிதர்கள் அனைவரையும் ஆதி காலத்திலேயே அவரவர் வினைகளுக்கு ஏற்ப வகுத்து படைத்தவன் ஆதியாகவும் பழமையானவனாகவும் இருக்கின்ற இறைவன். அவனை அடைவதற்கான ஆறு விதமான வழி முறைகளையும் தனது திருவடிக்கு இணையான முக்தியை தமக்குள்ளேயே தேடி அடைவதற்காக அவரவர் தகுதிகளுக்கு ஏற்றபடி அமைத்துக் கொடுத்து அதை முறையாக கடைபிடிப்பவர்கள் பக்குவ நிலையை அடையும் போது அவர்களுக்குள் நெருப்பு வடிவமாக வந்து நிற்கின்றான் ஆதியிலிருந்தே அனைத்திற்கும் தலைவனாக இருக்கின்ற இறைவன்.`,
  },
  {
    id: 1559, tantraId: 5, verseNumber: 1558,
    tamil: `ஒன்றது பேரூர் வழியா றதற்கு
என்றது போல இருமுச் சமயமும்
நன்றிது தீதிது என்றுரை யாளர்கள்
குன்று குரைத்தெழு நாயையொத் தார்களே`,
    transliteration: `oṉṟatu pērūr vaḻiyā ṟataṟku
eṉṟatu pōla irumuc camayamum
naṉṟitu tītitu eṉṟurai yāḷarkaḷ
kuṉṟu kuraitteḻu nāyaiyot tārkaḷē`,
    english: `1558: All Faiths Lead but to Lord
One, the Great City,
Six, the roads that lead to it;
Thus are Faiths Six;
They that contend,
"This true; That false"
Are unto the dog that in ire barks
To its own echo at hilly side.`,
    elaborationTamil: `ஒன்றாக இருக்கின்ற மிகப் பெரும் ஊருக்கு செல்லுவதற்கு ஆறு விதமான வழிகள் இருக்கின்றது. அது போலவே ஆறு விதமான சமயங்களும் ஒரே பரம்பொருளாகிய இறைவனை அடைவதற்கான ஆறு விதமான வழி முறைகளையே சொல்லுகின்றன. ஆனால் இதை முழுவதுமாக உணர்ந்து கொள்ளாமல் நன்மையானது இந்த சமயம் தீமையானது இந்த சமயம் என்று பிரித்து பிரித்து வேறுபாடுள்ள கருத்துக்களை உரைத்து தாம் கூறுவதே உண்மை என்று மற்றவர்களை நம்ப வைக்க பிரச்சாரம் செய்கின்றவர்கள் மலையைப் பார்த்து குரைத்து குதிக்கின்ற நாயை போலவே இருக்கின்றார்கள்.`,
  },
  {
    id: 1560, tantraId: 5, verseNumber: 1559,
    tamil: `சைவப் பெருமைத் தனிநா யகன்தன்னை
உய்ய வுயிர்க்கின்ற ஒண்சுடர் நந்தியை
மெய்ய பெருமையர்க் கன்பனை இன்பஞ்செய்
வையத் தலைவனை வந்தடைந் துயமினே`,
    transliteration: `caivap perumait taṉinā yakaṉtaṉṉai
uyya vuyirkkiṉṟa oṇcuṭar nantiyai
meyya perumaiyark kaṉpaṉai iṉpañcey
vaiyat talaivaṉai vantaṭain tuyamiṉē`,
    english: `1559: Come, Stand Apart and Seek Lord
He is the incomparable Lord
Of the magnificient path of Saivam;
He is Nandi of Divine Lustre
That breaths the eternal life of Grace;
Beloved is He of the truly great;
The Lord of all universe, the source of all Joy;`,
    elaborationEnglish: `Mantras 1559 & 1560

He is the Peerless Lord of the munificent path of Saivam; the Nandi of Divine Lustre that grants an eternal life of Grace. He is the Lord of all universe, and the source of all joy. He laid the divine path that takes jiva to his eternal home. He is within you. Seek and realize Him.`,
    elaborationTamil: `சைவம் என்று அறியப்படுகின்ற இறைவனை அடைவதற்கான நெறிமுறைக்கு மிகப்பெரும் பெருமையாக இருக்கின்றவனும் தனக்கு சரிசமமாக வேறு யாரும் இல்லாத தலைவனாக இருக்கின்றவனும் உயிர்கள் அனைத்தும் தம்மை அடைவதற்காக அவற்றுக்குள் உணர்வாக கலந்து நின்று இயக்குகின்றவனும் அதற்கான ஞானத்தை தரும் ஜோதியாக இருந்து மாயையாகிய இருளை அகற்றுகின்ற குருநாதனாக இருக்கின்றவனும் தம்மை உண்மையாக அறிந்து கொண்ட பெருமை மிக்க அடியவர்களிடம் அன்பு செய்கின்ற அடியவனாக இருந்து பேரின்பத்தை கொடுக்கின்றவனும் உலகங்கள் அனைத்திற்கும் தலைவனாக இருக்கின்றவனும் ஆகிய இறைவனை நீங்களும் வந்து உங்களுக்குள் தேடி அடைந்து அவனை உண்மையாக உணர்ந்து மேன்மை பெறுங்கள்.`,
  },
  {
    id: 1561, tantraId: 5, verseNumber: 1560,
    tamil: `சிவனவன் வைத்ததோர் தெய்வ நெறியிற்
பவனவன் வைத்த பழிவழி நாடி
இவனவன் என்ப தறியவல் லார்கட்
கவனவ னங்குள தாங்கட னாமே`,
    transliteration: `civaṉavaṉ vaittatōr teyva neṟiyiṟ
pavaṉavaṉ vaitta paḻivaḻi nāṭi
ivaṉavaṉ eṉpa taṟiyaval lārkaṭ
kavaṉava ṉaṅkuḷa tāṅkaṭa ṉāmē`,
    english: `1560: "You Are He"-Is the Teaching of True Path
Siva laid the divine path ancient
That leads to the Home Eternal
Seek Him that way;
And know you are He
You shall duly find Him within yourself.`,
    elaborationTamil: `சிவப் பரம்பொருளாக இருக்கின்ற இறைவன் வைத்து அருளிய தெய்வத்தை அடைவதற்கான ஒரு நெறி முறையை கடைபிடித்து அந்த சிவப் பரம்பொருளே வைத்து அருளிய பழமையான வழியை தமக்குள்ளே தேடி அடைந்து அதன் மூலம் தமது ஆன்மாவாக இருப்பதும் அவனே என்பதை அறிந்து கொள்ள முடிந்தவர்களுக்கு, தாம் பார்க்கின்ற அனைத்திலும் அவனை காண்பவர்களுக்கு அவர்கள் பார்க்கின்ற அனைத்திலும் அதனதன் தன்மையிலேயே வந்து இருக்க வேண்டியது அந்த இறைவனின் கடமை ஆகும்.`,
  },
  {
    id: 1562, tantraId: 5, verseNumber: 1561,
    tamil: `ஆமா றுரைக்கும் அறுசம யாதிக்குப்
போமாறு தானில்லை புண்ணிய மல்லதங்
காமாம் வழியாக்கும் அவ்வே றுயிர்கட்கும்
போமா றவ்வாதாரப் பூங்கொடி யாளே`,
    transliteration: `āmā ṟuraikkum aṟucama yātikkup
pōmāṟu tāṉillai puṇṇiya mallataṅ
kāmām vaḻiyākkum avvē ṟuyirkaṭkum
pōmā ṟavvātārap pūṅkoṭi yāḷē`,
    english: `1561: The True Path is Through Kundalini
The Six Faiths that profess the means to Becoming
Are by themselves but blind alleys all;
No good comes by following them alone;
The true path of Becoming for all life to pursue
Is but the path of divine Kundalini Sakti,
The blossom-vine that through Six centers courses.`,
    elaborationEnglish: `The six faiths that proclaim the means to 'becoming' can do no good standing by themselves. Kundalini the blossom-vine that courses through the six chakras within is the pervasive force in them all.`,
    elaborationTamil: `அவரவர்களின் நிலைக்கு ஏற்றபடியே இறைவனை அடைவதற்கான வழியை எடுத்துக் கூறுகின்ற ஆறு விதமான சமயங்களுக்கும் ஆதிப் பரம்பொருளாகிய இறைவனிடம் போய் சேருகின்ற வழி புண்ணியத்தை தவிர வேறு ஒன்றும் இல்லை. ஆகவே புண்ணியத்தினால் இறைவனை அடைகின்ற வழியை உருவாக்கிக் கொடுத்து அதனால் பல வகையான உயிர்களுக்கும் இறைவனிடம் போய் சேருகின்ற வழியாக அவர்களுக்குள் இருக்கின்ற ஆறு ஆதார சக்கரங்களின் பூவிதழ்களை இணைக்கின்ற கொடியாக இருந்து ஏழாவது சக்கரமாக இருக்கின்ற இறைவனிடம் இணைப்பது இறைவியே ஆகும்.`,
  },
  {
    id: 1563, tantraId: 5, verseNumber: 1562,
    tamil: `அரன்நெறி யாவ தறிந்தேனும் நானுஞ்
சிலநெறி தேடித் திரிந்தஅந் நாளும்
உரநெறி யுள்ளக் கடல்கடந் தேறுந்
தரநெறி நின்ற தனிச்சுடர் தானே`,
    transliteration: `araṉneṟi yāva taṟintēṉum nāṉuñ
cilaneṟi tēṭit tirintaan nāḷum
uraneṟi yuḷḷak kaṭalkaṭan tēṟun
taraneṟi niṉṟa taṉiccuṭar tāṉē`,
    english: `1562: Lord Ever Guides
Now have I realized the Path of Hara;
In the past I sought Him in narrow paths
And strayed;
Lo! all the while He stood before me
Like a beacon light in firmament
Guiding my voyage
Across the sea of my Soul's longing.`,
    elaborationEnglish: `Mantras 1562 & 1563

Narrow and crooked is not the path to the Lord. All the while, He stands before you like a beacon light guiding the voyage across the sea of soul's longing. Seek the proven path of Siva that leads to Hara. It is the divine path that renowned souls have treaded through time.`,
    elaborationTamil: `அனைத்தையும் காத்து நிற்கின்ற இறைவனை அடைவதற்கான வழி முறைகளாக இருப்பவற்றை அறிந்து கொண்டேன் யானும். அந்த இறைவனை அடைவதற்கான வழி முறைகளை தேடி யான் திரிந்து கொண்டிருந்த முன்னொரு நாட்களில் எமக்குள் பல விதமான எண்ணங்கள் அலை மோதிக் கொண்டு இருக்கின்ற வழி முறைகளில் எமது உள்ளமாகிய பெரும் கடலை கடந்து மேல் நிலைக்கு செல்லுவதற்கு இறைவன் எமக்குத் தந்து அருளிய வழி முறைகளாக இருந்து வழி காட்டுவது தமக்கு சரிசமமாக எதுவும் இல்லாத பேரொளிச் சுடராக எமக்குள் இருக்கின்ற இறைவனே என்பதை அறிந்து கொண்டேன்.`,
  },
  {
    id: 1564, tantraId: 5, verseNumber: 1563,
    tamil: `தேர்ந்த அரனை அடைந்த சிவநெறி
பேர்ந்தவர் உன்னிப் பெயர்ந்த பெருவழி
ஆர்ந்தவர் அண்டத்துப் புக்க அருள்நெறி
போந்து புனைந்து புணர்நெறி யாமே`,
    transliteration: `tērnta araṉai aṭainta civaneṟi
pērntavar uṉṉip peyarnta peruvaḻi
ārntavar aṇṭattup pukka aruḷneṟi
pōntu puṉaintu puṇarneṟi yāmē`,
    english: `1563: Siva Path is Proven Path
The Path of Siva is the proven path
It led them to Hara;
It is the royal path that renowned Souls had walked;
The Path Divine
That took the devout to Cosmic Space;
That path, do seek,
Enter and persevere.`,
    elaborationTamil: `இறைவனை தமக்குள் உணர்ந்து தெளிவு பெற்றவர்கள் அடைந்த இறைவனை அடைவதற்கான வழி முறைகளை அவர்கள் அடைந்த படியே வெளிப்புறமாக தேடுவதை விட்டு விட்டு, மனதை ஒருநிலைப் படுத்தி தமக்குள் இறைவனையே நினைத்துக் கொண்டு, ஆசைகளையும் பற்றுக்களையும் விட்டு விட்டு, அடைகின்ற மிகப் பெரும் வழி முறைகளை நன்றாக ஆராய்ந்து அறிந்து கொண்டவர்கள், அண்ட சராசரங்களில் உள்ள அனைத்திலும் புகுந்து இருக்கின்ற இறையருளை அடைவதற்கான வழி முறைகள் தமக்குள்ளே இருப்பதை உணர்ந்து, அதற்குள் புகுந்து அதனோடு பின்னிப் பிணைந்து ஒன்றாக கலந்து இறைவனை அடைகின்ற வழி முறை இதுவே ஆகும்.`,
  },
  {
    id: 1565, tantraId: 5, verseNumber: 1564,
    tamil: `ஈரு மனத்தை யிரண்டற வீசுமின்
ஊருஞ் சகாரத்தை ஓதுமின் னோதியே
வாரு மரநெறி மன்னியே முன்னியத்
தூருஞ் சுடரொளி தோன்றலு மாமே`,
    transliteration: `īru maṉattai yiraṇṭaṟa vīcumiṉ
ūruñ cakārattai ōtumiṉ ṉōtiyē
vāru maraneṟi maṉṉiyē muṉṉiyat
tūruñ cuṭaroḷi tōṉṟalu māmē`,
    english: `1564: Vision of Light Effulgent in Saiva Path
Still your wandering thoughts;
Chant sacred syllable "Si"
And so persevere in Path of Hara
You shall envision Primal Light Effulgent.`,
    elaborationEnglish: `Mantras 1564-1566

Perseverence in the path of Hara enables the jiva to reach the effulgent Primal Light vision through the Saiva path. There is the Primal Lord, the tender shoot of Jnana Light with the Lady of Lightning Form, the blazing fire of Vedic brahmins and of the radiant souls who think of Him in devotion.`,
    elaborationTamil: `பொருளும் போகமும் வேண்டும் அருளும் ஞானமும் வேண்டும் என்று இரண்டு விதமாக அலைகின்ற மனதை அந்த இரண்டு ஆசைகளும் இல்லாமல் போகும் படி வெளியே எடுத்து வீசிவிடுங்கள். அப்போது கிடைக்கின்ற பேரமைதியான நிலையில் சாதகருக்குள் சக்தியின் ஒலி வடிவமாகிய ஒரு மந்திர எழுத்து தோன்றும். அப்படி தானாகவே தோன்றுகின்ற மந்திர எழுத்தை அசபையாக ஓதிக் கொண்டே இருங்கள். அவ்வாறு ஓதிக் கொண்டு இருப்பவரை அணைத்துக் காப்பாற்றுகின்ற வழி முறையில் மனதை நிலை பெற வைத்திருந்தால், தமக்குள்ளே உருவாகும் சுடரானது பேரொளியாக தோன்றுவதை நீங்கள் உணரலாம்.`,
  },
  {
    id: 1566, tantraId: 5, verseNumber: 1565,
    tamil: `மினற்குறி யாளனை வேதியர் வேதத்
தனற்குறி யாளனை ஆதிப் பிரான்தன்னை
நினைக்குறி யாளனை ஞானக் கொழுந்தி
னயக்குறி காணில் அரநெறி யாமே`,
    transliteration: `miṉaṟkuṟi yāḷaṉai vētiyar vētat
taṉaṟkuṟi yāḷaṉai ātip pirāṉtaṉṉai
niṉaikkuṟi yāḷaṉai ñāṉak koḻunti
ṉayakkuṟi kāṇil araneṟi yāmē`,
    english: `1565: Vision Through Saiva Path
He that belongs to the Lady of Lightning Form
He that belongs to the Vedic Fire of Brahmins
He that belongs to them that think of Him
He, the Primal Lord
He, the tender shoot of Jnana,
When you glimpse His loving signs,
Then have you walked in Path of Siva.`,
    elaborationTamil: `மின்னல் போன்ற ஒளியும் ஒலியும் சேர்ந்த வடிவமாக இருப்பவனை அந்தணர்கள் ஓதுகின்ற வேதத்தின் உட்பொருள் வடிவமாக இருப்பவனை ஆதியிலிருந்தே இருக்கின்ற தலைவனை அடியவர்கள் நினைக்கின்ற வடிவமாகவே வந்திருந்து அருளுபவனை ஞானத்தின் உச்சியான நிலையில் அன்பின் வடிவமாகவே கண்டு தரிசித்தால் அதுவே அவனை அடைவதற்கான வழி முறையாக ஆகி விடும். கருத்து: இறைவனை அடைவதற்கான ஆறு விதமான வழி முறைகளில் எந்த வழி முறையில் சென்றாலும் அனைத்திற்கும் பொதுவாக இருப்பது அன்பின் வழியாக இறைவனை அடைவதே ஆகும்.`,
  },
  {
    id: 1567, tantraId: 5, verseNumber: 1566,
    tamil: `ஆய்ந்துண ரார்களின் ஆன்மாச் சதுர்பல
வாய்ந்துண ராவகை நின்ற அரனெறி
பாய்ந்துணர் வார் அரன் சேவடி கைதொழு
தேய்ந்துணர் செய்வதோர் இன்பமு மாமே`,
    transliteration: `āyntuṇa rārkaḷiṉ āṉmāc caturpala
vāyntuṇa rāvakai niṉṟa araṉeṟi
pāyntuṇar vār araṉ cēvaṭi kaitoḻu
tēyntuṇar ceyvatōr iṉpamu māmē`,
    english: `1566: Adoration of Siva is Bliss
They that discriminated not
Knew not Hara's Path;
Their souls in myriad machinations caught,
The Truth saw not;
They that followed Hara's Path
Of a certain reached His Feet of Grace,
And joyed the Bliss, all senses uplifted.`,
    elaborationTamil: `இறைவனை அடைய தாங்கள் கடைபிடிக்கும் ஒரு வழி முறையை ஆராய்ந்து உணர்ந்தவர்கள் அதற்கான விதி முறைகளை பல விதமாக கூறுகின்றார்கள். ஆனால் இந்த விதி முறைகளை ஆராய்ந்து உணர முடியாத வகையில் தான் நிற்கின்றது இறைவனை அடைவதற்கான உண்மையான வழி முறை. அதனை தமக்குள் ஆராய்ந்து உணர்ந்து கொண்டவர்கள் இறைவனின் திருவடிகளை இரண்டு கைகளும் கூப்பி தொழுது வணங்கி தம்முடைய தூய்மையான அன்பினால் இறைவனை உணர்ந்து கொள்ளுவதே ஒரு பேரின்பம் ஆகும். கருத்து: இறைவனை அடைவதற்கு சமையங்கள் சொல்லுகின்ற பல விதமான விதி முறைகளை ஆராய்வதால் ஒரு பயனும் இல்லை. அன்பினால் தமக்குள் ஆராய்ந்து உணருவதே இறைவனை அடைவதற்கான உண்மையான வழியாகும்.`,
  },
  {
    id: 1568, tantraId: 5, verseNumber: 1567,
    tamil: `சைவ சமயத் தனிநா யகன்நந்தி
உய்ய வகுத்த குருநெறி ஒன்றுண்டு
தெய்வச் சிவநெறி சன்மார்க்கஞ் சேர்ந்துய்ய
வையத் துளார்க்குவகுத்துவைத் தானே`,
    transliteration: `caiva camayat taṉinā yakaṉnanti
uyya vakutta kuruneṟi oṉṟuṇṭu
teyvac civaneṟi caṉmārkkañ cērntuyya
vaiyat tuḷārkkuvakuttuvait tāṉē`,
    english: `1567: Saiva Path was Laid by Holy Nandi
The Holy Nandi, the acclaimed Master of Saiva Faith
Has showed a Way-the Master's way of Redemption;
That, divine Path of Saiva
He did chalk out for those here below
To walk in Sanmarga's trail
And be for ever free.`,
    elaborationEnglish: `Holy Nandi, the Master of Saiva Faith, laid the divine path of Saivam as the sure way to the soul's liberation. Discriminate knowledge draws the jiva in Hara’s path. They who walk in that path will surely reach His Feet of Grace and savour Siva bliss.`,
    elaborationTamil: `சைவ சமயத்திற்கு தனிப் பெரும் தலைவனாகவும் குரு நாதனாகவும் இருக்கின்ற இறைவன் அனைத்து உயிர்களும் முக்தியை அடைவதற்காக வகுத்து அருளிய வழி முறையில் அன்பு ஒன்று மட்டுமே இருக்கின்றது. அதுவே தெய்வீகமான இறைவனை அடைவதற்கான வழி முறையாகும். உண்மை வழி முறைகள் அனைத்தும் அதனோடு சேர்ந்தே உலகத்தில் உள்ள அனைத்து உயிர்களுக்கும் அதனதன் தகுதிக்கு ஏற்றவாறு பல வழி முறைகளாக பிரித்து வைத்து அருளினான் இறைவன்.`,
  },
  {
    id: 1569, tantraId: 5, verseNumber: 1568,
    tamil: `இத்தவம் அத்தவம் என்றிரு பேரிடும்
பித்தரைக் காணின் நகுமெங்கள் பேர்நந்தி
எத்தவ மாகிலென் எங்குப் பிறக்கிலென்
ஒத்துணர் வார்க்கொல்லை யூர்புக லாமே`,
    transliteration: `ittavam attavam eṉṟiru pēriṭum
pittaraik kāṇiṉ nakumeṅkaḷ pērnanti
ettava mākileṉ eṅkup piṟakkileṉ
ottuṇar vārkkollai yūrpuka lāmē`,
    english: `1568: Attune to Infinity
This the right Faith, that the true Faith
When my Lord Nandi thus sees
Mad men in two contend
He smiles in pity;
What though the form of Faith?
What though the place of Birth?
They with mind to infinity attuned
Sure enter the City of God.`,
    elaborationEnglish: `Siva smiles in pity at the mad men who contend about faiths. To attune to infinity is to reach the ‘City of God’.`,
    elaborationTamil: `இந்த தவம் சிறந்தது அந்த தவம் சிறப்பு இல்லாதது என்று நன்மை தீமை என்று இரண்டு விதமான பெயர்களை வைக்கின்ற பைத்தியக்காரர்களை எங்களின் பெருமை மிக்க குருநாதனாகிய இறைவன் கண்டு கொள்வது இல்லை. எந்த தவத்தை கடைபிடித்தால் என்ன? இந்த உலகத்தில் எந்த இடத்தில் எந்த உயிராக பிறந்திருந்தால் என்ன? அனைத்து உயிர்களிலும் அன்பின் வடிவமாக இறைவன் ஒருவனே இருக்கின்றான் என்பதை உணருபவர்களுக்கு உடனடியாக முக்திக்குள் நுழைய முடியும்.`,
  },
  {
    id: 1570, tantraId: 5, verseNumber: 1569,
    tamil: `ஆமே பிரான்முகம் ஐந்தொடு மாருயிர்
ஆமே பிரானுக் கதோமுக மாறுள
தாமே பிரானுக்குந் தன்சிர மாலைக்கும்
நாமே பிரானுக்கு நரரியல் பாமே`,
    transliteration: `āmē pirāṉmukam aintoṭu māruyir
āmē pirāṉuk katōmuka māṟuḷa
tāmē pirāṉukkun taṉcira mālaikkum
nāmē pirāṉukku narariyal pāmē`,
    english: `1569: Siva is Inclusive of Jiva
Siva has faces five
And with His downward looking visage for Jiva,
He has faces six in all;
The Lord by Himself All
Sports the garland of heads
That verily is the Human Aspect
Of the Godly One.`,
    elaborationEnglish: `Siva has six faces (even as there are six faiths). One Face (Athomukha) looks downward for jiva’s liberation.`,
    elaborationTamil: `அனைத்திற்கும் தலைவனாகிய இறைவனுக்கு ஐந்து திரு முகங்களோடு ஆறாவது முகமான அதோ முகமாக அண்ட சராசரங்களும் அதிலுள்ள அனைத்து உயிர்களுமே இருக்கின்றன. இந்த உலகத்தில் இருக்கின்ற உயிர்களால் அழைக்கப் படுகின்ற பலவாறான பெயர்களே இறைவன் தனது திருக்கழுத்தில் அணிந்து இருக்கின்ற மண்டையோட்டு மாலையாக இருக்கின்றது. இவையெல்லாம் மாயையை தமது இயல்பாக கொண்ட மனிதர்களால் பாவனை செய்யப் பட்ட உருவகங்களே தவிர இறைவனுக்கு என்று தனியாக ஒரு பெயரோ உருவமோ அல்லது தன்மையோ கிடையாது. கருத்து: இறைவனை அடைவதற்கு இருக்கின்ற ஆறு விதமான வழிகளில் செல்லுகின்ற உயிர்கள் தங்களின் மாயையால் இறைவனுக்கு பல விதமான பெயர்களையும் உருவங்களையும் பாவனை செய்து வழி படுகின்றன. அனைத்து பெயர்களும் உருவங்களும் ஒரே பரம் பொருளையே குறிக்கின்றது. இறைவனுடைய ஆறு முகங்கள்: ஈசானம் தற்புருடம் அகோரம் வாமதேவம் சத்யோ ஜாதம் அதோ முகம்`,
  },
  {
    id: 1571, tantraId: 5, verseNumber: 1570,
    tamil: `ஆதிப்பிரானுல கேழும் அளந்தவன்
ஓதக் கடலும் உயிர்களு மாய்நிற்கும்
பேதிப் பிலாமையின் நின்ற பராசத்தி
ஆதிக்கட் டெய்வமும் அந்தமு மாமே`,
    transliteration: `ātippirāṉula kēḻum aḷantavaṉ
ōtak kaṭalum uyirkaḷu māyniṟkum
pētip pilāmaiyiṉ niṉṟa parācatti
ātikkaṭ ṭeyvamum antamu māmē`,
    english: `1570: Lord is Beginning and End
The Primal Lord spanned the worlds seven
He stands as the sea and the myriad life here below,
And with Parasakti pervades all
In Union that no separateness knows
Verily, God is the Beginning and End of All.`,
    elaborationEnglish: `Mantras 1570 & 1571

With Parasakti, the Primal Lord pervades all Seven Worlds. He is the Beginning and End of all. The immortal beings, devas and Vidyadharas sought Him, but in vain. Pursuit through the proven path of Siva grants realisation of bliss here and hereafter.`,
    elaborationTamil: `ஆதியிலிருந்தே இருக்கின்ற தலைவனாகிய இறைவனே ஏழு உலகங்களையும் அவற்றின் தேவைக்கு ஏற்ப அளந்து படைத்தான். அலைகளால் பேரிரைச்சல் கொண்டு இருக்கின்ற கடல்களும் அது சூழ்ந்து நிற்கின்ற உலகத்தில் வாழ்கின்ற உயிர்களும் ஆகிய அனைத்துமாக அவனே நிற்கின்றான். அவை அனைத்தில் இருந்தும் வேறு பட்டு இல்லாதவனாக ஒன்றாகவே கலந்து நிற்கின்ற இறைவனே அசையும் சக்தியாகவும் இருந்து அனைத்தையும் இயக்குகின்றான். ஆதியிலிருந்தே அனைத்தையும் பார்க்கின்றவனாகவும் பார்க்கப் படுகின்ற பொருளாகவும் இருக்கின்ற தெய்வமாகவும் அனைத்தையும் ஊழிக் காலத்தில் அழிக்கின்ற தெய்வமாகவும் அவனே இருக்கின்றான். கருத்து: உயிர்களுக்குள் இருக்கின்ற இறைவனே உயிர்கள் வெளிப்புறத்தில் பார்க்கின்ற அனைத்துமாகவும் இருக்கின்றான் அனைத்தையும் இயக்குகின்றான் என்பதை உணர்ந்து வழி படுதலே அவனை அடைவதற்கு எளிதான வழியாகும்.`,
  },
  {
    id: 1572, tantraId: 5, verseNumber: 1571,
    tamil: `ஆய்ந்தறி வார்கள் அமரர்வித் தியாதரர்
ஆய்ந்தறி யாவண்ணம் நின்ற அரனெறி
ஆய்ந்தறிந் தேனவன் சேவடி கைதொழ
ஆய்ந்தறிந் தேனிம்மை அம்மைகண் டேனே`,
    transliteration: `āyntaṟi vārkaḷ amararvit tiyātarar
āyntaṟi yāvaṇṇam niṉṟa araṉeṟi
āyntaṟin tēṉavaṉ cēvaṭi kaitoḻa
āyntaṟin tēṉimmai ammaikaṇ ṭēṉē`,
    english: `1571: The Path of Siva Leads to Bliss
The immortal Beings, Devas and Vidyadaras,
Sought after Him, but knew Him not;
But pursuing the proven path of Siva
I reached His Feet of Grace to adore
And so realized the bliss of Here and Hereafter.`,
    elaborationTamil: `இறைவனை ஆராய்ந்து அறிந்தவர்களே அமரர்களாகவும் உண்மை ஞானமும் உலக ஞானமும் பெற்ற ஞானிகளாகவும் இருக்கின்றார்கள். ஆனாலும் ஆராய்ந்து அறிந்து கொள்ள முடியாத தன்மையை உடையவனாக நின்று அனைத்தையும் காக்கின்ற இறைவனை அடைகின்ற வழி முறை அன்பினால் உணர்கின்ற வழி முறையாகும். அப்படிப் பட்ட இறைவனை யானும் அன்பினால் ஆராய்ந்து அறிந்து கொண்டு அவனின் திருவடிகளை எமது இரண்டு கைகளையும் கூப்பி தொழுது வணங்கி எமக்குள்ளே ஆராய்ந்து அறிந்து கொண்டோம். அது எப்படி என்றால் அன்பின் வடிவமாகிய இறைவனின் சக்தியே எமக்குள் இருக்கின்ற மனமாகவும் அதன் தன்மைகளாகவும் எமக்குள் இயங்குகின்ற அனைத்துமாகவும் இருந்து எமக்கு காண்பித்தை யாம் கண்டு கொண்டோம்.`,
  },
  {
    id: 1573, tantraId: 5, verseNumber: 1572,
    tamil: `அறியவொண் ணாதவ் வுடம்பின் பயனை
அறியவொண் ணாத அறுவகை யாக்கி
அறியவொண் ணாத அறுவகைக் கோசத்
தறியவொண் ணாததோர் அண்டம் பதிந்ததே`,
    transliteration: `aṟiyavoṇ ṇātav vuṭampiṉ payaṉai
aṟiyavoṇ ṇāta aṟuvakai yākki
aṟiyavoṇ ṇāta aṟuvakaik kōcat
taṟiyavoṇ ṇātatōr aṇṭam patintatē`,
    english: `1572: Macrocosm in Microcosm-A Mystery
Baffling indeed is the mystery of Life's Goal
Baffling it is, why into the six systems was it made;
A baffling mystery far,
How into the shedding sheaths of this body microcosm
Got imprinted a veritable macrocosm.`,
    elaborationEnglish: `Life's goal is the realisation of the macrocosm in the microcosm — the Over-Soul in the self-soul—the mysterium tremendum.`,
    elaborationTamil: `அறிந்து கொள்ள முடியாத உடம்பின் உண்மையான பயனாகிய அக வழிபாட்டின் மூலம் இறைவனை அடைவதை உணர்ந்து, இறைவனை அடைவதற்கான ஆறு விதமான வழி முறைகளில் தங்களின் பக்குவத்து ஏற்ற ஒரு வழி முறையை தேர்ந்து எடுத்து அதில் முழுமை பெற்று அந்த முறையின் மூலம் கிடைக்கின்ற தம்மை முழுவதும் மூடியிருக்கும் பாதுகாப்பு அரனாக இருக்கின்ற உறையை பெற்று, ஒரு அண்டத்தையே தமது உடம்பிற்குள் பதித்து காணுவதே இறைவனை அடைவதற்கான வழி முறையாகும்.`,
  },
];
